            {
                var existingFileAttachmentModel = await GetFileAttachmentByIdForWriteAsync(fileAttachmentId);
                if (!existingFileAttachmentModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(existingFileAttachmentModel);
