                if (visionBoardSessionPictures == null)
                {
                    return log.ErrorAndReturnListModel<VisionBoardSessionPictureModel>($"Unable to Create Vision Board Session Pictures", new ReturnErrorItem("", "Vision Board Session Pictures information is not valid"));
