                var lst = new List<VisionBoardSessionPictureModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var visionBoardSessionPicture in visionBoardSessionPictures.NewVisionBoardSessionPictures)
                    {
                        var cResult = await CreateVisionBoardSessionPictureAsync(visionBoardSessionPicture);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<VisionBoardSessionPictureModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<VisionBoardSessionPictureModel>($"Unexpected error when creating Vision Board Session Pictures", new { visionBoardSessionPictures }, ex);
            }
        }

