        public async Task<ReturnModel<VisionBoardSessionPictureModel>> UpdateVisionBoardSessionPictureAsync(VisionBoardSessionPictureUpdateModel visionBoardSessionPicture)
        {
            try
            {
                if (visionBoardSessionPicture == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>($"Unable to update Vision Board Session Picture", new ReturnErrorItem("", "Vision Board Session Picture information is not valid"));
                }

                var existingVisionBoardSessionPictureModel = await GetVisionBoardSessionPictureByIdForWriteAsync(visionBoardSessionPicture.VisionBoardSessionPictureId);
                if (!existingVisionBoardSessionPictureModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>(existingVisionBoardSessionPictureModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(visionBoardSessionPicture.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>(errorStr);
                }

                visionBoardSessionPicture.CreatedByUserId = existingVisionBoardSessionPictureModel.Model.CreatedByUserId;
                visionBoardSessionPicture.CreatedDate = existingVisionBoardSessionPictureModel.Model.CreatedDate;
                visionBoardSessionPicture.IsDeleted = existingVisionBoardSessionPictureModel.Model.IsDeleted;
                visionBoardSessionPicture.UserId = existingVisionBoardSessionPictureModel.Model.UserId;

                var errorList = await IsVisionBoardSessionPictureModelValidForUpdateAsync(visionBoardSessionPicture);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>($"Unable to update Vision Board Session Picture", errorList);
                }

                var item = objectMapperService.VisionBoardSessionPictureUpdateModelToVisionBoardSessionPicture(visionBoardSessionPicture);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateVisionBoardSessionPictureAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Vision Board Session Picture");
                    }

                    //await CreateOrUpdateVisionBoardSessionPictureDependentsAsync(visionBoardSessionPicture)

                    await trx.CompleteAsync();
                }

                await auditService.VisionBoardSessionPictureUpdatedAsync(visionBoardSessionPicture.VisionBoardSessionPictureId);

                var view = await manifestRepository.GetVisionBoardSessionPictureViewByIdAsync(visionBoardSessionPicture.VisionBoardSessionPictureId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>($"Unable to find the Vision Board Session Picture", new { visionBoardSessionPicture.VisionBoardSessionPictureId });
                }

                return this.ConvertToItem(view, objectMapperService.VisionBoardSessionPictureViewToVisionBoardSessionPictureModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>($"Unexpected error when updating Vision Board Session Picture", new { visionBoardSessionPicture?.VisionBoardSessionPictureId }, ex);
            }
        }

