        public Task<List<ReturnErrorItem>> IsVisionBoardSessionPictureModelValidForCreateAsync(VisionBoardSessionPictureUpdateModel visionBoardSessionPictureModel)
        {
            return IsVisionBoardSessionPictureModelValidForAllAsync(true, visionBoardSessionPictureModel);
