        public Task<List<ReturnErrorItem>> IsVisionBoardSessionPictureModelValidForUpdateAsync(VisionBoardSessionPictureUpdateModel visionBoardSessionPictureModel)
        {
            return IsVisionBoardSessionPictureModelValidForAllAsync(false, visionBoardSessionPictureModel);
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardSessionPictureModelValidForAllAsync(bool isCreate, VisionBoardSessionPictureUpdateModel visionBoardSessionPictureModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (visionBoardSessionPictureModel.VisionBoardSessionPictureId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Session Picture Identifier is not valid"));
                }
            }
            else
            {
                if (visionBoardSessionPictureModel.VisionBoardSessionPictureId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Session Picture Unique Identifier is not valid"));
                }
            }

            var visionBoardSessionItem = await manifestRepository.GetVisionBoardSessionViewByIdAsync(visionBoardSessionPictureModel.VisionBoardSessionId);
            if (visionBoardSessionItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the VisionBoardSession Information"));
                return result;
            }

            if (visionBoardSessionItem.UserId != visionBoardSessionPictureModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this VisionBoardSession Information"));
                return result;
            }


            var visionBoardPictureItem = await manifestRepository.GetVisionBoardPictureViewByIdAsync(visionBoardSessionPictureModel.VisionBoardPictureId);
            if (visionBoardPictureItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the VisionBoardPicture Information"));
                return result;
            }

            if (visionBoardPictureItem.UserId != visionBoardSessionPictureModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this VisionBoardPicture Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(visionBoardSessionPictureModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != visionBoardSessionPictureModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!ValidationUtils.IsLongValid(visionBoardSessionPictureModel.VisionBoardSessionId))
            {
                result.Add(new ReturnErrorItem("VisionBoardSessionId", "VisionBoardSession cannot be empty"));
            }
            else
            {
                var itemForVisionBoardSession = await manifestRepository.GetVisionBoardSessionByIdAsync(visionBoardSessionPictureModel.VisionBoardSessionId);
                if (itemForVisionBoardSession == null)
                {
                    result.Add(new ReturnErrorItem("VisionBoardSessionId", "VisionBoardSession is not available"));
                }
                else
                {
                    if (itemForVisionBoardSession.UserId != visionBoardSessionPictureModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("VisionBoardSessionId", "VisionBoardSession does not belong to you."));
                    }
                }
            }
            if (!DateUtils.IsValidDate(visionBoardSessionPictureModel.VisionBoardSessionPictureDate))
            {
                result.Add(new ReturnErrorItem("VisionBoardSessionPictureDate", $"VisionBoardSessionPictureDate is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(visionBoardSessionPictureModel.VisionBoardPictureId))
            {
                result.Add(new ReturnErrorItem("VisionBoardPictureId", "VisionBoardPicture cannot be empty"));
            }
            else
            {
                var itemForVisionBoardPicture = await manifestRepository.GetVisionBoardPictureByIdAsync(visionBoardSessionPictureModel.VisionBoardPictureId);
                if (itemForVisionBoardPicture == null)
                {
                    result.Add(new ReturnErrorItem("VisionBoardPictureId", "VisionBoardPicture is not available"));
                }
                else
                {
                    if (itemForVisionBoardPicture.UserId != visionBoardSessionPictureModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("VisionBoardPictureId", "VisionBoardPicture does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(visionBoardSessionPictureModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(visionBoardSessionPictureModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != visionBoardSessionPictureModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



