        public async Task<ReturnModel<bool>> UploadVisionBoardSessionPictureFileAsync(long visionBoardSessionPictureId, FileStreamModel streamModel)
        {
            try
            {
                var visionBoardSessionPicture = await GetVisionBoardSessionPictureByIdForWriteAsync(visionBoardSessionPictureId);
                if (!visionBoardSessionPicture.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(visionBoardSessionPicture);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(visionBoardSessionPicture.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(visionBoardSessionPicture.Model.UserId, visionBoardSessionPicture.Model.VisionBoardSessionPictureId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(visionBoardSessionPicture.Model.UserId, visionBoardSessionPicture.Model.VisionBoardSessionPictureId, streamModel.FileName);
                        await productRepository.UpdateVisionBoardSessionPictureFilePathAsync(visionBoardSessionPicture.Model.VisionBoardSessionPictureId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(visionBoardSessionPicture.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Vision Board Session Picture File", ex);
            }
        }

