        }

        public async Task CreateOrUpdateVisionBoardSessionPictureDependentsAsync(VisionBoardSessionPictureUpdateModel model)
        {
            if (model.NewVisionBoardSessionPictureXYZZYXModels == null)
                model.NewVisionBoardSessionPictureXYZZYXModels = new List<VisionBoardSessionPictureXYZZYXCreateModel>();

            if (model.ExistingVisionBoardSessionPictureXYZZYXModels == null)
                model.ExistingVisionBoardSessionPictureXYZZYXModels = new List<VisionBoardSessionPictureXYZZYXUpdateModel>();

            var dbExistingVisionBoardSessionPictures = await manifestRepository.GetVisionBoardSessionPictureXYZZYXsByVisionBoardSessionPictureIdAsync(model.VisionBoardSessionPictureId);
            if (!dbExistingVisionBoardSessionPictures.IsNullOrEmpty())
            {
                var dbExistingVisionBoardSessionPictureIds = dbExistingVisionBoardSessionPictures.SelectToList(x => x.VisionBoardSessionPictureXYZZYXId);
                var modelExistingVisionBoardSessionPictureIds = model.ExistingVisionBoardSessionPictureXYZZYXModels.SelectToList(x => x.VisionBoardSessionPictureXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingVisionBoardSessionPictures.Where(x => !modelExistingVisionBoardSessionPictureIds.Contains(x.VisionBoardSessionPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkVisionBoardSessionPictureXYZZYXAsDeletedByIdAsync(x.VisionBoardSessionPictureXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingVisionBoardSessionPictureXYZZYXModels.Where(x => dbExistingVisionBoardSessionPictureIds.Contains(x.VisionBoardSessionPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.VisionBoardSessionPictureId = model.VisionBoardSessionPictureId;
                    var result = await UpdateVisionBoardSessionPictureXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewVisionBoardSessionPictureXYZZYXModels)
            {
                x.VisionBoardSessionPictureId = model.VisionBoardSessionPictureId;
                var result = await CreateVisionBoardSessionPictureXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableVisionBoardSessionPictureByIdAsync(long visionBoardSessionPictureId)
        {
            try
            {
                var existingVisionBoardSessionPictureModel = await GetVisionBoardSessionPictureByIdForWriteAsync(visionBoardSessionPictureId);
                if (!existingVisionBoardSessionPictureModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionPictureModel>(existingVisionBoardSessionPictureModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingVisionBoardSessionPictureModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableVisionBoardSessionPictureByIdAsync(existingVisionBoardSessionPictureModel.Model.VisionBoardSessionPictureId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.VisionBoardSessionPictureEnabledAsync(visionBoardSessionPictureId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Vision Board Session Picture", new { visionBoardSessionPictureId }, ex);
            }
        }

