        public async Task<ReturnModel<bool>> AssociateXYZZYXWithVisionBoardSessionPictureAsync(VisionBoardSessionPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardSessionPictureWithVisionBoardSessionPictureAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Session Picture association is invalid", errorLst);
                }

                if (await manifestRepository.DoesVisionBoardSessionPictureWithXYZZYXAssociationExistsAsync(model.VisionBoardSessionPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Session Picture is already associated with the Vision Board Session Picture", new { model.VisionBoardSessionPictureId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateVisionBoardSessionPictureWithXYZZYXAsync(model.VisionBoardSessionPictureId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Vision Board Session Picture with XYZZYX", new { model.VisionBoardSessionPictureId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Vision Board Session Picture with XYZZYX", new { model.VisionBoardSessionPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithVisionBoardSessionPictureAsync(VisionBoardSessionPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardSessionPictureWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Session Picture association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesVisionBoardSessionPictureWithXYZZYXAssociationExistsAsync(model.VisionBoardSessionPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Session Picture is not associated with the Vision Board Session Picture", new { model.VisionBoardSessionPictureId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateVisionBoardSessionPictureWithVisionBoardSessionPictureAsync(model.VisionBoardSessionPictureId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Vision Board Session Picture with the Vision Board Session Picture", new { model.VisionBoardSessionPictureId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Vision Board Session Picture with the Vision Board Session Picture", new { model.VisionBoardSessionPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardSessionPictureWithXYZZYXAssociationValidAsync(VisionBoardSessionPictureXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.VisionBoardSessionPictureId == 0)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Session Picture is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Vision Board Session Picture  is not valid"));
                return result;
            }

            var entity = await GetVisionBoardSessionPictureForWriteByIdAsync(model.VisionBoardSessionPictureId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Session Picture information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Session Pictures does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportVisionBoardSessionPictureAsync(VisionBoardSessionPictureImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Vision Board Session Picture Import Info is not provided");
                }

                if (model.VisionBoardSessionPictures == null || model.VisionBoardSessionPictures.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Vision Board Session Pictures Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.VisionBoardSessionPictures)
                {
                    var prod = await wipService.GetVisionBoardSessionPictureByExternalIdentifierAsync(item.VisionBoardSessionPictureIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        VisionBoardSessionPictureCreateModel visionBoardSessionPictureCreateModel = new VisionBoardSessionPictureCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedVisionBoardSessionPicture = await CreateVisionBoardSessionPictureAsync(visionBoardSessionPictureCreateModel);
                        if (!newlyCreatedVisionBoardSessionPicture.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedVisionBoardSessionPicture.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedVisionBoardSessionPicture.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        VisionBoardSessionPictureUpdateModel visionBoardSessionPictureUpdateModel = new VisionBoardSessionPictureUpdateModel
                        {
                        };

                        //update product
                        var updatedVisionBoardSessionPictureModel = await wipService.UpdateVisionBoardSessionPictureAsync(visionBoardSessionPictureUpdateModel);
                        if (!updatedVisionBoardSessionPictureModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModel<ImportStatusModel>("Unexpected error occurred when importing Vision Board Session Picture Info", ex);
            }
        }

        public async Task<ReturnListModel<VisionBoardSessionPictureExportModel>> ExportVisionBoardSessionPictureAsync(VisionBoardSessionPictureExportParameter filter, bool isTest)
        {
            try
            {
                var visionBoardSessionPictureCount = await manifestRepository.GetVisionBoardSessionPictureCountAsync(filter);
                if (visionBoardSessionPictureCount == 0)
                {
                    return log.ErrorAndReturnListModel<VisionBoardSessionPictureExportModel>("No Vision Board Session Picture available for export.");
                }

                var itemsToReturn = new List<VisionBoardSessionPictureExportModel>();
                var numberOfLoops = (visionBoardSessionPictureCount / pageSize) + 1;
                for (var i = 0; i < numberOfLoops; ++i)
                {
                    var dataResult = await wipService.GetUserViewListAsync(new VisionBoardSessionPictureSearchCriteria { Page = i, PageSize = pageSize, Keyword = filter.Keyword });
                    if (dataResult.IsSuccess)
                    {
                        return log.ErrorAndReturnListModel<VisionBoardSessionPictureExportModel>(dataResult);
                    }

