        public async Task<ReturnListModel<CategoryModel>> CreateMultipleCategoryAsync(MultipleCategoryCreateModel categorys)
        {
            try
            {
                if (categorys == null)
                {
                    return log.ErrorAndReturnListModel<CategoryModel>($"Unable to Create Categorys", new ReturnErrorItem("", "Categorys information is not valid"));
                }

                if (categorys.NewCategorys.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<CategoryModel>($"Unable to Create Categorys", new ReturnErrorItem("", "Categorys information is not provided"));
                }

                var lst = new List<CategoryModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var category in categorys.NewCategorys)
                    {
                        var cResult = await CreateCategoryAsync(category);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<CategoryModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<CategoryModel>($"Unexpected error when creating Categorys", new { categorys }, ex);
            }
        }

        public async Task<ReturnModel<CategoryModel>> CreateCategoryAsync(CategoryCreateModel category)
        {
            try
            {
                if (category == null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to create Category", new ReturnErrorItem("", "Category information is not valid"));
                }

                if (!await permissionService.IsUserSuperAdmin())
                {
                    category.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                //var companyModel = await companyService.GetCompanyByIdForReadAsync(category.UserId);
                //if (!companyModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<CategoryModel>(companyModel);
                //}
                //
                //var movieModel = await GetMovieByIdForReadAsync(category.MovieId);
                //if (!movieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<CategoryModel>(movieModel);
                //}
                //


                /*var ignoreCode = false;
                if (category.CategoryCode.IsNullOrEmpty())
                {
                    ignoreCode = true;
                    category.CategoryCode = StringConstants.PrefixForCode.Category + Guid.NewGuid().ToString();
                }
                */

                var errorList = await IsCategoryModelValidForCreateAsync(category);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to create Category", errorList);
                }

                category.IsDeleted = false;

                var item = objectMapperService.CategoryCreateModelToCategory(category);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Category");
                    }

                    //await CreateOrUpdateCategoryDependentsAsync(category)

                    /*if (ignoreCode)
                    {
                        if (!await manifestRepository.UpdateCategoryCodeAsync(item.UserId, item.CategoryId, StringConstants.PrefixForCode.Category + item.CategoryId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Category Code", item);
                        }
                    }*/

                    await trx.CompleteAsync();
                }

                await auditService.CategoryCreatedAsync(item.CategoryId);

                var view = await manifestRepository.GetCategoryViewByIdAsync(item.CategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to find the Category", new { item.CategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.CategoryViewToCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<CategoryModel>($"Unexpected error when creating Category", new { category?.CategoryId }, ex);
            }
        }

        public async Task<ReturnModel<CategoryModel>> UpdateCategoryAsync(CategoryUpdateModel category)
        {
            try
            {
                if (category == null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to update Category", new ReturnErrorItem("", "Category information is not valid"));
                }

                var existingCategoryModel = await GetCategoryByIdForWriteAsync(category.CategoryId);
                if (!existingCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<CategoryModel>(existingCategoryModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(category.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<CategoryModel>(errorStr);
                }

                if (canAssign)
                {
                    category.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                category.CreatedByUserId = existingCategoryModel.Model.CreatedByUserId;
                category.CreatedDate = existingCategoryModel.Model.CreatedDate;
                category.IsDeleted = existingCategoryModel.Model.IsDeleted;
                category.UserId = existingCategoryModel.Model.UserId;
                //category.MovieId = existingCategoryModel.Model.MovieId;
                //category.ProfileImageActualFileName = existingCategoryModel.Model.ProfileImageActualFileName;
                //category.ProfileImageLocation = existingCategoryModel.Model.ProfileImageLocation;



                var errorList = await IsCategoryModelValidForUpdateAsync(category);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to update Category", errorList);
                }

                var item = objectMapperService.CategoryUpdateModelToCategory(category);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Category");
                    }

                    //await CreateOrUpdateCategoryDependentsAsync(category)

                    await trx.CompleteAsync();
                }

                await auditService.CategoryUpdatedAsync(category.CategoryId);

                var view = await manifestRepository.GetCategoryViewByIdAsync(category.CategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<CategoryModel>($"Unable to find the Category", new { category.CategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.CategoryViewToCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<CategoryModel>($"Unexpected error when updating Category", new { category?.CategoryId }, ex);
            }
        }

