        public Task<List<ReturnErrorItem>> IsCategoryModelValidForCreateAsync(CategoryUpdateModel categoryModel)
        {
            return IsCategoryModelValidForAllAsync(true, categoryModel);
        }

        public Task<List<ReturnErrorItem>> IsCategoryModelValidForUpdateAsync(CategoryUpdateModel categoryModel)
        {
            return IsCategoryModelValidForAllAsync(false, categoryModel);
        }

        public async Task<List<ReturnErrorItem>> IsCategoryModelValidForAllAsync(bool isCreate, CategoryUpdateModel categoryModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsCategoryNameAlreadyExistsForOtherCategoryAsync(categoryModel.CategoryName, categoryModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Category already exists"));
                }

                if (categoryModel.CategoryId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Category Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsCategoryNameAlreadyExistsForOtherCategoryAsync(categoryModel.CategoryId, categoryModel.CategoryName, categoryModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Category already exists"));
                }

                if (categoryModel.CategoryId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Category Unique Identifier is not valid"));
                }
            }

            var defaultCategoryItem = await manifestRepository.GetDefaultCategoryViewByIdAsync(categoryModel.DefaultCategoryId);
            if (defaultCategoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the DefaultCategory Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(categoryModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != categoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!ValidationUtils.IsLongValid(categoryModel.DefaultCategoryId))
            {
                result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory cannot be empty"));
            }
            else
            {
                var itemForDefaultCategory = await manifestRepository.GetDefaultCategoryByIdAsync(categoryModel.DefaultCategoryId);
                if (itemForDefaultCategory == null)
                {
                    result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory is not available"));
                }
            }

            if (categoryModel.CategoryName != null && categoryModel.CategoryName.Length > CategoryModel.COLUMN_SIZE_CategoryName)
            {
                result.Add(new ReturnErrorItem("CategoryName", $"CategoryName size should not exceed {CategoryModel.COLUMN_SIZE_CategoryName}"));
            }
            if (categoryModel.CategoryName == null)
            {
                result.Add(new ReturnErrorItem("CategoryName", "CategoryName is required "));
            }
            if (!ValidationUtils.IsLongValid(categoryModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(categoryModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != categoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



