            }
        }

        public async Task<ReturnModel<FileStreamModel>> GetCategoryWordOrdPdfFileAsync(long categoryId, bool isPdf)
        {
            try
            {
                var view = await GetCategoryByIdForReadAsync(categoryId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the Category", new { categoryId });
                }

                var fileName = view.Model.SourceStoredFilePath;
                var docType = "Word";
                var docExt = ".docx";

                if (isPdf)
                {
                    fileName = view.Model.PreviewStoredFilePath;
                    docType = "Pdf";
                    docExt = ".pdf";
                }

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: {docType} file is not available.");
                }

                if (!await contractFileStorage.ExistsAsync(view.Model.UserId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: {docType} file is not available.");
                }

                var result = new FileStreamModel
                {
                    FileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"CategoryFile.{docType}" : view.Model.ActualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(view.Model.ActualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.UserId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for Category ", new { categoryId }, ex);
            }
        }

