        public async Task<ReturnModel<bool>> UploadCategoryFileAsync(long categoryId, FileStreamModel streamModel)
        {
            try
            {
                var category = await GetCategoryByIdForWriteAsync(categoryId);
                if (!category.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(category);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(category.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(category.Model.UserId, category.Model.CategoryId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(category.Model.UserId, category.Model.CategoryId, streamModel.FileName);
                        await productRepository.UpdateCategoryFilePathAsync(category.Model.CategoryId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(category.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Category File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearCategoryFileAsync(long categoryId)
        {
            try
            {
                var category = await GetCategoryByIdForWriteAsync(categoryId);
                if (!category.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(category);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearCategoryFilePathAsync(category.Model.CategoryId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(category.Model.UserId, category.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Category File", ex);
            }
        }

        public async Task CreateOrUpdateCategoryDependentsAsync(CategoryUpdateModel model)
        {
            if (model.NewCategoryXYZZYXModels == null)
                model.NewCategoryXYZZYXModels = new List<CategoryXYZZYXCreateModel>();

            if (model.ExistingCategoryXYZZYXModels == null)
                model.ExistingCategoryXYZZYXModels = new List<CategoryXYZZYXUpdateModel>();

            var dbExistingCategorys = await manifestRepository.GetCategoryXYZZYXsByCategoryIdAsync(model.CategoryId);
            if (!dbExistingCategorys.IsNullOrEmpty())
            {
                var dbExistingCategoryIds = dbExistingCategorys.SelectToList(x => x.CategoryXYZZYXId);
                var modelExistingCategoryIds = model.ExistingCategoryXYZZYXModels.SelectToList(x => x.CategoryXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingCategorys.Where(x => !modelExistingCategoryIds.Contains(x.CategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkCategoryXYZZYXAsDeletedByIdAsync(x.CategoryXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingCategoryXYZZYXModels.Where(x => dbExistingCategoryIds.Contains(x.CategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.CategoryId = model.CategoryId;
                    var result = await UpdateCategoryXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewCategoryXYZZYXModels)
            {
                x.CategoryId = model.CategoryId;
                var result = await CreateCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

