        public async Task<ReturnModel<bool>> AssociateXYZZYXWithCategoryAsync(CategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsCategoryWithCategoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Category association is invalid", errorLst);
                }

                if (await manifestRepository.DoesCategoryWithXYZZYXAssociationExistsAsync(model.CategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Category is already associated with the Category", new { model.CategoryId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateCategoryWithXYZZYXAsync(model.CategoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Category with XYZZYX", new { model.CategoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Category with XYZZYX", new { model.CategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithCategoryAsync(CategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsCategoryWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Category association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesCategoryWithXYZZYXAssociationExistsAsync(model.CategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Category is not associated with the Category", new { model.CategoryId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateCategoryWithCategoryAsync(model.CategoryId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Category with the Category", new { model.CategoryId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Category with the Category", new { model.CategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsCategoryWithXYZZYXAssociationValidAsync(CategoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.CategoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "Category is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Category  is not valid"));
                return result;
            }

            var entity = await GetCategoryForWriteByIdAsync(model.CategoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Category information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Categorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

