                var existingDailyAffirmationSessionModel = await GetDailyAffirmationSessionByIdForWriteAsync(dailyAffirmationSession.DailyAffirmationSessionId);
                if (!existingDailyAffirmationSessionModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionModel>(existingDailyAffirmationSessionModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(dailyAffirmationSession.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionModel>(errorStr);
                }

                if (canAssign)
                {
                    dailyAffirmationSession.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                dailyAffirmationSession.CreatedByUserId = existingDailyAffirmationSessionModel.Model.CreatedByUserId;
                dailyAffirmationSession.CreatedDate = existingDailyAffirmationSessionModel.Model.CreatedDate;
                dailyAffirmationSession.IsDeleted = existingDailyAffirmationSessionModel.Model.IsDeleted;
                dailyAffirmationSession.UserId = existingDailyAffirmationSessionModel.Model.UserId;
                //dailyAffirmationSession.MovieId = existingDailyAffirmationSessionModel.Model.MovieId;
                //dailyAffirmationSession.ProfileImageActualFileName = existingDailyAffirmationSessionModel.Model.ProfileImageActualFileName;
                //dailyAffirmationSession.ProfileImageLocation = existingDailyAffirmationSessionModel.Model.ProfileImageLocation;



                var errorList = await IsDailyAffirmationSessionModelValidForUpdateAsync(dailyAffirmationSession);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionModel>($"Unable to update Daily Affirmation Session", errorList);
                }

                var item = objectMapperService.DailyAffirmationSessionUpdateModelToDailyAffirmationSession(dailyAffirmationSession);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDailyAffirmationSessionAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Daily Affirmation Session");
                    }

                    //await CreateOrUpdateDailyAffirmationSessionDependentsAsync(dailyAffirmationSession)

                    await trx.CompleteAsync();
                }

                await auditService.DailyAffirmationSessionUpdatedAsync(dailyAffirmationSession.DailyAffirmationSessionId);

                var view = await manifestRepository.GetDailyAffirmationSessionViewByIdAsync(dailyAffirmationSession.DailyAffirmationSessionId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionModel>($"Unable to find the Daily Affirmation Session", new { dailyAffirmationSession.DailyAffirmationSessionId });
                }

                return this.ConvertToItem(view, objectMapperService.DailyAffirmationSessionViewToDailyAffirmationSessionModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DailyAffirmationSessionModel>($"Unexpected error when updating Daily Affirmation Session", new { dailyAffirmationSession?.DailyAffirmationSessionId }, ex);
            }
        }

