        public Task<List<ReturnErrorItem>> IsDailyAffirmationSessionModelValidForCreateAsync(DailyAffirmationSessionUpdateModel dailyAffirmationSessionModel)
        {
            return IsDailyAffirmationSessionModelValidForAllAsync(true, dailyAffirmationSessionModel);
        }

        public Task<List<ReturnErrorItem>> IsDailyAffirmationSessionModelValidForUpdateAsync(DailyAffirmationSessionUpdateModel dailyAffirmationSessionModel)
        {
            return IsDailyAffirmationSessionModelValidForAllAsync(false, dailyAffirmationSessionModel);
        }

        public async Task<List<ReturnErrorItem>> IsDailyAffirmationSessionModelValidForAllAsync(bool isCreate, DailyAffirmationSessionUpdateModel dailyAffirmationSessionModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (dailyAffirmationSessionModel.DailyAffirmationSessionId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Session Identifier is not valid"));
                }
            }
            else
            {
                if (dailyAffirmationSessionModel.DailyAffirmationSessionId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Session Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(dailyAffirmationSessionModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != dailyAffirmationSessionModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!DateUtils.IsValidDate(dailyAffirmationSessionModel.DailyAffirmationSessionDate))
            {
                result.Add(new ReturnErrorItem("DailyAffirmationSessionDate", $"DailyAffirmationSessionDate is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(dailyAffirmationSessionModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(dailyAffirmationSessionModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != dailyAffirmationSessionModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }
            if (dailyAffirmationSessionModel.AddedToFeedDate != null && !DateUtils.IsValidDate(dailyAffirmationSessionModel.AddedToFeedDate.Value))
            {
                result.Add(new ReturnErrorItem("AddedToFeedDate", $"AddedToFeedDate is not a valid date"));
            }


            return result.Count > 0 ? result : null;
        }



