        public async Task<ReturnModel<bool>> UploadDailyAffirmationSessionFileAsync(long dailyAffirmationSessionId, FileStreamModel streamModel)
        {
            try
            {
                var dailyAffirmationSession = await GetDailyAffirmationSessionByIdForWriteAsync(dailyAffirmationSessionId);
                if (!dailyAffirmationSession.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(dailyAffirmationSession);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(dailyAffirmationSession.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(dailyAffirmationSession.Model.UserId, dailyAffirmationSession.Model.DailyAffirmationSessionId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(dailyAffirmationSession.Model.UserId, dailyAffirmationSession.Model.DailyAffirmationSessionId, streamModel.FileName);
                        await productRepository.UpdateDailyAffirmationSessionFilePathAsync(dailyAffirmationSession.Model.DailyAffirmationSessionId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(dailyAffirmationSession.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Daily Affirmation Session File", ex);
            }
        }

