        public async Task CreateOrUpdateDailyAffirmationSessionDependentsAsync(DailyAffirmationSessionUpdateModel model)
        {
            if (model.NewDailyAffirmationSessionXYZZYXModels == null)
                model.NewDailyAffirmationSessionXYZZYXModels = new List<DailyAffirmationSessionXYZZYXCreateModel>();

            if (model.ExistingDailyAffirmationSessionXYZZYXModels == null)
                model.ExistingDailyAffirmationSessionXYZZYXModels = new List<DailyAffirmationSessionXYZZYXUpdateModel>();

            var dbExistingDailyAffirmationSessions = await manifestRepository.GetDailyAffirmationSessionXYZZYXsByDailyAffirmationSessionIdAsync(model.DailyAffirmationSessionId);
            if (!dbExistingDailyAffirmationSessions.IsNullOrEmpty())
            {
                var dbExistingDailyAffirmationSessionIds = dbExistingDailyAffirmationSessions.SelectToList(x => x.DailyAffirmationSessionXYZZYXId);
                var modelExistingDailyAffirmationSessionIds = model.ExistingDailyAffirmationSessionXYZZYXModels.SelectToList(x => x.DailyAffirmationSessionXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDailyAffirmationSessions.Where(x => !modelExistingDailyAffirmationSessionIds.Contains(x.DailyAffirmationSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDailyAffirmationSessionXYZZYXAsDeletedByIdAsync(x.DailyAffirmationSessionXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDailyAffirmationSessionXYZZYXModels.Where(x => dbExistingDailyAffirmationSessionIds.Contains(x.DailyAffirmationSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DailyAffirmationSessionId = model.DailyAffirmationSessionId;
                    var result = await UpdateDailyAffirmationSessionXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDailyAffirmationSessionXYZZYXModels)
            {
                x.DailyAffirmationSessionId = model.DailyAffirmationSessionId;
                var result = await CreateDailyAffirmationSessionXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

