                if (!existingDailyAffirmationSessionModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionModel>(existingDailyAffirmationSessionModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingDailyAffirmationSessionModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.DisableDailyAffirmationSessionByIdAsync(existingDailyAffirmationSessionModel.Model.DailyAffirmationSessionId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.DailyAffirmationSessionDisabledAsync(existingDailyAffirmationSessionModel.Model.DailyAffirmationSessionId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when disabling Daily Affirmation Session",new { dailyAffirmationSessionId }, ex);
            }
        }


