        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDailyAffirmationSessionAsync(DailyAffirmationSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationSessionWithDailyAffirmationSessionAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Session association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDailyAffirmationSessionWithXYZZYXAssociationExistsAsync(model.DailyAffirmationSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Session is already associated with the Daily Affirmation Session", new { model.DailyAffirmationSessionId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDailyAffirmationSessionWithXYZZYXAsync(model.DailyAffirmationSessionId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Daily Affirmation Session with XYZZYX", new { model.DailyAffirmationSessionId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Daily Affirmation Session with XYZZYX", new { model.DailyAffirmationSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDailyAffirmationSessionAsync(DailyAffirmationSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationSessionWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Session association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDailyAffirmationSessionWithXYZZYXAssociationExistsAsync(model.DailyAffirmationSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Session is not associated with the Daily Affirmation Session", new { model.DailyAffirmationSessionId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDailyAffirmationSessionWithDailyAffirmationSessionAsync(model.DailyAffirmationSessionId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Daily Affirmation Session with the Daily Affirmation Session", new { model.DailyAffirmationSessionId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Daily Affirmation Session with the Daily Affirmation Session", new { model.DailyAffirmationSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDailyAffirmationSessionWithXYZZYXAssociationValidAsync(DailyAffirmationSessionXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DailyAffirmationSessionId == 0)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Session is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Daily Affirmation Session  is not valid"));
                return result;
            }

            var entity = await GetDailyAffirmationSessionForWriteByIdAsync(model.DailyAffirmationSessionId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Session information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Sessions does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

