                if (dailyAffirmationSessionCategorys.NewDailyAffirmationSessionCategorys.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DailyAffirmationSessionCategoryModel>($"Unable to Create Daily Affirmation Session Categorys", new ReturnErrorItem("", "Daily Affirmation Session Categorys information is not provided"));
                }

                var lst = new List<DailyAffirmationSessionCategoryModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var dailyAffirmationSessionCategory in dailyAffirmationSessionCategorys.NewDailyAffirmationSessionCategorys)
                    {
                        var cResult = await CreateDailyAffirmationSessionCategoryAsync(dailyAffirmationSessionCategory);
                        if (!cResult.IsSuccess)
