                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DailyAffirmationSessionCategoryModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DailyAffirmationSessionCategoryModel>($"Unexpected error when creating Daily Affirmation Session Categorys", new { dailyAffirmationSessionCategorys }, ex);
