        public async Task<ReturnModel<DailyAffirmationSessionCategoryModel>> UpdateDailyAffirmationSessionCategoryAsync(DailyAffirmationSessionCategoryUpdateModel dailyAffirmationSessionCategory)
        {
            try
            {
                if (dailyAffirmationSessionCategory == null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionCategoryModel>($"Unable to update Daily Affirmation Session Category", new ReturnErrorItem("", "Daily Affirmation Session Category information is not valid"));
