                var existingDailyAffirmationSessionCategoryModel = await GetDailyAffirmationSessionCategoryByIdForWriteAsync(dailyAffirmationSessionCategory.DailyAffirmationSessionCategoryId);
                if (!existingDailyAffirmationSessionCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionCategoryModel>(existingDailyAffirmationSessionCategoryModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(dailyAffirmationSessionCategory.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionCategoryModel>(errorStr);
                }

                if (canAssign)
                {
                    dailyAffirmationSessionCategory.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                dailyAffirmationSessionCategory.CreatedByUserId = existingDailyAffirmationSessionCategoryModel.Model.CreatedByUserId;
                dailyAffirmationSessionCategory.CreatedDate = existingDailyAffirmationSessionCategoryModel.Model.CreatedDate;
                dailyAffirmationSessionCategory.IsDeleted = existingDailyAffirmationSessionCategoryModel.Model.IsDeleted;
                dailyAffirmationSessionCategory.UserId = existingDailyAffirmationSessionCategoryModel.Model.UserId;
                //dailyAffirmationSessionCategory.MovieId = existingDailyAffirmationSessionCategoryModel.Model.MovieId;
                //dailyAffirmationSessionCategory.ProfileImageActualFileName = existingDailyAffirmationSessionCategoryModel.Model.ProfileImageActualFileName;
                //dailyAffirmationSessionCategory.ProfileImageLocation = existingDailyAffirmationSessionCategoryModel.Model.ProfileImageLocation;



                var errorList = await IsDailyAffirmationSessionCategoryModelValidForUpdateAsync(dailyAffirmationSessionCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationSessionCategoryModel>($"Unable to update Daily Affirmation Session Category", errorList);
                }

                var item = objectMapperService.DailyAffirmationSessionCategoryUpdateModelToDailyAffirmationSessionCategory(dailyAffirmationSessionCategory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDailyAffirmationSessionCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Daily Affirmation Session Category");
                    }

                    //await CreateOrUpdateDailyAffirmationSessionCategoryDependentsAsync(dailyAffirmationSessionCategory)

                    await trx.CompleteAsync();
                }

                await auditService.DailyAffirmationSessionCategoryUpdatedAsync(dailyAffirmationSessionCategory.DailyAffirmationSessionCategoryId);

                var view = await manifestRepository.GetDailyAffirmationSessionCategoryViewByIdAsync(dailyAffirmationSessionCategory.DailyAffirmationSessionCategoryId);

                if (view == null)
