            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DailyAffirmationSessionCategoryModel>($"Unexpected error when updating Daily Affirmation Session Category", new { dailyAffirmationSessionCategory?.DailyAffirmationSessionCategoryId }, ex);
            }
        }

