            if (isCreate)
            {
                if (dailyAffirmationSessionCategoryModel.DailyAffirmationSessionCategoryId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Session Category Identifier is not valid"));
                }
            }
            else
            {
                if (dailyAffirmationSessionCategoryModel.DailyAffirmationSessionCategoryId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Session Category Unique Identifier is not valid"));
                }
            }

            var categoryItem = await manifestRepository.GetCategoryViewByIdAsync(dailyAffirmationSessionCategoryModel.CategoryId);
            if (categoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the Category Information"));
                return result;
            }

            if (categoryItem.UserId != dailyAffirmationSessionCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this Category Information"));
                return result;
            }


            var dailyAffirmationSessionItem = await manifestRepository.GetDailyAffirmationSessionViewByIdAsync(dailyAffirmationSessionCategoryModel.DailyAffirmationSessionId);
            if (dailyAffirmationSessionItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the DailyAffirmationSession Information"));
                return result;
            }

            if (dailyAffirmationSessionItem.UserId != dailyAffirmationSessionCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this DailyAffirmationSession Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(dailyAffirmationSessionCategoryModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != dailyAffirmationSessionCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!ValidationUtils.IsLongValid(dailyAffirmationSessionCategoryModel.CategoryId))
            {
                result.Add(new ReturnErrorItem("CategoryId", "Category cannot be empty"));
            }
            else
            {
                var itemForCategory = await manifestRepository.GetCategoryByIdAsync(dailyAffirmationSessionCategoryModel.CategoryId);
                if (itemForCategory == null)
                {
                    result.Add(new ReturnErrorItem("CategoryId", "Category is not available"));
                }
                else
                {
                    if (itemForCategory.UserId != dailyAffirmationSessionCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("CategoryId", "Category does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(dailyAffirmationSessionCategoryModel.DailyAffirmationSessionId))
            {
                result.Add(new ReturnErrorItem("DailyAffirmationSessionId", "DailyAffirmationSession cannot be empty"));
            }
            else
            {
                var itemForDailyAffirmationSession = await manifestRepository.GetDailyAffirmationSessionByIdAsync(dailyAffirmationSessionCategoryModel.DailyAffirmationSessionId);
                if (itemForDailyAffirmationSession == null)
                {
                    result.Add(new ReturnErrorItem("DailyAffirmationSessionId", "DailyAffirmationSession is not available"));
                }
                else
                {
                    if (itemForDailyAffirmationSession.UserId != dailyAffirmationSessionCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("DailyAffirmationSessionId", "DailyAffirmationSession does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(dailyAffirmationSessionCategoryModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(dailyAffirmationSessionCategoryModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != dailyAffirmationSessionCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



