        public async Task<ReturnModel<FileStreamModel>> GetDailyAffirmationSessionCategoryFileAsync(long dailyAffirmationSessionCategoryId)
        {
            try
            {
                var view = await GetDailyAffirmationSessionCategoryByIdForReadAsync(dailyAffirmationSessionCategoryId);

                if (!view.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"Unable to find the Daily Affirmation Session Category", new { dailyAffirmationSessionCategoryId });
                }

                var fileName = view.Model.SourceStoredFilePath;

                if (fileName.IsTrimmedStringNullOrEmpty())
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.UserId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"DailyAffirmationSessionCategoryFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.UserId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for Daily Affirmation Session Category ", new { dailyAffirmationSessionCategoryId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UploadDailyAffirmationSessionCategoryFileAsync(long dailyAffirmationSessionCategoryId, FileStreamModel streamModel)
        {
            try
            {
                var dailyAffirmationSessionCategory = await GetDailyAffirmationSessionCategoryByIdForWriteAsync(dailyAffirmationSessionCategoryId);
                if (!dailyAffirmationSessionCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(dailyAffirmationSessionCategory);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(dailyAffirmationSessionCategory.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(dailyAffirmationSessionCategory.Model.UserId, dailyAffirmationSessionCategory.Model.DailyAffirmationSessionCategoryId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(dailyAffirmationSessionCategory.Model.UserId, dailyAffirmationSessionCategory.Model.DailyAffirmationSessionCategoryId, streamModel.FileName);
                        await productRepository.UpdateDailyAffirmationSessionCategoryFilePathAsync(dailyAffirmationSessionCategory.Model.DailyAffirmationSessionCategoryId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(dailyAffirmationSessionCategory.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Daily Affirmation Session Category File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearDailyAffirmationSessionCategoryFileAsync(long dailyAffirmationSessionCategoryId)
        {
            try
            {
                var dailyAffirmationSessionCategory = await GetDailyAffirmationSessionCategoryByIdForWriteAsync(dailyAffirmationSessionCategoryId);
                if (!dailyAffirmationSessionCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(dailyAffirmationSessionCategory);
