                    await productRepository.ClearDailyAffirmationSessionCategoryFilePathAsync(dailyAffirmationSessionCategory.Model.DailyAffirmationSessionCategoryId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(dailyAffirmationSessionCategory.Model.UserId, dailyAffirmationSessionCategory.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Daily Affirmation Session Category File", ex);
            }
        }

        public async Task CreateOrUpdateDailyAffirmationSessionCategoryDependentsAsync(DailyAffirmationSessionCategoryUpdateModel model)
        {
            if (model.NewDailyAffirmationSessionCategoryXYZZYXModels == null)
                model.NewDailyAffirmationSessionCategoryXYZZYXModels = new List<DailyAffirmationSessionCategoryXYZZYXCreateModel>();

            if (model.ExistingDailyAffirmationSessionCategoryXYZZYXModels == null)
                model.ExistingDailyAffirmationSessionCategoryXYZZYXModels = new List<DailyAffirmationSessionCategoryXYZZYXUpdateModel>();

            var dbExistingDailyAffirmationSessionCategorys = await manifestRepository.GetDailyAffirmationSessionCategoryXYZZYXsByDailyAffirmationSessionCategoryIdAsync(model.DailyAffirmationSessionCategoryId);
            if (!dbExistingDailyAffirmationSessionCategorys.IsNullOrEmpty())
            {
                var dbExistingDailyAffirmationSessionCategoryIds = dbExistingDailyAffirmationSessionCategorys.SelectToList(x => x.DailyAffirmationSessionCategoryXYZZYXId);
                var modelExistingDailyAffirmationSessionCategoryIds = model.ExistingDailyAffirmationSessionCategoryXYZZYXModels.SelectToList(x => x.DailyAffirmationSessionCategoryXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDailyAffirmationSessionCategorys.Where(x => !modelExistingDailyAffirmationSessionCategoryIds.Contains(x.DailyAffirmationSessionCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDailyAffirmationSessionCategoryXYZZYXAsDeletedByIdAsync(x.DailyAffirmationSessionCategoryXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDailyAffirmationSessionCategoryXYZZYXModels.Where(x => dbExistingDailyAffirmationSessionCategoryIds.Contains(x.DailyAffirmationSessionCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DailyAffirmationSessionCategoryId = model.DailyAffirmationSessionCategoryId;
                    var result = await UpdateDailyAffirmationSessionCategoryXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDailyAffirmationSessionCategoryXYZZYXModels)
            {
                x.DailyAffirmationSessionCategoryId = model.DailyAffirmationSessionCategoryId;
                var result = await CreateDailyAffirmationSessionCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

