        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDailyAffirmationSessionCategoryAsync(DailyAffirmationSessionCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationSessionCategoryWithDailyAffirmationSessionCategoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Session Category association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDailyAffirmationSessionCategoryWithXYZZYXAssociationExistsAsync(model.DailyAffirmationSessionCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Session Category is already associated with the Daily Affirmation Session Category", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDailyAffirmationSessionCategoryWithXYZZYXAsync(model.DailyAffirmationSessionCategoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Daily Affirmation Session Category with XYZZYX", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Daily Affirmation Session Category with XYZZYX", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDailyAffirmationSessionCategoryAsync(DailyAffirmationSessionCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationSessionCategoryWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Session Category association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDailyAffirmationSessionCategoryWithXYZZYXAssociationExistsAsync(model.DailyAffirmationSessionCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Session Category is not associated with the Daily Affirmation Session Category", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDailyAffirmationSessionCategoryWithDailyAffirmationSessionCategoryAsync(model.DailyAffirmationSessionCategoryId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Daily Affirmation Session Category with the Daily Affirmation Session Category", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Daily Affirmation Session Category with the Daily Affirmation Session Category", new { model.DailyAffirmationSessionCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDailyAffirmationSessionCategoryWithXYZZYXAssociationValidAsync(DailyAffirmationSessionCategoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DailyAffirmationSessionCategoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Session Category is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Daily Affirmation Session Category  is not valid"));
                return result;
            }

            var entity = await GetDailyAffirmationSessionCategoryForWriteByIdAsync(model.DailyAffirmationSessionCategoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Session Category information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Session Categorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

