                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unable to create Daily Affirmation Text", errorList);
                }

                dailyAffirmationText.IsDeleted = false;

                var item = objectMapperService.DailyAffirmationTextCreateModelToDailyAffirmationText(dailyAffirmationText);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateDailyAffirmationTextAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Daily Affirmation Text");
                    }

                    //await CreateOrUpdateDailyAffirmationTextDependentsAsync(dailyAffirmationText)

                    /*if (ignoreCode)
                    {
                        if (!await manifestRepository.UpdateDailyAffirmationTextCodeAsync(item.UserId, item.DailyAffirmationTextId, StringConstants.PrefixForCode.DailyAffirmationText + item.DailyAffirmationTextId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Daily Affirmation Text Code", item);
                        }
                    }*/

                    await trx.CompleteAsync();
                }

                await auditService.DailyAffirmationTextCreatedAsync(item.DailyAffirmationTextId);

                var view = await manifestRepository.GetDailyAffirmationTextViewByIdAsync(item.DailyAffirmationTextId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unable to find the Daily Affirmation Text", new { item.DailyAffirmationTextId });
                }

                return this.ConvertToItem(view, objectMapperService.DailyAffirmationTextViewToDailyAffirmationTextModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<DailyAffirmationTextModel>($"Unexpected error when creating Daily Affirmation Text", new { dailyAffirmationText?.DailyAffirmationTextId }, ex);
            }
        }

        public async Task<ReturnModel<DailyAffirmationTextModel>> UpdateDailyAffirmationTextAsync(DailyAffirmationTextUpdateModel dailyAffirmationText)
        {
            try
            {
                if (dailyAffirmationText == null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unable to update Daily Affirmation Text", new ReturnErrorItem("", "Daily Affirmation Text information is not valid"));
                }

                var existingDailyAffirmationTextModel = await GetDailyAffirmationTextByIdForWriteAsync(dailyAffirmationText.DailyAffirmationTextId);
                if (!existingDailyAffirmationTextModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>(existingDailyAffirmationTextModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(dailyAffirmationText.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>(errorStr);
                }

                if (canAssign)
                {
                    dailyAffirmationText.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                dailyAffirmationText.CreatedByUserId = existingDailyAffirmationTextModel.Model.CreatedByUserId;
                dailyAffirmationText.CreatedDate = existingDailyAffirmationTextModel.Model.CreatedDate;
                dailyAffirmationText.IsDeleted = existingDailyAffirmationTextModel.Model.IsDeleted;
                dailyAffirmationText.UserId = existingDailyAffirmationTextModel.Model.UserId;
                //dailyAffirmationText.MovieId = existingDailyAffirmationTextModel.Model.MovieId;
                //dailyAffirmationText.ProfileImageActualFileName = existingDailyAffirmationTextModel.Model.ProfileImageActualFileName;
                //dailyAffirmationText.ProfileImageLocation = existingDailyAffirmationTextModel.Model.ProfileImageLocation;



                var errorList = await IsDailyAffirmationTextModelValidForUpdateAsync(dailyAffirmationText);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unable to update Daily Affirmation Text", errorList);
                }

                var item = objectMapperService.DailyAffirmationTextUpdateModelToDailyAffirmationText(dailyAffirmationText);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDailyAffirmationTextAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Daily Affirmation Text");
                    }

                    //await CreateOrUpdateDailyAffirmationTextDependentsAsync(dailyAffirmationText)

                    await trx.CompleteAsync();
                }

                await auditService.DailyAffirmationTextUpdatedAsync(dailyAffirmationText.DailyAffirmationTextId);

                var view = await manifestRepository.GetDailyAffirmationTextViewByIdAsync(dailyAffirmationText.DailyAffirmationTextId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unable to find the Daily Affirmation Text", new { dailyAffirmationText.DailyAffirmationTextId });
                }

                return this.ConvertToItem(view, objectMapperService.DailyAffirmationTextViewToDailyAffirmationTextModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DailyAffirmationTextModel>($"Unexpected error when updating Daily Affirmation Text", new { dailyAffirmationText?.DailyAffirmationTextId }, ex);
            }
        }

