        public Task<List<ReturnErrorItem>> IsDailyAffirmationTextModelValidForCreateAsync(DailyAffirmationTextUpdateModel dailyAffirmationTextModel)
        {
            return IsDailyAffirmationTextModelValidForAllAsync(true, dailyAffirmationTextModel);
        }

        public Task<List<ReturnErrorItem>> IsDailyAffirmationTextModelValidForUpdateAsync(DailyAffirmationTextUpdateModel dailyAffirmationTextModel)
        {
            return IsDailyAffirmationTextModelValidForAllAsync(false, dailyAffirmationTextModel);
        }

        public async Task<List<ReturnErrorItem>> IsDailyAffirmationTextModelValidForAllAsync(bool isCreate, DailyAffirmationTextUpdateModel dailyAffirmationTextModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDailyAffirmationTextNameAlreadyExistsForOtherDailyAffirmationTextAsync(dailyAffirmationTextModel.DailyAffirmationTextValue, dailyAffirmationTextModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Daily Affirmation Text already exists"));
                }

                if (dailyAffirmationTextModel.DailyAffirmationTextId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Text Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDailyAffirmationTextNameAlreadyExistsForOtherDailyAffirmationTextAsync(dailyAffirmationTextModel.DailyAffirmationTextId, dailyAffirmationTextModel.DailyAffirmationTextValue, dailyAffirmationTextModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Daily Affirmation Text already exists"));
                }

                if (dailyAffirmationTextModel.DailyAffirmationTextId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Daily Affirmation Text Unique Identifier is not valid"));
                }
            }

            var categoryItem = await manifestRepository.GetCategoryViewByIdAsync(dailyAffirmationTextModel.CategoryId);
            if (categoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the Category Information"));
                return result;
            }

            if (categoryItem.UserId != dailyAffirmationTextModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this Category Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(dailyAffirmationTextModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != dailyAffirmationTextModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (dailyAffirmationTextModel.DailyAffirmationTextValue != null && dailyAffirmationTextModel.DailyAffirmationTextValue.Length > DailyAffirmationTextModel.COLUMN_SIZE_DailyAffirmationTextValue)
            {
                result.Add(new ReturnErrorItem("DailyAffirmationTextValue", $"DailyAffirmationTextValue size should not exceed {DailyAffirmationTextModel.COLUMN_SIZE_DailyAffirmationTextValue}"));
            }
            if (dailyAffirmationTextModel.DailyAffirmationTextValue == null)
            {
                result.Add(new ReturnErrorItem("DailyAffirmationTextValue", "DailyAffirmationTextValue is required "));
            }
            if (!ValidationUtils.IsLongValid(dailyAffirmationTextModel.CategoryId))
            {
                result.Add(new ReturnErrorItem("CategoryId", "Category cannot be empty"));
            }
            else
            {
                var itemForCategory = await manifestRepository.GetCategoryByIdAsync(dailyAffirmationTextModel.CategoryId);
                if (itemForCategory == null)
                {
                    result.Add(new ReturnErrorItem("CategoryId", "Category is not available"));
                }
                else
                {
                    if (itemForCategory.UserId != dailyAffirmationTextModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("CategoryId", "Category does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(dailyAffirmationTextModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(dailyAffirmationTextModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != dailyAffirmationTextModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



