        public async Task<ReturnModel<bool>> UploadDailyAffirmationTextFileAsync(long dailyAffirmationTextId, FileStreamModel streamModel)
        {
            try
            {
                var dailyAffirmationText = await GetDailyAffirmationTextByIdForWriteAsync(dailyAffirmationTextId);
                if (!dailyAffirmationText.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(dailyAffirmationText);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(dailyAffirmationText.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(dailyAffirmationText.Model.UserId, dailyAffirmationText.Model.DailyAffirmationTextId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(dailyAffirmationText.Model.UserId, dailyAffirmationText.Model.DailyAffirmationTextId, streamModel.FileName);
                        await productRepository.UpdateDailyAffirmationTextFilePathAsync(dailyAffirmationText.Model.DailyAffirmationTextId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(dailyAffirmationText.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Daily Affirmation Text File", ex);
            }
        }

