            }
        }

        public async Task CreateOrUpdateDailyAffirmationTextDependentsAsync(DailyAffirmationTextUpdateModel model)
        {
            if (model.NewDailyAffirmationTextXYZZYXModels == null)
                model.NewDailyAffirmationTextXYZZYXModels = new List<DailyAffirmationTextXYZZYXCreateModel>();

            if (model.ExistingDailyAffirmationTextXYZZYXModels == null)
                model.ExistingDailyAffirmationTextXYZZYXModels = new List<DailyAffirmationTextXYZZYXUpdateModel>();

            var dbExistingDailyAffirmationTexts = await manifestRepository.GetDailyAffirmationTextXYZZYXsByDailyAffirmationTextIdAsync(model.DailyAffirmationTextId);
            if (!dbExistingDailyAffirmationTexts.IsNullOrEmpty())
            {
                var dbExistingDailyAffirmationTextIds = dbExistingDailyAffirmationTexts.SelectToList(x => x.DailyAffirmationTextXYZZYXId);
                var modelExistingDailyAffirmationTextIds = model.ExistingDailyAffirmationTextXYZZYXModels.SelectToList(x => x.DailyAffirmationTextXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDailyAffirmationTexts.Where(x => !modelExistingDailyAffirmationTextIds.Contains(x.DailyAffirmationTextXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDailyAffirmationTextXYZZYXAsDeletedByIdAsync(x.DailyAffirmationTextXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDailyAffirmationTextXYZZYXModels.Where(x => dbExistingDailyAffirmationTextIds.Contains(x.DailyAffirmationTextXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DailyAffirmationTextId = model.DailyAffirmationTextId;
                    var result = await UpdateDailyAffirmationTextXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDailyAffirmationTextXYZZYXModels)
            {
                x.DailyAffirmationTextId = model.DailyAffirmationTextId;
                var result = await CreateDailyAffirmationTextXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

