        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDailyAffirmationTextAsync(DailyAffirmationTextXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationTextWithDailyAffirmationTextAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Text association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDailyAffirmationTextWithXYZZYXAssociationExistsAsync(model.DailyAffirmationTextId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Text is already associated with the Daily Affirmation Text", new { model.DailyAffirmationTextId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDailyAffirmationTextWithXYZZYXAsync(model.DailyAffirmationTextId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Daily Affirmation Text with XYZZYX", new { model.DailyAffirmationTextId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Daily Affirmation Text with XYZZYX", new { model.DailyAffirmationTextId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDailyAffirmationTextAsync(DailyAffirmationTextXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDailyAffirmationTextWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Daily Affirmation Text association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDailyAffirmationTextWithXYZZYXAssociationExistsAsync(model.DailyAffirmationTextId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Daily Affirmation Text is not associated with the Daily Affirmation Text", new { model.DailyAffirmationTextId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDailyAffirmationTextWithDailyAffirmationTextAsync(model.DailyAffirmationTextId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Daily Affirmation Text with the Daily Affirmation Text", new { model.DailyAffirmationTextId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Daily Affirmation Text with the Daily Affirmation Text", new { model.DailyAffirmationTextId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDailyAffirmationTextWithXYZZYXAssociationValidAsync(DailyAffirmationTextXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DailyAffirmationTextId == 0)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Text is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Daily Affirmation Text  is not valid"));
                return result;
            }

            var entity = await GetDailyAffirmationTextForWriteByIdAsync(model.DailyAffirmationTextId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Text information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Daily Affirmation Texts does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

