        public async Task<ReturnListModel<DefaultCategoryModel>> CreateMultipleDefaultCategoryAsync(MultipleDefaultCategoryCreateModel defaultCategorys)
        {
            try
            {
                if (defaultCategorys == null)
                {
                    return log.ErrorAndReturnListModel<DefaultCategoryModel>($"Unable to Create Default Categorys", new ReturnErrorItem("", "Default Categorys information is not valid"));
                }

                if (defaultCategorys.NewDefaultCategorys.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DefaultCategoryModel>($"Unable to Create Default Categorys", new ReturnErrorItem("", "Default Categorys information is not provided"));
                }

                var lst = new List<DefaultCategoryModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var defaultCategory in defaultCategorys.NewDefaultCategorys)
                    {
                        var cResult = await CreateDefaultCategoryAsync(defaultCategory);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DefaultCategoryModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DefaultCategoryModel>($"Unexpected error when creating Default Categorys", new { defaultCategorys }, ex);
            }
        }

