            try
            {
                if (defaultCategory == null)
                {
                    return log.ErrorAndReturnModel<DefaultCategoryModel>($"Unable to update Default Category", new ReturnErrorItem("", "Default Category information is not valid"));
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultCategoryModel>("You dont have access to this resource");
                }

                var existingDefaultCategoryModel = await GetDefaultCategoryByIdForWriteAsync(defaultCategory.DefaultCategoryId);
                if (!existingDefaultCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultCategoryModel>(existingDefaultCategoryModel);
                }


                defaultCategory.CreatedByUserId = existingDefaultCategoryModel.Model.CreatedByUserId;
                defaultCategory.CreatedDate = existingDefaultCategoryModel.Model.CreatedDate;
                defaultCategory.IsDeleted = existingDefaultCategoryModel.Model.IsDeleted;
                //defaultCategory.MovieId = existingDefaultCategoryModel.Model.MovieId;
                //defaultCategory.ProfileImageActualFileName = existingDefaultCategoryModel.Model.ProfileImageActualFileName;
                //defaultCategory.ProfileImageLocation = existingDefaultCategoryModel.Model.ProfileImageLocation;



                var errorList = await IsDefaultCategoryModelValidForUpdateAsync(defaultCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultCategoryModel>($"Unable to update Default Category", errorList);
                }

                var item = objectMapperService.DefaultCategoryUpdateModelToDefaultCategory(defaultCategory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Category");
                    }

                    //await CreateOrUpdateDefaultCategoryDependentsAsync(defaultCategory)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultCategoryUpdatedAsync(defaultCategory.DefaultCategoryId);

                var view = await manifestRepository.GetDefaultCategoryViewByIdAsync(defaultCategory.DefaultCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultCategoryModel>($"Unable to find the Default Category", new { defaultCategory.DefaultCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultCategoryViewToDefaultCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultCategoryModel>($"Unexpected error when updating Default Category", new { defaultCategory?.DefaultCategoryId }, ex);
            }
        }

