        public Task<List<ReturnErrorItem>> IsDefaultCategoryModelValidForUpdateAsync(DefaultCategoryUpdateModel defaultCategoryModel)
        {
            return IsDefaultCategoryModelValidForAllAsync(false, defaultCategoryModel);
        }

        public async Task<List<ReturnErrorItem>> IsDefaultCategoryModelValidForAllAsync(bool isCreate, DefaultCategoryUpdateModel defaultCategoryModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDefaultCategoryNameAlreadyExistsForOtherDefaultCategoryAsync(defaultCategoryModel.DefaultCategoryName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Category already exists"));
                }

                if (defaultCategoryModel.DefaultCategoryId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Category Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDefaultCategoryNameAlreadyExistsForOtherDefaultCategoryAsync(defaultCategoryModel.DefaultCategoryId, defaultCategoryModel.DefaultCategoryName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Category already exists"));
                }

                if (defaultCategoryModel.DefaultCategoryId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Category Unique Identifier is not valid"));
                }
            }

            if (defaultCategoryModel.DefaultCategoryName != null && defaultCategoryModel.DefaultCategoryName.Length > DefaultCategoryModel.COLUMN_SIZE_DefaultCategoryName)
            {
                result.Add(new ReturnErrorItem("DefaultCategoryName", $"DefaultCategoryName size should not exceed {DefaultCategoryModel.COLUMN_SIZE_DefaultCategoryName}"));
            }

            if (defaultCategoryModel.DefaultCategoryName == null)
            {
                result.Add(new ReturnErrorItem("DefaultCategoryName", "DefaultCategoryName is required "));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedIconTypes, long>(defaultCategoryModel.PredefinedIconTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedIconTypeId", "Icon Type is not valid"));
            }

            return result.Count > 0 ? result : null;
        }




