        public async Task<ReturnModel<bool>> UploadDefaultCategoryFileAsync(long defaultCategoryId, FileStreamModel streamModel)
        {
            try
            {
                var defaultCategory = await GetDefaultCategoryByIdForWriteAsync(defaultCategoryId);
                if (!defaultCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultCategory);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(defaultCategory.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultCategory.Model.UserId, defaultCategory.Model.DefaultCategoryId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultCategory.Model.UserId, defaultCategory.Model.DefaultCategoryId, streamModel.FileName);
                        await productRepository.UpdateDefaultCategoryFilePathAsync(defaultCategory.Model.DefaultCategoryId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultCategory.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Category File", ex);
            }
        }

