        public async Task CreateOrUpdateDefaultCategoryDependentsAsync(DefaultCategoryUpdateModel model)
        {
            if (model.NewDefaultCategoryXYZZYXModels == null)
                model.NewDefaultCategoryXYZZYXModels = new List<DefaultCategoryXYZZYXCreateModel>();

            if (model.ExistingDefaultCategoryXYZZYXModels == null)
                model.ExistingDefaultCategoryXYZZYXModels = new List<DefaultCategoryXYZZYXUpdateModel>();

            var dbExistingDefaultCategorys = await manifestRepository.GetDefaultCategoryXYZZYXsByDefaultCategoryIdAsync(model.DefaultCategoryId);
            if (!dbExistingDefaultCategorys.IsNullOrEmpty())
            {
                var dbExistingDefaultCategoryIds = dbExistingDefaultCategorys.SelectToList(x => x.DefaultCategoryXYZZYXId);
                var modelExistingDefaultCategoryIds = model.ExistingDefaultCategoryXYZZYXModels.SelectToList(x => x.DefaultCategoryXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultCategorys.Where(x => !modelExistingDefaultCategoryIds.Contains(x.DefaultCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultCategoryXYZZYXAsDeletedByIdAsync(x.DefaultCategoryXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultCategoryXYZZYXModels.Where(x => dbExistingDefaultCategoryIds.Contains(x.DefaultCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultCategoryId = model.DefaultCategoryId;
                    var result = await UpdateDefaultCategoryXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultCategoryXYZZYXModels)
            {
                x.DefaultCategoryId = model.DefaultCategoryId;
                var result = await CreateDefaultCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

