        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultCategoryAsync(DefaultCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultCategoryWithDefaultCategoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Category association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultCategoryWithXYZZYXAssociationExistsAsync(model.DefaultCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Category is already associated with the Default Category", new { model.DefaultCategoryId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultCategoryWithXYZZYXAsync(model.DefaultCategoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Category with XYZZYX", new { model.DefaultCategoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Category with XYZZYX", new { model.DefaultCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultCategoryAsync(DefaultCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultCategoryWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Category association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultCategoryWithXYZZYXAssociationExistsAsync(model.DefaultCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Category is not associated with the Default Category", new { model.DefaultCategoryId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultCategoryWithDefaultCategoryAsync(model.DefaultCategoryId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Category with the Default Category", new { model.DefaultCategoryId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Category with the Default Category", new { model.DefaultCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultCategoryWithXYZZYXAssociationValidAsync(DefaultCategoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultCategoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Category is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Category  is not valid"));
                return result;
            }

            var entity = await GetDefaultCategoryForWriteByIdAsync(model.DefaultCategoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Category information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Categorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportDefaultCategoryAsync(DefaultCategoryImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Default Category Import Info is not provided");
                }

                if (model.DefaultCategorys == null || model.DefaultCategorys.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Default Categorys Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.DefaultCategorys)
                {
                    var prod = await wipService.GetDefaultCategoryByExternalIdentifierAsync(item.DefaultCategoryIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        DefaultCategoryCreateModel defaultCategoryCreateModel = new DefaultCategoryCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedDefaultCategory = await CreateDefaultCategoryAsync(defaultCategoryCreateModel);
                        if (!newlyCreatedDefaultCategory.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedDefaultCategory.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedDefaultCategory.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        DefaultCategoryUpdateModel defaultCategoryUpdateModel = new DefaultCategoryUpdateModel
                        {
                        };

                        //update product
                        var updatedDefaultCategoryModel = await wipService.UpdateDefaultCategoryAsync(defaultCategoryUpdateModel);
                        if (!updatedDefaultCategoryModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModel<ImportStatusModel>("Unexpected error occurred when importing Default Category Info", ex);
            }
        }

        public async Task<ReturnListModel<DefaultCategoryExportModel>> ExportDefaultCategoryAsync(DefaultCategoryExportParameter filter, bool isTest)
        {
            try
            {
                var defaultCategoryCount = await manifestRepository.GetDefaultCategoryCountAsync(filter);
                if (defaultCategoryCount == 0)
                {
                    return log.ErrorAndReturnListModel<DefaultCategoryExportModel>("No Default Category available for export.");
                }

                var itemsToReturn = new List<DefaultCategoryExportModel>();
                var numberOfLoops = (defaultCategoryCount / pageSize) + 1;
                for (var i = 0; i < numberOfLoops; ++i)
                {
                    var dataResult = await wipService.GetUserViewListAsync(new DefaultCategorySearchCriteria { Page = i, PageSize = pageSize, Keyword = filter.Keyword });
                    if (dataResult.IsSuccess)
