        public async Task<ReturnListModel<DefaultDailyAffirmationTextModel>> CreateMultipleDefaultDailyAffirmationTextAsync(MultipleDefaultDailyAffirmationTextCreateModel defaultDailyAffirmationTexts)
        {
            try
            {
                if (defaultDailyAffirmationTexts == null)
                {
                    return log.ErrorAndReturnListModel<DefaultDailyAffirmationTextModel>($"Unable to Create Default Daily Affirmation Texts", new ReturnErrorItem("", "Default Daily Affirmation Texts information is not valid"));
                }

                if (defaultDailyAffirmationTexts.NewDefaultDailyAffirmationTexts.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DefaultDailyAffirmationTextModel>($"Unable to Create Default Daily Affirmation Texts", new ReturnErrorItem("", "Default Daily Affirmation Texts information is not provided"));
                }

                var lst = new List<DefaultDailyAffirmationTextModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var defaultDailyAffirmationText in defaultDailyAffirmationTexts.NewDefaultDailyAffirmationTexts)
                    {
                        var cResult = await CreateDefaultDailyAffirmationTextAsync(defaultDailyAffirmationText);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DefaultDailyAffirmationTextModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DefaultDailyAffirmationTextModel>($"Unexpected error when creating Default Daily Affirmation Texts", new { defaultDailyAffirmationTexts }, ex);
            }
        }

        public async Task<ReturnModel<DefaultDailyAffirmationTextModel>> CreateDefaultDailyAffirmationTextAsync(DefaultDailyAffirmationTextCreateModel defaultDailyAffirmationText)
        {
            try
            {
                if (defaultDailyAffirmationText == null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to create Default Daily Affirmation Text", new ReturnErrorItem("", "Default Daily Affirmation Text information is not valid"));
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>("You dont have access to this resource");
                }

                var errorList = await IsDefaultDailyAffirmationTextModelValidForCreateAsync(defaultDailyAffirmationText);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to create Default Daily Affirmation Text", errorList);
                }

                defaultDailyAffirmationText.IsDeleted = false;

                var item = objectMapperService.DefaultDailyAffirmationTextCreateModelToDefaultDailyAffirmationText(defaultDailyAffirmationText);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateDefaultDailyAffirmationTextAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Default Daily Affirmation Text");
                    }

                    //await CreateOrUpdateDefaultDailyAffirmationTextDependentsAsync(defaultDailyAffirmationText)

                    /*if (ignoreCode)
                    {
                        if (!await manifestRepository.UpdateDefaultDailyAffirmationTextCodeAsync(item.UserId, item.DefaultDailyAffirmationTextId, StringConstants.PrefixForCode.DefaultDailyAffirmationText + item.DefaultDailyAffirmationTextId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Default Daily Affirmation Text Code", item);
                        }
                    }*/

                    await trx.CompleteAsync();
                }

                await auditService.DefaultDailyAffirmationTextCreatedAsync(item.DefaultDailyAffirmationTextId);

                var view = await manifestRepository.GetDefaultDailyAffirmationTextViewByIdAsync(item.DefaultDailyAffirmationTextId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to find the Default Daily Affirmation Text", new { item.DefaultDailyAffirmationTextId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultDailyAffirmationTextViewToDefaultDailyAffirmationTextModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<DefaultDailyAffirmationTextModel>($"Unexpected error when creating Default Daily Affirmation Text", new { defaultDailyAffirmationText?.DefaultDailyAffirmationTextId }, ex);
            }
        }

        public async Task<ReturnModel<DefaultDailyAffirmationTextModel>> UpdateDefaultDailyAffirmationTextAsync(DefaultDailyAffirmationTextUpdateModel defaultDailyAffirmationText)
        {
            try
            {
                if (defaultDailyAffirmationText == null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to update Default Daily Affirmation Text", new ReturnErrorItem("", "Default Daily Affirmation Text information is not valid"));
                }

                var existingDefaultDailyAffirmationTextModel = await GetDefaultDailyAffirmationTextByIdForWriteAsync(defaultDailyAffirmationText.DefaultDailyAffirmationTextId);
                if (!existingDefaultDailyAffirmationTextModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>(existingDefaultDailyAffirmationTextModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>("You dont have access to this resource");
                }

                defaultDailyAffirmationText.CreatedByUserId = existingDefaultDailyAffirmationTextModel.Model.CreatedByUserId;
                defaultDailyAffirmationText.CreatedDate = existingDefaultDailyAffirmationTextModel.Model.CreatedDate;
                defaultDailyAffirmationText.IsDeleted = existingDefaultDailyAffirmationTextModel.Model.IsDeleted;
                //defaultDailyAffirmationText.MovieId = existingDefaultDailyAffirmationTextModel.Model.MovieId;
                //defaultDailyAffirmationText.ProfileImageActualFileName = existingDefaultDailyAffirmationTextModel.Model.ProfileImageActualFileName;
                //defaultDailyAffirmationText.ProfileImageLocation = existingDefaultDailyAffirmationTextModel.Model.ProfileImageLocation;



                var errorList = await IsDefaultDailyAffirmationTextModelValidForUpdateAsync(defaultDailyAffirmationText);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to update Default Daily Affirmation Text", errorList);
                }

                var item = objectMapperService.DefaultDailyAffirmationTextUpdateModelToDefaultDailyAffirmationText(defaultDailyAffirmationText);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultDailyAffirmationTextAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Daily Affirmation Text");
                    }

                    //await CreateOrUpdateDefaultDailyAffirmationTextDependentsAsync(defaultDailyAffirmationText)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultDailyAffirmationTextUpdatedAsync(defaultDailyAffirmationText.DefaultDailyAffirmationTextId);

                var view = await manifestRepository.GetDefaultDailyAffirmationTextViewByIdAsync(defaultDailyAffirmationText.DefaultDailyAffirmationTextId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unable to find the Default Daily Affirmation Text", new { defaultDailyAffirmationText.DefaultDailyAffirmationTextId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultDailyAffirmationTextViewToDefaultDailyAffirmationTextModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultDailyAffirmationTextModel>($"Unexpected error when updating Default Daily Affirmation Text", new { defaultDailyAffirmationText?.DefaultDailyAffirmationTextId }, ex);
            }
        }

