        public Task<List<ReturnErrorItem>> IsDefaultDailyAffirmationTextModelValidForCreateAsync(DefaultDailyAffirmationTextUpdateModel defaultDailyAffirmationTextModel)
        {
            return IsDefaultDailyAffirmationTextModelValidForAllAsync(true, defaultDailyAffirmationTextModel);
        }

        public Task<List<ReturnErrorItem>> IsDefaultDailyAffirmationTextModelValidForUpdateAsync(DefaultDailyAffirmationTextUpdateModel defaultDailyAffirmationTextModel)
        {
            return IsDefaultDailyAffirmationTextModelValidForAllAsync(false, defaultDailyAffirmationTextModel);
        }

        public async Task<List<ReturnErrorItem>> IsDefaultDailyAffirmationTextModelValidForAllAsync(bool isCreate, DefaultDailyAffirmationTextUpdateModel defaultDailyAffirmationTextModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDefaultDailyAffirmationTextNameAlreadyExistsForOtherDefaultDailyAffirmationTextAsync(defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Daily Affirmation Text already exists"));
                }

                if (defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Daily Affirmation Text Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDefaultDailyAffirmationTextNameAlreadyExistsForOtherDefaultDailyAffirmationTextAsync(defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextId, defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Daily Affirmation Text already exists"));
                }

                if (defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Daily Affirmation Text Unique Identifier is not valid"));
                }
            }

            var defaultCategoryItem = await manifestRepository.GetDefaultCategoryViewByIdAsync(defaultDailyAffirmationTextModel.DefaultCategoryId);
            if (defaultCategoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the DefaultCategory Information"));
                return result;
            }

            if (defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextName != null && defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextName.Length > DefaultDailyAffirmationTextModel.COLUMN_SIZE_DefaultDailyAffirmationTextName)
            {
                result.Add(new ReturnErrorItem("DefaultDailyAffirmationTextName", $"DefaultDailyAffirmationTextName size should not exceed {DefaultDailyAffirmationTextModel.COLUMN_SIZE_DefaultDailyAffirmationTextName}"));
            }
            if (defaultDailyAffirmationTextModel.DefaultDailyAffirmationTextName == null)
            {
                result.Add(new ReturnErrorItem("DefaultDailyAffirmationTextName", "DefaultDailyAffirmationTextName is required "));
            }
            if (!ValidationUtils.IsLongValid(defaultDailyAffirmationTextModel.DefaultCategoryId))
            {
                result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory cannot be empty"));
            }
            else
            {
                var itemForDefaultCategory = await manifestRepository.GetDefaultCategoryByIdAsync(defaultDailyAffirmationTextModel.DefaultCategoryId);
                if (itemForDefaultCategory == null)
                {
                    result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory is not available"));
                }
            }


            return result.Count > 0 ? result : null;
        }



