                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                if (!await wipFileStorage.ExistsAsync(view.Model.UserId, fileName))
                {
                    return log.ErrorAndReturnModel<FileStreamModel>($"System error: file is not available.");
                }

                var actualFileName = view.Model.ActualFileName.IsTrimmedStringNullOrEmpty() ? $"DefaultDailyAffirmationTextFile" : view.Model.ActualFileName;

                var result = new FileStreamModel
                {
                    FileName = actualFileName,
                    ContentType = FileUtils.GetMimeTypeFromFileName(actualFileName),
                    FileData = await wipFileStorage.OpenReadAsync(view.Model.UserId, fileName)
                };

                return ReturnModel<FileStreamModel>.Success(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FileStreamModel>($"Unexpected error when getting File for Default Daily Affirmation Text ", new { defaultDailyAffirmationTextId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UploadDefaultDailyAffirmationTextFileAsync(long defaultDailyAffirmationTextId, FileStreamModel streamModel)
        {
            try
            {
                var defaultDailyAffirmationText = await GetDefaultDailyAffirmationTextByIdForWriteAsync(defaultDailyAffirmationTextId);
                if (!defaultDailyAffirmationText.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultDailyAffirmationText);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(defaultDailyAffirmationText.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultDailyAffirmationText.Model.UserId, defaultDailyAffirmationText.Model.DefaultDailyAffirmationTextId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultDailyAffirmationText.Model.UserId, defaultDailyAffirmationText.Model.DefaultDailyAffirmationTextId, streamModel.FileName);
                        await productRepository.UpdateDefaultDailyAffirmationTextFilePathAsync(defaultDailyAffirmationText.Model.DefaultDailyAffirmationTextId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultDailyAffirmationText.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Daily Affirmation Text File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearDefaultDailyAffirmationTextFileAsync(long defaultDailyAffirmationTextId)
        {
            try
            {
                var defaultDailyAffirmationText = await GetDefaultDailyAffirmationTextByIdForWriteAsync(defaultDailyAffirmationTextId);
                if (!defaultDailyAffirmationText.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultDailyAffirmationText);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearDefaultDailyAffirmationTextFilePathAsync(defaultDailyAffirmationText.Model.DefaultDailyAffirmationTextId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(defaultDailyAffirmationText.Model.UserId, defaultDailyAffirmationText.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Default Daily Affirmation Text File", ex);
            }
        }

        public async Task CreateOrUpdateDefaultDailyAffirmationTextDependentsAsync(DefaultDailyAffirmationTextUpdateModel model)
        {
            if (model.NewDefaultDailyAffirmationTextXYZZYXModels == null)
                model.NewDefaultDailyAffirmationTextXYZZYXModels = new List<DefaultDailyAffirmationTextXYZZYXCreateModel>();

            if (model.ExistingDefaultDailyAffirmationTextXYZZYXModels == null)
                model.ExistingDefaultDailyAffirmationTextXYZZYXModels = new List<DefaultDailyAffirmationTextXYZZYXUpdateModel>();

            var dbExistingDefaultDailyAffirmationTexts = await manifestRepository.GetDefaultDailyAffirmationTextXYZZYXsByDefaultDailyAffirmationTextIdAsync(model.DefaultDailyAffirmationTextId);
            if (!dbExistingDefaultDailyAffirmationTexts.IsNullOrEmpty())
            {
                var dbExistingDefaultDailyAffirmationTextIds = dbExistingDefaultDailyAffirmationTexts.SelectToList(x => x.DefaultDailyAffirmationTextXYZZYXId);
                var modelExistingDefaultDailyAffirmationTextIds = model.ExistingDefaultDailyAffirmationTextXYZZYXModels.SelectToList(x => x.DefaultDailyAffirmationTextXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultDailyAffirmationTexts.Where(x => !modelExistingDefaultDailyAffirmationTextIds.Contains(x.DefaultDailyAffirmationTextXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultDailyAffirmationTextXYZZYXAsDeletedByIdAsync(x.DefaultDailyAffirmationTextXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultDailyAffirmationTextXYZZYXModels.Where(x => dbExistingDefaultDailyAffirmationTextIds.Contains(x.DefaultDailyAffirmationTextXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultDailyAffirmationTextId = model.DefaultDailyAffirmationTextId;
                    var result = await UpdateDefaultDailyAffirmationTextXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultDailyAffirmationTextXYZZYXModels)
            {
                x.DefaultDailyAffirmationTextId = model.DefaultDailyAffirmationTextId;
                var result = await CreateDefaultDailyAffirmationTextXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

