        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultDailyAffirmationTextAsync(DefaultDailyAffirmationTextXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultDailyAffirmationTextWithDefaultDailyAffirmationTextAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Daily Affirmation Text association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultDailyAffirmationTextWithXYZZYXAssociationExistsAsync(model.DefaultDailyAffirmationTextId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Daily Affirmation Text is already associated with the Default Daily Affirmation Text", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultDailyAffirmationTextWithXYZZYXAsync(model.DefaultDailyAffirmationTextId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Daily Affirmation Text with XYZZYX", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Daily Affirmation Text with XYZZYX", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultDailyAffirmationTextAsync(DefaultDailyAffirmationTextXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultDailyAffirmationTextWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Daily Affirmation Text association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultDailyAffirmationTextWithXYZZYXAssociationExistsAsync(model.DefaultDailyAffirmationTextId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Daily Affirmation Text is not associated with the Default Daily Affirmation Text", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultDailyAffirmationTextWithDefaultDailyAffirmationTextAsync(model.DefaultDailyAffirmationTextId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Daily Affirmation Text with the Default Daily Affirmation Text", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Daily Affirmation Text with the Default Daily Affirmation Text", new { model.DefaultDailyAffirmationTextId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultDailyAffirmationTextWithXYZZYXAssociationValidAsync(DefaultDailyAffirmationTextXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultDailyAffirmationTextId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Daily Affirmation Text is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Daily Affirmation Text  is not valid"));
                return result;
            }

            var entity = await GetDefaultDailyAffirmationTextForWriteByIdAsync(model.DefaultDailyAffirmationTextId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Daily Affirmation Text information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Daily Affirmation Texts does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

