        public async Task<ReturnModel<DefaultGoalTrackerModel>> UpdateDefaultGoalTrackerAsync(DefaultGoalTrackerUpdateModel defaultGoalTracker)
        {
            try
            {
                if (defaultGoalTracker == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerModel>($"Unable to update Default Goal Tracker", new ReturnErrorItem("", "Default Goal Tracker information is not valid"));
                }

                var existingDefaultGoalTrackerModel = await GetDefaultGoalTrackerByIdForWriteAsync(defaultGoalTracker.DefaultGoalTrackerId);
                if (!existingDefaultGoalTrackerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerModel>(existingDefaultGoalTrackerModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerModel>("You dont have access to this resource");
                }

                defaultGoalTracker.CreatedByUserId = existingDefaultGoalTrackerModel.Model.CreatedByUserId;
                defaultGoalTracker.CreatedDate = existingDefaultGoalTrackerModel.Model.CreatedDate;
                defaultGoalTracker.IsDeleted = existingDefaultGoalTrackerModel.Model.IsDeleted;
                //defaultGoalTracker.MovieId = existingDefaultGoalTrackerModel.Model.MovieId;
                //defaultGoalTracker.ProfileImageActualFileName = existingDefaultGoalTrackerModel.Model.ProfileImageActualFileName;
                //defaultGoalTracker.ProfileImageLocation = existingDefaultGoalTrackerModel.Model.ProfileImageLocation;



                var errorList = await IsDefaultGoalTrackerModelValidForUpdateAsync(defaultGoalTracker);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerModel>($"Unable to update Default Goal Tracker", errorList);
                }

                var item = objectMapperService.DefaultGoalTrackerUpdateModelToDefaultGoalTracker(defaultGoalTracker);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultGoalTrackerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Goal Tracker");
                    }

                    //await CreateOrUpdateDefaultGoalTrackerDependentsAsync(defaultGoalTracker)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultGoalTrackerUpdatedAsync(defaultGoalTracker.DefaultGoalTrackerId);

                var view = await manifestRepository.GetDefaultGoalTrackerViewByIdAsync(defaultGoalTracker.DefaultGoalTrackerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerModel>($"Unable to find the Default Goal Tracker", new { defaultGoalTracker.DefaultGoalTrackerId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultGoalTrackerViewToDefaultGoalTrackerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultGoalTrackerModel>($"Unexpected error when updating Default Goal Tracker", new { defaultGoalTracker?.DefaultGoalTrackerId }, ex);
            }
        }

