        public async Task<List<ReturnErrorItem>> IsDefaultGoalTrackerModelValidForAllAsync(bool isCreate, DefaultGoalTrackerUpdateModel defaultGoalTrackerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDefaultGoalTrackerNameAlreadyExistsForOtherDefaultGoalTrackerAsync(defaultGoalTrackerModel.DefaultGoalTrackerText))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Goal Tracker already exists"));
                }

                if (defaultGoalTrackerModel.DefaultGoalTrackerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Goal Tracker Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDefaultGoalTrackerNameAlreadyExistsForOtherDefaultGoalTrackerAsync(defaultGoalTrackerModel.DefaultGoalTrackerId, defaultGoalTrackerModel.DefaultGoalTrackerText))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Goal Tracker already exists"));
                }

                if (defaultGoalTrackerModel.DefaultGoalTrackerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Goal Tracker Unique Identifier is not valid"));
                }
            }

            if (defaultGoalTrackerModel.DefaultGoalTrackerText != null && defaultGoalTrackerModel.DefaultGoalTrackerText.Length > DefaultGoalTrackerModel.COLUMN_SIZE_DefaultGoalTrackerText)
            {
                result.Add(new ReturnErrorItem("DefaultGoalTrackerText", $"DefaultGoalTrackerText size should not exceed {DefaultGoalTrackerModel.COLUMN_SIZE_DefaultGoalTrackerText}"));
            }
            if (defaultGoalTrackerModel.DefaultGoalTrackerText == null)
            {
                result.Add(new ReturnErrorItem("DefaultGoalTrackerText", "DefaultGoalTrackerText is required "));
            }


            return result.Count > 0 ? result : null;
        }




