        public async Task<ReturnModel<bool>> UploadDefaultGoalTrackerFileAsync(long defaultGoalTrackerId, FileStreamModel streamModel)
        {
            try
            {
                var defaultGoalTracker = await GetDefaultGoalTrackerByIdForWriteAsync(defaultGoalTrackerId);
                if (!defaultGoalTracker.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultGoalTracker);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(defaultGoalTracker.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultGoalTracker.Model.UserId, defaultGoalTracker.Model.DefaultGoalTrackerId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultGoalTracker.Model.UserId, defaultGoalTracker.Model.DefaultGoalTrackerId, streamModel.FileName);
                        await productRepository.UpdateDefaultGoalTrackerFilePathAsync(defaultGoalTracker.Model.DefaultGoalTrackerId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultGoalTracker.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Goal Tracker File", ex);
            }
        }

