        public async Task CreateOrUpdateDefaultGoalTrackerDependentsAsync(DefaultGoalTrackerUpdateModel model)
        {
            if (model.NewDefaultGoalTrackerXYZZYXModels == null)
                model.NewDefaultGoalTrackerXYZZYXModels = new List<DefaultGoalTrackerXYZZYXCreateModel>();

            if (model.ExistingDefaultGoalTrackerXYZZYXModels == null)
                model.ExistingDefaultGoalTrackerXYZZYXModels = new List<DefaultGoalTrackerXYZZYXUpdateModel>();

            var dbExistingDefaultGoalTrackers = await manifestRepository.GetDefaultGoalTrackerXYZZYXsByDefaultGoalTrackerIdAsync(model.DefaultGoalTrackerId);
            if (!dbExistingDefaultGoalTrackers.IsNullOrEmpty())
            {
                var dbExistingDefaultGoalTrackerIds = dbExistingDefaultGoalTrackers.SelectToList(x => x.DefaultGoalTrackerXYZZYXId);
                var modelExistingDefaultGoalTrackerIds = model.ExistingDefaultGoalTrackerXYZZYXModels.SelectToList(x => x.DefaultGoalTrackerXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultGoalTrackers.Where(x => !modelExistingDefaultGoalTrackerIds.Contains(x.DefaultGoalTrackerXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultGoalTrackerXYZZYXAsDeletedByIdAsync(x.DefaultGoalTrackerXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultGoalTrackerXYZZYXModels.Where(x => dbExistingDefaultGoalTrackerIds.Contains(x.DefaultGoalTrackerXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultGoalTrackerId = model.DefaultGoalTrackerId;
                    var result = await UpdateDefaultGoalTrackerXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultGoalTrackerXYZZYXModels)
            {
                x.DefaultGoalTrackerId = model.DefaultGoalTrackerId;
                var result = await CreateDefaultGoalTrackerXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

