        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultGoalTrackerAsync(DefaultGoalTrackerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultGoalTrackerWithDefaultGoalTrackerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Goal Tracker association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultGoalTrackerWithXYZZYXAssociationExistsAsync(model.DefaultGoalTrackerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Goal Tracker is already associated with the Default Goal Tracker", new { model.DefaultGoalTrackerId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultGoalTrackerWithXYZZYXAsync(model.DefaultGoalTrackerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Goal Tracker with XYZZYX", new { model.DefaultGoalTrackerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Goal Tracker with XYZZYX", new { model.DefaultGoalTrackerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultGoalTrackerAsync(DefaultGoalTrackerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultGoalTrackerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Goal Tracker association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultGoalTrackerWithXYZZYXAssociationExistsAsync(model.DefaultGoalTrackerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Goal Tracker is not associated with the Default Goal Tracker", new { model.DefaultGoalTrackerId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultGoalTrackerWithDefaultGoalTrackerAsync(model.DefaultGoalTrackerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Goal Tracker with the Default Goal Tracker", new { model.DefaultGoalTrackerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Goal Tracker with the Default Goal Tracker", new { model.DefaultGoalTrackerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultGoalTrackerWithXYZZYXAssociationValidAsync(DefaultGoalTrackerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultGoalTrackerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Tracker is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Goal Tracker  is not valid"));
                return result;
            }

            var entity = await GetDefaultGoalTrackerForWriteByIdAsync(model.DefaultGoalTrackerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Tracker information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Trackers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportDefaultGoalTrackerAsync(DefaultGoalTrackerImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Default Goal Tracker Import Info is not provided");
                }

                if (model.DefaultGoalTrackers == null || model.DefaultGoalTrackers.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Default Goal Trackers Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.DefaultGoalTrackers)
                {
                    var prod = await wipService.GetDefaultGoalTrackerByExternalIdentifierAsync(item.DefaultGoalTrackerIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        DefaultGoalTrackerCreateModel defaultGoalTrackerCreateModel = new DefaultGoalTrackerCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedDefaultGoalTracker = await CreateDefaultGoalTrackerAsync(defaultGoalTrackerCreateModel);
                        if (!newlyCreatedDefaultGoalTracker.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedDefaultGoalTracker.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedDefaultGoalTracker.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        DefaultGoalTrackerUpdateModel defaultGoalTrackerUpdateModel = new DefaultGoalTrackerUpdateModel
                        {
                        };

                        //update product
                        var updatedDefaultGoalTrackerModel = await wipService.UpdateDefaultGoalTrackerAsync(defaultGoalTrackerUpdateModel);
                        if (!updatedDefaultGoalTrackerModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
