        public async Task<ReturnListModel<DefaultGoalTrackerCategoryModel>> CreateMultipleDefaultGoalTrackerCategoryAsync(MultipleDefaultGoalTrackerCategoryCreateModel defaultGoalTrackerCategorys)
        {
            try
            {
                if (defaultGoalTrackerCategorys == null)
                {
                    return log.ErrorAndReturnListModel<DefaultGoalTrackerCategoryModel>($"Unable to Create Default Goal Tracker Categorys", new ReturnErrorItem("", "Default Goal Tracker Categorys information is not valid"));
                }

                if (defaultGoalTrackerCategorys.NewDefaultGoalTrackerCategorys.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DefaultGoalTrackerCategoryModel>($"Unable to Create Default Goal Tracker Categorys", new ReturnErrorItem("", "Default Goal Tracker Categorys information is not provided"));
                }

                var lst = new List<DefaultGoalTrackerCategoryModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var defaultGoalTrackerCategory in defaultGoalTrackerCategorys.NewDefaultGoalTrackerCategorys)
                    {
                        var cResult = await CreateDefaultGoalTrackerCategoryAsync(defaultGoalTrackerCategory);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DefaultGoalTrackerCategoryModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DefaultGoalTrackerCategoryModel>($"Unexpected error when creating Default Goal Tracker Categorys", new { defaultGoalTrackerCategorys }, ex);
            }
        }

        public async Task<ReturnModel<DefaultGoalTrackerCategoryModel>> CreateDefaultGoalTrackerCategoryAsync(DefaultGoalTrackerCategoryCreateModel defaultGoalTrackerCategory)
        {
            try
            {
                if (defaultGoalTrackerCategory == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to create Default Goal Tracker Category", new ReturnErrorItem("", "Default Goal Tracker Category information is not valid"));
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>("You dont have access to this resource");
                }

                var errorList = await IsDefaultGoalTrackerCategoryModelValidForCreateAsync(defaultGoalTrackerCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to create Default Goal Tracker Category", errorList);
                }

                defaultGoalTrackerCategory.IsDeleted = false;

                var item = objectMapperService.DefaultGoalTrackerCategoryCreateModelToDefaultGoalTrackerCategory(defaultGoalTrackerCategory);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateDefaultGoalTrackerCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Default Goal Tracker Category");
                    }

                    await trx.CompleteAsync();
                }

                await auditService.DefaultGoalTrackerCategoryCreatedAsync(item.DefaultGoalTrackerCategoryId);

                var view = await manifestRepository.GetDefaultGoalTrackerCategoryViewByIdAsync(item.DefaultGoalTrackerCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to find the Default Goal Tracker Category", new { item.DefaultGoalTrackerCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultGoalTrackerCategoryViewToDefaultGoalTrackerCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<DefaultGoalTrackerCategoryModel>($"Unexpected error when creating Default Goal Tracker Category", new { defaultGoalTrackerCategory?.DefaultGoalTrackerCategoryId }, ex);
            }
        }

        public async Task<ReturnModel<DefaultGoalTrackerCategoryModel>> UpdateDefaultGoalTrackerCategoryAsync(DefaultGoalTrackerCategoryUpdateModel defaultGoalTrackerCategory)
        {
            try
            {
                if (defaultGoalTrackerCategory == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to update Default Goal Tracker Category", new ReturnErrorItem("", "Default Goal Tracker Category information is not valid"));
                }

                var existingDefaultGoalTrackerCategoryModel = await GetDefaultGoalTrackerCategoryByIdForWriteAsync(defaultGoalTrackerCategory.DefaultGoalTrackerCategoryId);
                if (!existingDefaultGoalTrackerCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>(existingDefaultGoalTrackerCategoryModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>("You dont have access to this resource");
                }

                defaultGoalTrackerCategory.CreatedByUserId = existingDefaultGoalTrackerCategoryModel.Model.CreatedByUserId;
                defaultGoalTrackerCategory.CreatedDate = existingDefaultGoalTrackerCategoryModel.Model.CreatedDate;
                defaultGoalTrackerCategory.IsDeleted = existingDefaultGoalTrackerCategoryModel.Model.IsDeleted;


                var errorList = await IsDefaultGoalTrackerCategoryModelValidForUpdateAsync(defaultGoalTrackerCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to update Default Goal Tracker Category", errorList);
                }

                var item = objectMapperService.DefaultGoalTrackerCategoryUpdateModelToDefaultGoalTrackerCategory(defaultGoalTrackerCategory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultGoalTrackerCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Goal Tracker Category");
                    }

                    //await CreateOrUpdateDefaultGoalTrackerCategoryDependentsAsync(defaultGoalTrackerCategory)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultGoalTrackerCategoryUpdatedAsync(defaultGoalTrackerCategory.DefaultGoalTrackerCategoryId);

                var view = await manifestRepository.GetDefaultGoalTrackerCategoryViewByIdAsync(defaultGoalTrackerCategory.DefaultGoalTrackerCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unable to find the Default Goal Tracker Category", new { defaultGoalTrackerCategory.DefaultGoalTrackerCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultGoalTrackerCategoryViewToDefaultGoalTrackerCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>($"Unexpected error when updating Default Goal Tracker Category", new { defaultGoalTrackerCategory?.DefaultGoalTrackerCategoryId }, ex);
            }
        }

