        public async Task<List<ReturnErrorItem>> IsDefaultGoalTrackerCategoryModelValidForAllAsync(bool isCreate, DefaultGoalTrackerCategoryUpdateModel defaultGoalTrackerCategoryModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (defaultGoalTrackerCategoryModel.DefaultGoalTrackerCategoryId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Goal Tracker Category Identifier is not valid"));
                }
            }
            else
            {
                if (defaultGoalTrackerCategoryModel.DefaultGoalTrackerCategoryId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Goal Tracker Category Unique Identifier is not valid"));
                }
            }

            var defaultCategoryItem = await manifestRepository.GetDefaultCategoryViewByIdAsync(defaultGoalTrackerCategoryModel.DefaultCategoryId);
            if (defaultCategoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the DefaultCategory Information"));
                return result;
            }

            var defaultGoalTrackerItem = await manifestRepository.GetDefaultGoalTrackerViewByIdAsync(defaultGoalTrackerCategoryModel.DefaultGoalTrackerId);
            if (defaultGoalTrackerItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the DefaultGoalTracker Information"));
                return result;
            }


            if (!ValidationUtils.IsLongValid(defaultGoalTrackerCategoryModel.DefaultCategoryId))
            {
                result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory cannot be empty"));
            }
            else
            {
                var itemForDefaultCategory = await manifestRepository.GetDefaultCategoryByIdAsync(defaultGoalTrackerCategoryModel.DefaultCategoryId);
                if (itemForDefaultCategory == null)
                {
                    result.Add(new ReturnErrorItem("DefaultCategoryId", "DefaultCategory is not available"));
                }
            }
            if (!ValidationUtils.IsLongValid(defaultGoalTrackerCategoryModel.DefaultGoalTrackerId))
            {
                result.Add(new ReturnErrorItem("DefaultGoalTrackerId", "DefaultGoalTracker cannot be empty"));
            }
            else
            {
                var itemForDefaultGoalTracker = await manifestRepository.GetDefaultGoalTrackerByIdAsync(defaultGoalTrackerCategoryModel.DefaultGoalTrackerId);
                if (itemForDefaultGoalTracker == null)
                {
                    result.Add(new ReturnErrorItem("DefaultGoalTrackerId", "DefaultGoalTracker is not available"));
                }
            }


            return result.Count > 0 ? result : null;
        }



