        public async Task<ReturnModel<bool>> UploadDefaultGoalTrackerCategoryFileAsync(long defaultGoalTrackerCategoryId, FileStreamModel streamModel)
        {
            try
            {
                var defaultGoalTrackerCategory = await GetDefaultGoalTrackerCategoryByIdForWriteAsync(defaultGoalTrackerCategoryId);
                if (!defaultGoalTrackerCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultGoalTrackerCategory);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(defaultGoalTrackerCategory.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultGoalTrackerCategory.Model.UserId, defaultGoalTrackerCategory.Model.DefaultGoalTrackerCategoryId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultGoalTrackerCategory.Model.UserId, defaultGoalTrackerCategory.Model.DefaultGoalTrackerCategoryId, streamModel.FileName);
                        await productRepository.UpdateDefaultGoalTrackerCategoryFilePathAsync(defaultGoalTrackerCategory.Model.DefaultGoalTrackerCategoryId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultGoalTrackerCategory.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Goal Tracker Category File", ex);
            }
        }

