        public async Task CreateOrUpdateDefaultGoalTrackerCategoryDependentsAsync(DefaultGoalTrackerCategoryUpdateModel model)
        {
            if (model.NewDefaultGoalTrackerCategoryXYZZYXModels == null)
                model.NewDefaultGoalTrackerCategoryXYZZYXModels = new List<DefaultGoalTrackerCategoryXYZZYXCreateModel>();

            if (model.ExistingDefaultGoalTrackerCategoryXYZZYXModels == null)
                model.ExistingDefaultGoalTrackerCategoryXYZZYXModels = new List<DefaultGoalTrackerCategoryXYZZYXUpdateModel>();

            var dbExistingDefaultGoalTrackerCategorys = await manifestRepository.GetDefaultGoalTrackerCategoryXYZZYXsByDefaultGoalTrackerCategoryIdAsync(model.DefaultGoalTrackerCategoryId);
            if (!dbExistingDefaultGoalTrackerCategorys.IsNullOrEmpty())
            {
                var dbExistingDefaultGoalTrackerCategoryIds = dbExistingDefaultGoalTrackerCategorys.SelectToList(x => x.DefaultGoalTrackerCategoryXYZZYXId);
                var modelExistingDefaultGoalTrackerCategoryIds = model.ExistingDefaultGoalTrackerCategoryXYZZYXModels.SelectToList(x => x.DefaultGoalTrackerCategoryXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultGoalTrackerCategorys.Where(x => !modelExistingDefaultGoalTrackerCategoryIds.Contains(x.DefaultGoalTrackerCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultGoalTrackerCategoryXYZZYXAsDeletedByIdAsync(x.DefaultGoalTrackerCategoryXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultGoalTrackerCategoryXYZZYXModels.Where(x => dbExistingDefaultGoalTrackerCategoryIds.Contains(x.DefaultGoalTrackerCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultGoalTrackerCategoryId = model.DefaultGoalTrackerCategoryId;
                    var result = await UpdateDefaultGoalTrackerCategoryXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultGoalTrackerCategoryXYZZYXModels)
            {
                x.DefaultGoalTrackerCategoryId = model.DefaultGoalTrackerCategoryId;
                var result = await CreateDefaultGoalTrackerCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableDefaultGoalTrackerCategoryByIdAsync(long defaultGoalTrackerCategoryId)
        {
            try
            {
                var existingDefaultGoalTrackerCategoryModel = await GetDefaultGoalTrackerCategoryByIdForWriteAsync(defaultGoalTrackerCategoryId);
                if (!existingDefaultGoalTrackerCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultGoalTrackerCategoryModel>(existingDefaultGoalTrackerCategoryModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingDefaultGoalTrackerCategoryModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableDefaultGoalTrackerCategoryByIdAsync(existingDefaultGoalTrackerCategoryModel.Model.DefaultGoalTrackerCategoryId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.DefaultGoalTrackerCategoryEnabledAsync(defaultGoalTrackerCategoryId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Default Goal Tracker Category", new { defaultGoalTrackerCategoryId }, ex);
            }
        }

