        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultGoalTrackerCategoryAsync(DefaultGoalTrackerCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultGoalTrackerCategoryWithDefaultGoalTrackerCategoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Goal Tracker Category association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultGoalTrackerCategoryWithXYZZYXAssociationExistsAsync(model.DefaultGoalTrackerCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Goal Tracker Category is already associated with the Default Goal Tracker Category", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultGoalTrackerCategoryWithXYZZYXAsync(model.DefaultGoalTrackerCategoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Goal Tracker Category with XYZZYX", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Goal Tracker Category with XYZZYX", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultGoalTrackerCategoryAsync(DefaultGoalTrackerCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultGoalTrackerCategoryWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Goal Tracker Category association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultGoalTrackerCategoryWithXYZZYXAssociationExistsAsync(model.DefaultGoalTrackerCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Goal Tracker Category is not associated with the Default Goal Tracker Category", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultGoalTrackerCategoryWithDefaultGoalTrackerCategoryAsync(model.DefaultGoalTrackerCategoryId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Goal Tracker Category with the Default Goal Tracker Category", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Goal Tracker Category with the Default Goal Tracker Category", new { model.DefaultGoalTrackerCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultGoalTrackerCategoryWithXYZZYXAssociationValidAsync(DefaultGoalTrackerCategoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultGoalTrackerCategoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Tracker Category is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Goal Tracker Category  is not valid"));
                return result;
            }

            var entity = await GetDefaultGoalTrackerCategoryForWriteByIdAsync(model.DefaultGoalTrackerCategoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Tracker Category information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Goal Tracker Categorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

