                if (defaultMeditationFiles.NewDefaultMeditationFiles.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DefaultMeditationFileModel>($"Unable to Create Default Meditation Files", new ReturnErrorItem("", "Default Meditation Files information is not provided"));
                }

                var lst = new List<DefaultMeditationFileModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var defaultMeditationFile in defaultMeditationFiles.NewDefaultMeditationFiles)
                    {
                        var cResult = await CreateDefaultMeditationFileAsync(defaultMeditationFile);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DefaultMeditationFileModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DefaultMeditationFileModel>($"Unexpected error when creating Default Meditation Files", new { defaultMeditationFiles }, ex);
            }
        }

        public async Task<ReturnModel<DefaultMeditationFileModel>> CreateDefaultMeditationFileAsync(DefaultMeditationFileCreateModel defaultMeditationFile)
        {
            try
            {
                if (defaultMeditationFile == null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to create Default Meditation File", new ReturnErrorItem("", "Default Meditation File information is not valid"));
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>("You dont have access to this resource");
                }

                var errorList = await IsDefaultMeditationFileModelValidForCreateAsync(defaultMeditationFile);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to create Default Meditation File", errorList);
                }

                defaultMeditationFile.IsDeleted = false;

                var item = objectMapperService.DefaultMeditationFileCreateModelToDefaultMeditationFile(defaultMeditationFile);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateDefaultMeditationFileAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Default Meditation File");
                    }

                    //await CreateOrUpdateDefaultMeditationFileDependentsAsync(defaultMeditationFile)

                    /*if (ignoreCode)
                    {
                        if (!await manifestRepository.UpdateDefaultMeditationFileCodeAsync(item.UserId, item.DefaultMeditationFileId, StringConstants.PrefixForCode.DefaultMeditationFile + item.DefaultMeditationFileId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Default Meditation File Code", item);
                        }
                    }*/

                    await trx.CompleteAsync();
                }

                await auditService.DefaultMeditationFileCreatedAsync(item.DefaultMeditationFileId);

                var view = await manifestRepository.GetDefaultMeditationFileViewByIdAsync(item.DefaultMeditationFileId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to find the Default Meditation File", new { item.DefaultMeditationFileId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultMeditationFileViewToDefaultMeditationFileModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<DefaultMeditationFileModel>($"Unexpected error when creating Default Meditation File", new { defaultMeditationFile?.DefaultMeditationFileId }, ex);
            }
        }

        public async Task<ReturnModel<DefaultMeditationFileModel>> UpdateDefaultMeditationFileAsync(DefaultMeditationFileUpdateModel defaultMeditationFile)
        {
            try
            {
                if (defaultMeditationFile == null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to update Default Meditation File", new ReturnErrorItem("", "Default Meditation File information is not valid"));
                }

                var existingDefaultMeditationFileModel = await GetDefaultMeditationFileByIdForWriteAsync(defaultMeditationFile.DefaultMeditationFileId);
                if (!existingDefaultMeditationFileModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>(existingDefaultMeditationFileModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>("You dont have access to this resource");
                }

                defaultMeditationFile.CreatedByUserId = existingDefaultMeditationFileModel.Model.CreatedByUserId;
                defaultMeditationFile.CreatedDate = existingDefaultMeditationFileModel.Model.CreatedDate;
                defaultMeditationFile.IsDeleted = existingDefaultMeditationFileModel.Model.IsDeleted;
                //defaultMeditationFile.MovieId = existingDefaultMeditationFileModel.Model.MovieId;
                //defaultMeditationFile.ProfileImageActualFileName = existingDefaultMeditationFileModel.Model.ProfileImageActualFileName;
                //defaultMeditationFile.ProfileImageLocation = existingDefaultMeditationFileModel.Model.ProfileImageLocation;



                var errorList = await IsDefaultMeditationFileModelValidForUpdateAsync(defaultMeditationFile);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to update Default Meditation File", errorList);
                }

                var item = objectMapperService.DefaultMeditationFileUpdateModelToDefaultMeditationFile(defaultMeditationFile);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultMeditationFileAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Meditation File");
                    }

                    //await CreateOrUpdateDefaultMeditationFileDependentsAsync(defaultMeditationFile)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultMeditationFileUpdatedAsync(defaultMeditationFile.DefaultMeditationFileId);

                var view = await manifestRepository.GetDefaultMeditationFileViewByIdAsync(defaultMeditationFile.DefaultMeditationFileId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unable to find the Default Meditation File", new { defaultMeditationFile.DefaultMeditationFileId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultMeditationFileViewToDefaultMeditationFileModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultMeditationFileModel>($"Unexpected error when updating Default Meditation File", new { defaultMeditationFile?.DefaultMeditationFileId }, ex);
            }
        }

