        public async Task<List<ReturnErrorItem>> IsDefaultMeditationFileModelValidForAllAsync(bool isCreate, DefaultMeditationFileUpdateModel defaultMeditationFileModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDefaultMeditationFileNameAlreadyExistsForOtherDefaultMeditationFileAsync(defaultMeditationFileModel.DefaultMeditationFileName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Meditation File already exists"));
                }

                if (defaultMeditationFileModel.DefaultMeditationFileId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Meditation File Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDefaultMeditationFileNameAlreadyExistsForOtherDefaultMeditationFileAsync(defaultMeditationFileModel.DefaultMeditationFileId, defaultMeditationFileModel.DefaultMeditationFileName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Meditation File already exists"));
                }

                if (defaultMeditationFileModel.DefaultMeditationFileId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Meditation File Unique Identifier is not valid"));
                }
            }



            if (defaultMeditationFileModel.DefaultMeditationFileName != null && defaultMeditationFileModel.DefaultMeditationFileName.Length > DefaultMeditationFileModel.COLUMN_SIZE_DefaultMeditationFileName)
            {
                result.Add(new ReturnErrorItem("DefaultMeditationFileName", $"DefaultMeditationFileName size should not exceed {DefaultMeditationFileModel.COLUMN_SIZE_DefaultMeditationFileName}"));
            }
            if (defaultMeditationFileModel.DefaultMeditationFileName == null)
            {
                result.Add(new ReturnErrorItem("DefaultMeditationFileName", "DefaultMeditationFileName is required "));
            }
            if (defaultMeditationFileModel.PredefinedMeditationTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedMeditationTypeId", "PredefinedMeditationTypeId cannot be empty"));
            }
            if (defaultMeditationFileModel.Location != null && defaultMeditationFileModel.Location.Length > DefaultMeditationFileModel.COLUMN_SIZE_Location)
            {
                result.Add(new ReturnErrorItem("Location", $"Location size should not exceed {DefaultMeditationFileModel.COLUMN_SIZE_Location}"));
            }
            if (defaultMeditationFileModel.FileName != null && defaultMeditationFileModel.FileName.Length > DefaultMeditationFileModel.COLUMN_SIZE_FileName)
            {
                result.Add(new ReturnErrorItem("FileName", $"FileName size should not exceed {DefaultMeditationFileModel.COLUMN_SIZE_FileName}"));
            }
            if (defaultMeditationFileModel.FileName == null)
            {
                result.Add(new ReturnErrorItem("FileName", "FileName is required "));
            }


            return result.Count > 0 ? result : null;
        }




