        public async Task<ReturnModel<bool>> UploadDefaultMeditationFileFileAsync(long defaultMeditationFileId, FileStreamModel streamModel)
        {
            try
            {
                var defaultMeditationFile = await GetDefaultMeditationFileByIdForWriteAsync(defaultMeditationFileId);
                if (!defaultMeditationFile.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(defaultMeditationFile);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(defaultMeditationFile.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultMeditationFile.Model.UserId, defaultMeditationFile.Model.DefaultMeditationFileId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultMeditationFile.Model.UserId, defaultMeditationFile.Model.DefaultMeditationFileId, streamModel.FileName);
                        await productRepository.UpdateDefaultMeditationFileFilePathAsync(defaultMeditationFile.Model.DefaultMeditationFileId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultMeditationFile.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Meditation File File", ex);
            }
        }

