        public async Task CreateOrUpdateDefaultMeditationFileDependentsAsync(DefaultMeditationFileUpdateModel model)
        {
            if (model.NewDefaultMeditationFileXYZZYXModels == null)
                model.NewDefaultMeditationFileXYZZYXModels = new List<DefaultMeditationFileXYZZYXCreateModel>();

            if (model.ExistingDefaultMeditationFileXYZZYXModels == null)
                model.ExistingDefaultMeditationFileXYZZYXModels = new List<DefaultMeditationFileXYZZYXUpdateModel>();

            var dbExistingDefaultMeditationFiles = await manifestRepository.GetDefaultMeditationFileXYZZYXsByDefaultMeditationFileIdAsync(model.DefaultMeditationFileId);
            if (!dbExistingDefaultMeditationFiles.IsNullOrEmpty())
            {
                var dbExistingDefaultMeditationFileIds = dbExistingDefaultMeditationFiles.SelectToList(x => x.DefaultMeditationFileXYZZYXId);
                var modelExistingDefaultMeditationFileIds = model.ExistingDefaultMeditationFileXYZZYXModels.SelectToList(x => x.DefaultMeditationFileXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultMeditationFiles.Where(x => !modelExistingDefaultMeditationFileIds.Contains(x.DefaultMeditationFileXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultMeditationFileXYZZYXAsDeletedByIdAsync(x.DefaultMeditationFileXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultMeditationFileXYZZYXModels.Where(x => dbExistingDefaultMeditationFileIds.Contains(x.DefaultMeditationFileXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultMeditationFileId = model.DefaultMeditationFileId;
                    var result = await UpdateDefaultMeditationFileXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultMeditationFileXYZZYXModels)
            {
                x.DefaultMeditationFileId = model.DefaultMeditationFileId;
                var result = await CreateDefaultMeditationFileXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

