        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultMeditationFileAsync(DefaultMeditationFileXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultMeditationFileWithDefaultMeditationFileAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Meditation File association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultMeditationFileWithXYZZYXAssociationExistsAsync(model.DefaultMeditationFileId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Meditation File is already associated with the Default Meditation File", new { model.DefaultMeditationFileId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultMeditationFileWithXYZZYXAsync(model.DefaultMeditationFileId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Meditation File with XYZZYX", new { model.DefaultMeditationFileId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Meditation File with XYZZYX", new { model.DefaultMeditationFileId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultMeditationFileAsync(DefaultMeditationFileXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultMeditationFileWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Meditation File association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultMeditationFileWithXYZZYXAssociationExistsAsync(model.DefaultMeditationFileId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Meditation File is not associated with the Default Meditation File", new { model.DefaultMeditationFileId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultMeditationFileWithDefaultMeditationFileAsync(model.DefaultMeditationFileId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Meditation File with the Default Meditation File", new { model.DefaultMeditationFileId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Meditation File with the Default Meditation File", new { model.DefaultMeditationFileId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultMeditationFileWithXYZZYXAssociationValidAsync(DefaultMeditationFileXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultMeditationFileId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Meditation File is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Meditation File  is not valid"));
                return result;
            }

            var entity = await GetDefaultMeditationFileForWriteByIdAsync(model.DefaultMeditationFileId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Meditation File information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Meditation Files does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

