        public async Task<ReturnListModel<DefaultVisionBoardPictureModel>> CreateMultipleDefaultVisionBoardPictureAsync(MultipleDefaultVisionBoardPictureCreateModel defaultVisionBoardPictures)
        {
            try
            {
                if (defaultVisionBoardPictures == null)
                {
                    return log.ErrorAndReturnListModel<DefaultVisionBoardPictureModel>($"Unable to Create Default Vision Board Pictures", new ReturnErrorItem("", "Default Vision Board Pictures information is not valid"));
                }

                if (defaultVisionBoardPictures.NewDefaultVisionBoardPictures.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<DefaultVisionBoardPictureModel>($"Unable to Create Default Vision Board Pictures", new ReturnErrorItem("", "Default Vision Board Pictures information is not provided"));
                }

                var lst = new List<DefaultVisionBoardPictureModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var defaultVisionBoardPicture in defaultVisionBoardPictures.NewDefaultVisionBoardPictures)
                    {
                        var cResult = await CreateDefaultVisionBoardPictureAsync(defaultVisionBoardPicture);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<DefaultVisionBoardPictureModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<DefaultVisionBoardPictureModel>($"Unexpected error when creating Default Vision Board Pictures", new { defaultVisionBoardPictures }, ex);
            }
        }

        public async Task<ReturnModel<DefaultVisionBoardPictureModel>> CreateDefaultVisionBoardPictureAsync(DefaultVisionBoardPictureCreateModel defaultVisionBoardPicture)
