                var errorList = await IsDefaultVisionBoardPictureModelValidForCreateAsync(defaultVisionBoardPicture);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unable to create Default Vision Board Picture", errorList);
                }

                defaultVisionBoardPicture.IsDeleted = false;

                var item = objectMapperService.DefaultVisionBoardPictureCreateModelToDefaultVisionBoardPicture(defaultVisionBoardPicture);

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    item = await manifestRepository.CreateDefaultVisionBoardPictureAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (item == null)
                    {
                        throw new Exception($"Unable to create Default Vision Board Picture");
                    }

                    //await CreateOrUpdateDefaultVisionBoardPictureDependentsAsync(defaultVisionBoardPicture)

                    /*if (ignoreCode)
                    {
                        if (!await manifestRepository.UpdateDefaultVisionBoardPictureCodeAsync(item.UserId, item.DefaultVisionBoardPictureId, StringConstants.PrefixForCode.DefaultVisionBoardPicture + item.DefaultVisionBoardPictureId, await currentSessionService.GetCurrentUserIdAsync()))
                        {
                            throw new RollbackException($"Unable update the Default Vision Board Picture Code", item);
                        }
                    }*/

                    await trx.CompleteAsync();
                }

                await auditService.DefaultVisionBoardPictureCreatedAsync(item.DefaultVisionBoardPictureId);

                var view = await manifestRepository.GetDefaultVisionBoardPictureViewByIdAsync(item.DefaultVisionBoardPictureId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unable to find the Default Vision Board Picture", new { item.DefaultVisionBoardPictureId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultVisionBoardPictureViewToDefaultVisionBoardPictureModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModelWithRollbackExceptionHandler<DefaultVisionBoardPictureModel>($"Unexpected error when creating Default Vision Board Picture", new { defaultVisionBoardPicture?.DefaultVisionBoardPictureId }, ex);
            }
        }

        public async Task<ReturnModel<DefaultVisionBoardPictureModel>> UpdateDefaultVisionBoardPictureAsync(DefaultVisionBoardPictureUpdateModel defaultVisionBoardPicture)
        {
            try
            {
                if (defaultVisionBoardPicture == null)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unable to update Default Vision Board Picture", new ReturnErrorItem("", "Default Vision Board Picture information is not valid"));
                }

                var existingDefaultVisionBoardPictureModel = await GetDefaultVisionBoardPictureByIdForWriteAsync(defaultVisionBoardPicture.DefaultVisionBoardPictureId);
                if (!existingDefaultVisionBoardPictureModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>(existingDefaultVisionBoardPictureModel);
                }

                if (!await currentSessionService.IsCurrentUserASuperAdminAsync())
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>("You dont have access to this resource");
                }

                defaultVisionBoardPicture.CreatedByUserId = existingDefaultVisionBoardPictureModel.Model.CreatedByUserId;
                defaultVisionBoardPicture.CreatedDate = existingDefaultVisionBoardPictureModel.Model.CreatedDate;
                defaultVisionBoardPicture.IsDeleted = existingDefaultVisionBoardPictureModel.Model.IsDeleted;
                //defaultVisionBoardPicture.MovieId = existingDefaultVisionBoardPictureModel.Model.MovieId;
                //defaultVisionBoardPicture.ProfileImageActualFileName = existingDefaultVisionBoardPictureModel.Model.ProfileImageActualFileName;
                //defaultVisionBoardPicture.ProfileImageLocation = existingDefaultVisionBoardPictureModel.Model.ProfileImageLocation;



                var errorList = await IsDefaultVisionBoardPictureModelValidForUpdateAsync(defaultVisionBoardPicture);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unable to update Default Vision Board Picture", errorList);
                }

                var item = objectMapperService.DefaultVisionBoardPictureUpdateModelToDefaultVisionBoardPicture(defaultVisionBoardPicture);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateDefaultVisionBoardPictureAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Default Vision Board Picture");
                    }

                    //await CreateOrUpdateDefaultVisionBoardPictureDependentsAsync(defaultVisionBoardPicture)

                    await trx.CompleteAsync();
                }

                await auditService.DefaultVisionBoardPictureUpdatedAsync(defaultVisionBoardPicture.DefaultVisionBoardPictureId);

                var view = await manifestRepository.GetDefaultVisionBoardPictureViewByIdAsync(defaultVisionBoardPicture.DefaultVisionBoardPictureId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unable to find the Default Vision Board Picture", new { defaultVisionBoardPicture.DefaultVisionBoardPictureId });
                }

                return this.ConvertToItem(view, objectMapperService.DefaultVisionBoardPictureViewToDefaultVisionBoardPictureModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<DefaultVisionBoardPictureModel>($"Unexpected error when updating Default Vision Board Picture", new { defaultVisionBoardPicture?.DefaultVisionBoardPictureId }, ex);
            }
        }

