        public async Task<List<ReturnErrorItem>> IsDefaultVisionBoardPictureModelValidForAllAsync(bool isCreate, DefaultVisionBoardPictureUpdateModel defaultVisionBoardPictureModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsDefaultVisionBoardPictureNameAlreadyExistsForOtherDefaultVisionBoardPictureAsync(defaultVisionBoardPictureModel.FileName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Vision Board Picture already exists"));
                }

                if (defaultVisionBoardPictureModel.DefaultVisionBoardPictureId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Vision Board Picture Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsDefaultVisionBoardPictureNameAlreadyExistsForOtherDefaultVisionBoardPictureAsync(defaultVisionBoardPictureModel.DefaultVisionBoardPictureId, defaultVisionBoardPictureModel.FileName))
                {
                    result.Add(new ReturnErrorItem("", "Another Default Vision Board Picture already exists"));
                }

                if (defaultVisionBoardPictureModel.DefaultVisionBoardPictureId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Default Vision Board Picture Unique Identifier is not valid"));
                }
            }



            if (defaultVisionBoardPictureModel.Location != null && defaultVisionBoardPictureModel.Location.Length > DefaultVisionBoardPictureModel.COLUMN_SIZE_Location)
            {
                result.Add(new ReturnErrorItem("Location", $"Location size should not exceed {DefaultVisionBoardPictureModel.COLUMN_SIZE_Location}"));
            }
            if (defaultVisionBoardPictureModel.FileName != null && defaultVisionBoardPictureModel.FileName.Length > DefaultVisionBoardPictureModel.COLUMN_SIZE_FileName)
            {
                result.Add(new ReturnErrorItem("FileName", $"FileName size should not exceed {DefaultVisionBoardPictureModel.COLUMN_SIZE_FileName}"));
            }
            if (defaultVisionBoardPictureModel.FileName == null)
            {
                result.Add(new ReturnErrorItem("FileName", "FileName is required "));
            }


            return result.Count > 0 ? result : null;
        }




