                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(defaultVisionBoardPicture.Model.UserId, defaultVisionBoardPicture.Model.DefaultVisionBoardPictureId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(defaultVisionBoardPicture.Model.UserId, defaultVisionBoardPicture.Model.DefaultVisionBoardPictureId, streamModel.FileName);
                        await productRepository.UpdateDefaultVisionBoardPictureFilePathAsync(defaultVisionBoardPicture.Model.DefaultVisionBoardPictureId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(defaultVisionBoardPicture.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Default Vision Board Picture File", ex);
            }
        }

