        public async Task CreateOrUpdateDefaultVisionBoardPictureDependentsAsync(DefaultVisionBoardPictureUpdateModel model)
        {
            if (model.NewDefaultVisionBoardPictureXYZZYXModels == null)
                model.NewDefaultVisionBoardPictureXYZZYXModels = new List<DefaultVisionBoardPictureXYZZYXCreateModel>();

            if (model.ExistingDefaultVisionBoardPictureXYZZYXModels == null)
                model.ExistingDefaultVisionBoardPictureXYZZYXModels = new List<DefaultVisionBoardPictureXYZZYXUpdateModel>();

            var dbExistingDefaultVisionBoardPictures = await manifestRepository.GetDefaultVisionBoardPictureXYZZYXsByDefaultVisionBoardPictureIdAsync(model.DefaultVisionBoardPictureId);
            if (!dbExistingDefaultVisionBoardPictures.IsNullOrEmpty())
            {
                var dbExistingDefaultVisionBoardPictureIds = dbExistingDefaultVisionBoardPictures.SelectToList(x => x.DefaultVisionBoardPictureXYZZYXId);
                var modelExistingDefaultVisionBoardPictureIds = model.ExistingDefaultVisionBoardPictureXYZZYXModels.SelectToList(x => x.DefaultVisionBoardPictureXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingDefaultVisionBoardPictures.Where(x => !modelExistingDefaultVisionBoardPictureIds.Contains(x.DefaultVisionBoardPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkDefaultVisionBoardPictureXYZZYXAsDeletedByIdAsync(x.DefaultVisionBoardPictureXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingDefaultVisionBoardPictureXYZZYXModels.Where(x => dbExistingDefaultVisionBoardPictureIds.Contains(x.DefaultVisionBoardPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.DefaultVisionBoardPictureId = model.DefaultVisionBoardPictureId;
                    var result = await UpdateDefaultVisionBoardPictureXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewDefaultVisionBoardPictureXYZZYXModels)
            {
                x.DefaultVisionBoardPictureId = model.DefaultVisionBoardPictureId;
                var result = await CreateDefaultVisionBoardPictureXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

