        public async Task<ReturnModel<bool>> AssociateXYZZYXWithDefaultVisionBoardPictureAsync(DefaultVisionBoardPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultVisionBoardPictureWithDefaultVisionBoardPictureAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Vision Board Picture association is invalid", errorLst);
                }

                if (await manifestRepository.DoesDefaultVisionBoardPictureWithXYZZYXAssociationExistsAsync(model.DefaultVisionBoardPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Vision Board Picture is already associated with the Default Vision Board Picture", new { model.DefaultVisionBoardPictureId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateDefaultVisionBoardPictureWithXYZZYXAsync(model.DefaultVisionBoardPictureId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Default Vision Board Picture with XYZZYX", new { model.DefaultVisionBoardPictureId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Default Vision Board Picture with XYZZYX", new { model.DefaultVisionBoardPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithDefaultVisionBoardPictureAsync(DefaultVisionBoardPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsDefaultVisionBoardPictureWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Default Vision Board Picture association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesDefaultVisionBoardPictureWithXYZZYXAssociationExistsAsync(model.DefaultVisionBoardPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Default Vision Board Picture is not associated with the Default Vision Board Picture", new { model.DefaultVisionBoardPictureId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateDefaultVisionBoardPictureWithDefaultVisionBoardPictureAsync(model.DefaultVisionBoardPictureId, model.XYZZYXId);
