                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Default Vision Board Picture with the Default Vision Board Picture", new { model.DefaultVisionBoardPictureId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Default Vision Board Picture with the Default Vision Board Picture", new { model.DefaultVisionBoardPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsDefaultVisionBoardPictureWithXYZZYXAssociationValidAsync(DefaultVisionBoardPictureXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.DefaultVisionBoardPictureId == 0)
            {
                result.Add(new ReturnErrorItem("", "Default Vision Board Picture is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Default Vision Board Picture  is not valid"));
                return result;
            }

            var entity = await GetDefaultVisionBoardPictureForWriteByIdAsync(model.DefaultVisionBoardPictureId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Default Vision Board Picture information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Default Vision Board Pictures does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

