        public async Task<ReturnListModel<FeedModel>> CreateMultipleFeedAsync(MultipleFeedCreateModel feeds)
        {
            try
            {
                if (feeds == null)
                {
                    return log.ErrorAndReturnListModel<FeedModel>($"Unable to Create Feeds", new ReturnErrorItem("", "Feeds information is not valid"));
                }

                if (feeds.NewFeeds.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<FeedModel>($"Unable to Create Feeds", new ReturnErrorItem("", "Feeds information is not provided"));
                }

                var lst = new List<FeedModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var feed in feeds.NewFeeds)
                    {
                        var cResult = await CreateFeedAsync(feed);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<FeedModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<FeedModel>($"Unexpected error when creating Feeds", new { feeds }, ex);
            }
        }

