        public async Task<ReturnModel<FeedModel>> UpdateFeedAsync(FeedUpdateModel feed)
        {
            try
            {
                if (feed == null)
                {
                    return log.ErrorAndReturnModel<FeedModel>($"Unable to update Feed", new ReturnErrorItem("", "Feed information is not valid"));
                }

                var existingFeedModel = await GetFeedByIdForWriteAsync(feed.FeedId);
                if (!existingFeedModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FeedModel>(existingFeedModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(feed.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<FeedModel>(errorStr);
                }

                if (canAssign)
                {
                    feed.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                feed.CreatedByUserId = existingFeedModel.Model.CreatedByUserId;
                feed.CreatedDate = existingFeedModel.Model.CreatedDate;
                feed.IsDeleted = existingFeedModel.Model.IsDeleted;
                feed.UserId = existingFeedModel.Model.UserId;
                //feed.MovieId = existingFeedModel.Model.MovieId;
                //feed.ProfileImageActualFileName = existingFeedModel.Model.ProfileImageActualFileName;
                //feed.ProfileImageLocation = existingFeedModel.Model.ProfileImageLocation;



                var errorList = await IsFeedModelValidForUpdateAsync(feed);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<FeedModel>($"Unable to update Feed", errorList);
                }

                var item = objectMapperService.FeedUpdateModelToFeed(feed);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateFeedAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Feed");
                    }

                    //await CreateOrUpdateFeedDependentsAsync(feed)

                    await trx.CompleteAsync();
                }

                await auditService.FeedUpdatedAsync(feed.FeedId);

                var view = await manifestRepository.GetFeedViewByIdAsync(feed.FeedId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<FeedModel>($"Unable to find the Feed", new { feed.FeedId });
                }

                return this.ConvertToItem(view, objectMapperService.FeedViewToFeedModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<FeedModel>($"Unexpected error when updating Feed", new { feed?.FeedId }, ex);
            }
        }

