        public async Task<ReturnModel<bool>> HardDeleteFeedByAsync(long feedId)
        {
            try
            {
                var existingFeedModel = await GetFeedByIdForWriteAsync(feedId);
                if (!existingFeedModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(existingFeedModel);
                }

                var (resultValue, _, errorStr) = await permissionService.CanModifyResource(existingFeedModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.HardDeleteFeedByIdAsync(feedId);
                    await trx.CompleteAsync();
                }


                await auditService.HardDeleteFeedAsync(feedId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when deleting Feed", new { feedId }, ex);
            }
        }

        public Task<List<ReturnErrorItem>> IsFeedModelValidForCreateAsync(FeedUpdateModel feedModel)
        {
            return IsFeedModelValidForAllAsync(true, feedModel);
        }

        public Task<List<ReturnErrorItem>> IsFeedModelValidForUpdateAsync(FeedUpdateModel feedModel)
        {
            return IsFeedModelValidForAllAsync(false, feedModel);
        }

        public async Task<List<ReturnErrorItem>> IsFeedModelValidForAllAsync(bool isCreate, FeedUpdateModel feedModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (feedModel.FeedId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Feed Identifier is not valid"));
                }
            }
            else
            {
                if (feedModel.FeedId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Feed Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(feedModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != feedModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }


            if (feedModel.DailyAffirmationSessionId > 0)
            {
                var dailyAffirmationSessionItem = await manifestRepository.GetDailyAffirmationSessionViewByIdAsync(feedModel.DailyAffirmationSessionId ?? 0);
                if (dailyAffirmationSessionItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the DailyAffirmationSession Information"));
                    return result;
                }

                if (dailyAffirmationSessionItem.UserId != feedModel.UserId)
                {
                    result.Add(new ReturnErrorItem("", $"You dont have access to this DailyAffirmationSession Information"));
                    return result;
                }

            }

            if (feedModel.VisionBoardSessionId > 0)
            {
                var visionBoardSessionItem = await manifestRepository.GetVisionBoardSessionViewByIdAsync(feedModel.VisionBoardSessionId ?? 0);
                if (visionBoardSessionItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the VisionBoardSession Information"));
                    return result;
                }

                if (visionBoardSessionItem.UserId != feedModel.UserId)
                {
                    result.Add(new ReturnErrorItem("", $"You dont have access to this VisionBoardSession Information"));
                    return result;
                }

            }

            if (feedModel.MeditationSessionId > 0)
            {
                var meditationSessionItem = await manifestRepository.GetMeditationSessionViewByIdAsync(feedModel.MeditationSessionId ?? 0);
                if (meditationSessionItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the MeditationSession Information"));
                    return result;
                }

                if (meditationSessionItem.UserId != feedModel.UserId)
                {
                    result.Add(new ReturnErrorItem("", $"You dont have access to this MeditationSession Information"));
                    return result;
                }

            }

            if (feedModel.GoalTrackerId > 0)
            {
                var goalTrackerItem = await manifestRepository.GetGoalTrackerViewByIdAsync(feedModel.GoalTrackerId ?? 0);
                if (goalTrackerItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the GoalTracker Information"));
                    return result;
                }

                if (goalTrackerItem.UserId != feedModel.UserId)
                {
                    result.Add(new ReturnErrorItem("", $"You dont have access to this GoalTracker Information"));
                    return result;
                }

            }

            if (feedModel.GoalTrackerMileStoneId > 0)
            {
                var goalTrackerMileStoneItem = await manifestRepository.GetGoalTrackerMileStoneViewByIdAsync(feedModel.GoalTrackerMileStoneId ?? 0);
                if (goalTrackerMileStoneItem == null)
                {
                    result.Add(new ReturnErrorItem("", $"Unable to Get the GoalTrackerMileStone Information"));
                    return result;
                }

                if (goalTrackerMileStoneItem.UserId != feedModel.UserId)
                {
                    result.Add(new ReturnErrorItem("", $"You dont have access to this GoalTrackerMileStone Information"));
                    return result;
                }

            }



            if (!ValidationUtils.IsLongValid(feedModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(feedModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != feedModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }
            if (feedModel.DailyAffirmationSessionDate != null && !DateUtils.IsValidDate(feedModel.DailyAffirmationSessionDate.Value))
            {
                result.Add(new ReturnErrorItem("DailyAffirmationSessionDate", $"DailyAffirmationSessionDate is not a valid date"));
            }
            if (feedModel.VisionBoardSessionDate != null && !DateUtils.IsValidDate(feedModel.VisionBoardSessionDate.Value))
            {
                result.Add(new ReturnErrorItem("VisionBoardSessionDate", $"VisionBoardSessionDate is not a valid date"));
            }
            if (feedModel.MeditationSessionDate != null && !DateUtils.IsValidDate(feedModel.MeditationSessionDate.Value))
            {
                result.Add(new ReturnErrorItem("MeditationSessionDate", $"MeditationSessionDate is not a valid date"));
            }
            if (feedModel.MeditationFileName != null && feedModel.MeditationFileName.Length > FeedModel.COLUMN_SIZE_MeditationFileName)
            {
                result.Add(new ReturnErrorItem("MeditationFileName", $"MeditationFileName size should not exceed {FeedModel.COLUMN_SIZE_MeditationFileName}"));
            }
            if (feedModel.GoalTrackerName != null && feedModel.GoalTrackerName.Length > FeedModel.COLUMN_SIZE_GoalTrackerName)
            {
                result.Add(new ReturnErrorItem("GoalTrackerName", $"GoalTrackerName size should not exceed {FeedModel.COLUMN_SIZE_GoalTrackerName}"));
            }
            if (feedModel.GoalTrackerStartDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerStartDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerStartDate", $"GoalTrackerStartDate is not a valid date"));
            }
            if (feedModel.GoalTrackerEndDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerEndDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerEndDate", $"GoalTrackerEndDate is not a valid date"));
            }
            if (feedModel.GoalTrackerCompletedDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerCompletedDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerCompletedDate", $"GoalTrackerCompletedDate is not a valid date"));
            }
            if (feedModel.GoalTrackerMileStoneName != null && feedModel.GoalTrackerMileStoneName.Length > FeedModel.COLUMN_SIZE_GoalTrackerMileStoneName)
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneName", $"GoalTrackerMileStoneName size should not exceed {FeedModel.COLUMN_SIZE_GoalTrackerMileStoneName}"));
            }
            if (feedModel.GoalTrackerMileStoneStartDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerMileStoneStartDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneStartDate", $"GoalTrackerMileStoneStartDate is not a valid date"));
            }
            if (feedModel.GoalTrackerMileStoneEndDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerMileStoneEndDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneEndDate", $"GoalTrackerMileStoneEndDate is not a valid date"));
            }
            if (feedModel.GoalTrackerMileStoneCompletedDate != null && !DateUtils.IsValidDate(feedModel.GoalTrackerMileStoneCompletedDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneCompletedDate", $"GoalTrackerMileStoneCompletedDate is not a valid date"));
            }


            return result.Count > 0 ? result : null;
        }



