        public async Task<ReturnModel<bool>> UploadFeedFileAsync(long feedId, FileStreamModel streamModel)
        {
            try
            {
                var feed = await GetFeedByIdForWriteAsync(feedId);
                if (!feed.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(feed);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(feed.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(feed.Model.UserId, feed.Model.FeedId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(feed.Model.UserId, feed.Model.FeedId, streamModel.FileName);
                        await productRepository.UpdateFeedFilePathAsync(feed.Model.FeedId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(feed.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Feed File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearFeedFileAsync(long feedId)
        {
            try
            {
                var feed = await GetFeedByIdForWriteAsync(feedId);
                if (!feed.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(feed);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearFeedFilePathAsync(feed.Model.FeedId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(feed.Model.UserId, feed.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Feed File", ex);
            }
        }

        public async Task CreateOrUpdateFeedDependentsAsync(FeedUpdateModel model)
        {
            if (model.NewFeedXYZZYXModels == null)
                model.NewFeedXYZZYXModels = new List<FeedXYZZYXCreateModel>();

            if (model.ExistingFeedXYZZYXModels == null)
                model.ExistingFeedXYZZYXModels = new List<FeedXYZZYXUpdateModel>();

            var dbExistingFeeds = await manifestRepository.GetFeedXYZZYXsByFeedIdAsync(model.FeedId);
            if (!dbExistingFeeds.IsNullOrEmpty())
            {
                var dbExistingFeedIds = dbExistingFeeds.SelectToList(x => x.FeedXYZZYXId);
                var modelExistingFeedIds = model.ExistingFeedXYZZYXModels.SelectToList(x => x.FeedXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingFeeds.Where(x => !modelExistingFeedIds.Contains(x.FeedXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkFeedXYZZYXAsDeletedByIdAsync(x.FeedXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingFeedXYZZYXModels.Where(x => dbExistingFeedIds.Contains(x.FeedXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.FeedId = model.FeedId;
                    var result = await UpdateFeedXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewFeedXYZZYXModels)
            {
                x.FeedId = model.FeedId;
                var result = await CreateFeedXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableFeedByIdAsync(long feedId)
        {
            try
            {
                var existingFeedModel = await GetFeedByIdForWriteAsync(feedId);
                if (!existingFeedModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<FeedModel>(existingFeedModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingFeedModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableFeedByIdAsync(existingFeedModel.Model.FeedId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.FeedEnabledAsync(feedId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Feed", new { feedId }, ex);
            }
        }

