        public async Task<ReturnModel<bool>> AssociateXYZZYXWithFeedAsync(FeedXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsFeedWithFeedAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Feed association is invalid", errorLst);
                }

                if (await manifestRepository.DoesFeedWithXYZZYXAssociationExistsAsync(model.FeedId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Feed is already associated with the Feed", new { model.FeedId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateFeedWithXYZZYXAsync(model.FeedId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Feed with XYZZYX", new { model.FeedId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Feed with XYZZYX", new { model.FeedId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithFeedAsync(FeedXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsFeedWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Feed association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesFeedWithXYZZYXAssociationExistsAsync(model.FeedId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Feed is not associated with the Feed", new { model.FeedId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateFeedWithFeedAsync(model.FeedId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Feed with the Feed", new { model.FeedId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Feed with the Feed", new { model.FeedId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsFeedWithXYZZYXAssociationValidAsync(FeedXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.FeedId == 0)
            {
                result.Add(new ReturnErrorItem("", "Feed is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Feed  is not valid"));
                return result;
            }

            var entity = await GetFeedForWriteByIdAsync(model.FeedId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Feed information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Feeds does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

