        public async Task<ReturnModel<GoalTrackerModel>> GetGoalTrackerByIdInternalAsync(bool forWrite, long goalTrackerId)
        {
            try
            {
                var item = await manifestRepository.GetGoalTrackerViewByIdAsync(goalTrackerId);
                if (item == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>($"Unable to find the Goal Tracker", new { goalTrackerId });
                }

                //var existingMovieModel = forWrite ? await GetMovieByIdForWriteAsync(item.MovieId) : await GetMovieByIdForReadAsync(item.MovieId);
                //if (!existingMovieModel.IsSuccess)
                //{
                //    return log.ErrorAndReturnModel<CompanyModel>(existingMovieModel);
                //}

                var (resultValue, _, errorStr) = await permissionService.CanModifyResource(item.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>(errorStr);
                }

                var result = this.ConvertToItem(item,objectMapperService.GoalTrackerViewToGoalTrackerModel);

                var childItems = await manifestRepository.GetGoalTrackerMileStoneViewByGoalTrackerIdAsync(goalTrackerId);
                result.Model.ExistingGoalTrackerMileStones = this.ConvertToList<GoalTrackerMileStoneView, GoalTrackerMileStoneModel>(childItems, objectMapperService.GoalTrackerMileStoneViewListToGoalTrackerMileStoneModelList).Model;

                var cchildItems = await manifestRepository.GetBareCategoryByGoalTrackerIdAsync(item.GoalTrackerId);
                result.Model.ExistingCategorys = this.ConvertToList<Category,CategoryModel>(cchildItems, objectMapperService.CategoryListToCategoryModelList).Model;

                return result;
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<GoalTrackerModel>($"Unexpected error when getting Goal Tracker", new { goalTrackerId }, ex);
            }
        }

        public async Task<ReturnListModel<GoalTrackerModel>> CreateMultipleGoalTrackerAsync(MultipleGoalTrackerCreateModel goalTrackers)
        {
            try
            {
                if (goalTrackers == null)
                {
                    return log.ErrorAndReturnListModel<GoalTrackerModel>($"Unable to Create Goal Trackers", new ReturnErrorItem("", "Goal Trackers information is not valid"));
                }

                if (goalTrackers.NewGoalTrackers.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<GoalTrackerModel>($"Unable to Create Goal Trackers", new ReturnErrorItem("", "Goal Trackers information is not provided"));
                }

                var lst = new List<GoalTrackerModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var goalTracker in goalTrackers.NewGoalTrackers)
                    {
                        var cResult = await CreateGoalTrackerAsync(goalTracker);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<GoalTrackerModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<GoalTrackerModel>($"Unexpected error when creating Goal Trackers", new { goalTrackers }, ex);
            }
        }

