        public async Task<ReturnModel<GoalTrackerModel>> UpdateGoalTrackerAsync(GoalTrackerUpdateModel goalTracker)
        {
            try
            {
                if (goalTracker == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>($"Unable to update Goal Tracker", new ReturnErrorItem("", "Goal Tracker information is not valid"));
                }

                var existingGoalTrackerModel = await GetGoalTrackerByIdForWriteAsync(goalTracker.GoalTrackerId);
                if (!existingGoalTrackerModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>(existingGoalTrackerModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(goalTracker.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>(errorStr);
                }

                if (canAssign)
                {
                    goalTracker.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                goalTracker.CreatedByUserId = existingGoalTrackerModel.Model.CreatedByUserId;
                goalTracker.CreatedDate = existingGoalTrackerModel.Model.CreatedDate;
                goalTracker.IsDeleted = existingGoalTrackerModel.Model.IsDeleted;
                goalTracker.UserId = existingGoalTrackerModel.Model.UserId;
                //goalTracker.MovieId = existingGoalTrackerModel.Model.MovieId;
                //goalTracker.ProfileImageActualFileName = existingGoalTrackerModel.Model.ProfileImageActualFileName;
                //goalTracker.ProfileImageLocation = existingGoalTrackerModel.Model.ProfileImageLocation;



                var errorList = await IsGoalTrackerModelValidForUpdateAsync(goalTracker);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>($"Unable to update Goal Tracker", errorList);
                }

                var item = objectMapperService.GoalTrackerUpdateModelToGoalTracker(goalTracker);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateGoalTrackerAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Goal Tracker");
                    }

                    await CreateOrUpdateGoalTrackerDependentsAsync(goalTracker);

                    await trx.CompleteAsync();
                }

                await auditService.GoalTrackerUpdatedAsync(goalTracker.GoalTrackerId);

                var view = await manifestRepository.GetGoalTrackerViewByIdAsync(goalTracker.GoalTrackerId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerModel>($"Unable to find the Goal Tracker", new { goalTracker.GoalTrackerId });
                }

                return this.ConvertToItem(view, objectMapperService.GoalTrackerViewToGoalTrackerModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<GoalTrackerModel>($"Unexpected error when updating Goal Tracker", new { goalTracker?.GoalTrackerId }, ex);
            }
        }

