        public async Task<List<ReturnErrorItem>> IsGoalTrackerModelValidForAllAsync(bool isCreate, GoalTrackerUpdateModel goalTrackerModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsGoalTrackerNameAlreadyExistsForOtherGoalTrackerAsync(goalTrackerModel.GoalTrackerName, goalTrackerModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Goal Tracker already exists"));
                }

                if (goalTrackerModel.GoalTrackerId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsGoalTrackerNameAlreadyExistsForOtherGoalTrackerAsync(goalTrackerModel.GoalTrackerId, goalTrackerModel.GoalTrackerName, goalTrackerModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Goal Tracker already exists"));
                }

                if (goalTrackerModel.GoalTrackerId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(goalTrackerModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != goalTrackerModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (goalTrackerModel.GoalTrackerName != null && goalTrackerModel.GoalTrackerName.Length > GoalTrackerModel.COLUMN_SIZE_GoalTrackerName)
            {
                result.Add(new ReturnErrorItem("GoalTrackerName", $"GoalTrackerName size should not exceed {GoalTrackerModel.COLUMN_SIZE_GoalTrackerName}"));
            }
            if (goalTrackerModel.GoalTrackerName == null)
            {
                result.Add(new ReturnErrorItem("GoalTrackerName", "GoalTrackerName is required "));
            }
            if (goalTrackerModel.PredefinedGoalStatusTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedGoalStatusTypeId", "PredefinedGoalStatusTypeId cannot be empty"));
            }
            if (goalTrackerModel.GoalTrackerStartDate != null && !DateUtils.IsValidDate(goalTrackerModel.GoalTrackerStartDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerStartDate", $"GoalTrackerStartDate is not a valid date"));
            }
            if (goalTrackerModel.GoalTrackerEndDate != null && !DateUtils.IsValidDate(goalTrackerModel.GoalTrackerEndDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerEndDate", $"GoalTrackerEndDate is not a valid date"));
            }
            if (goalTrackerModel.GoalTrackerCompletedDate != null && !DateUtils.IsValidDate(goalTrackerModel.GoalTrackerCompletedDate.Value))
            {
                result.Add(new ReturnErrorItem("GoalTrackerCompletedDate", $"GoalTrackerCompletedDate is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(goalTrackerModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(goalTrackerModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != goalTrackerModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }
            if (goalTrackerModel.AddedToFeedDate != null && !DateUtils.IsValidDate(goalTrackerModel.AddedToFeedDate.Value))
            {
                result.Add(new ReturnErrorItem("AddedToFeedDate", $"AddedToFeedDate is not a valid date"));
            }

            if (!ValidationUtils.IsEnumValid<PredefinedGoalPriorityTypes, long>(goalTrackerModel.PredefinedGoalPriorityTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedGoalPriorityTypeId", "Priority Type is not valid"));
            }

            return result.Count > 0 ? result : null;
        }



