        public async Task<ReturnModel<bool>> UploadGoalTrackerFileAsync(long goalTrackerId, FileStreamModel streamModel)
        {
            try
            {
                var goalTracker = await GetGoalTrackerByIdForWriteAsync(goalTrackerId);
                if (!goalTracker.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(goalTracker);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(goalTracker.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(goalTracker.Model.UserId, goalTracker.Model.GoalTrackerId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(goalTracker.Model.UserId, goalTracker.Model.GoalTrackerId, streamModel.FileName);
                        await productRepository.UpdateGoalTrackerFilePathAsync(goalTracker.Model.GoalTrackerId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(goalTracker.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Goal Tracker File", ex);
            }
        }

