        public async Task<ReturnModel<bool>> AssociateXYZZYXWithGoalTrackerAsync(GoalTrackerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerWithGoalTrackerAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker association is invalid", errorLst);
                }

                if (await manifestRepository.DoesGoalTrackerWithXYZZYXAssociationExistsAsync(model.GoalTrackerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker is already associated with the Goal Tracker", new { model.GoalTrackerId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateGoalTrackerWithXYZZYXAsync(model.GoalTrackerId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Goal Tracker with XYZZYX", new { model.GoalTrackerId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Goal Tracker with XYZZYX", new { model.GoalTrackerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithGoalTrackerAsync(GoalTrackerXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesGoalTrackerWithXYZZYXAssociationExistsAsync(model.GoalTrackerId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker is not associated with the Goal Tracker", new { model.GoalTrackerId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateGoalTrackerWithGoalTrackerAsync(model.GoalTrackerId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Goal Tracker with the Goal Tracker", new { model.GoalTrackerId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Goal Tracker with the Goal Tracker", new { model.GoalTrackerId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsGoalTrackerWithXYZZYXAssociationValidAsync(GoalTrackerXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.GoalTrackerId == 0)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Goal Tracker  is not valid"));
                return result;
            }

            var entity = await GetGoalTrackerForWriteByIdAsync(model.GoalTrackerId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Goal Trackers does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

        public async Task<ReturnListModel<ImportStatusModel>> ImportGoalTrackerAsync(GoalTrackerImportModel model, bool isTest)
        {
            try
            {
                if (model == null)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Goal Tracker Import Info is not provided");
                }

                if (model.GoalTrackers == null || model.GoalTrackers.Count == 0)
                {
                    return log.ErrorAndReturnListModel<ImportStatusModel>("Goal Trackers Info is not available to import");
                }

                var resultLst = new List<ImportStatusModel>();

                foreach (var item in model.GoalTrackers)
                {
                    var prod = await wipService.GetGoalTrackerByExternalIdentifierAsync(item.GoalTrackerIdentifier);
                    if (prod.Model == null)
                    {
                        //var newProd = new ProductCreateModel();
                        GoalTrackerCreateModel goalTrackerCreateModel = new GoalTrackerCreateModel
                        {
                            IsEnabled = item.IsProductEnabled
                        };

                        var newlyCreatedGoalTracker = await CreateGoalTrackerAsync(goalTrackerCreateModel);
                        if (!newlyCreatedGoalTracker.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (newlyCreatedGoalTracker.ErrorHolder.ErrorItemList != null && newlyCreatedProd.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = newlyCreatedGoalTracker.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : newlyCreatedProd.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                    else
                    {
                        GoalTrackerUpdateModel goalTrackerUpdateModel = new GoalTrackerUpdateModel
                        {
                        };

                        //update product
                        var updatedGoalTrackerModel = await wipService.UpdateGoalTrackerAsync(goalTrackerUpdateModel);
                        if (!updatedGoalTrackerModel.IsSuccess)
                        {
                            var errorStr = string.Empty;
                            if (updateProdModel.ErrorHolder.ErrorItemList != null && updateProdModel.ErrorHolder.ErrorItemList.Count > 0)
                            {
                                var errorValueList = updateProdModel.ErrorHolder.ErrorItemList.SelectToList(x => x.Value);
                                errorStr = string.Join(",", errorValueList);
                            }

                            resultLst.Add(new ImportStatusModel() { IsSucess = false, Message = errorStr.IsNotNullOrEmpty() ? errorStr : updateProdModel.ErrorHolder.FriendlyMessage });
                            continue;
                        }
                        else
                        {
                            resultLst.Add(new ImportStatusModel() { IsSucess = true });
                        }
                    }
                }

                return ReturnListModel<ImportStatusModel>.Success(resultLst);
            }
