        public async Task<ReturnListModel<GoalTrackerCategoryModel>> CreateMultipleGoalTrackerCategoryAsync(MultipleGoalTrackerCategoryCreateModel goalTrackerCategorys)
        {
            try
            {
                if (goalTrackerCategorys == null)
                {
                    return log.ErrorAndReturnListModel<GoalTrackerCategoryModel>($"Unable to Create Goal Tracker Categorys", new ReturnErrorItem("", "Goal Tracker Categorys information is not valid"));
                }

                if (goalTrackerCategorys.NewGoalTrackerCategorys.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<GoalTrackerCategoryModel>($"Unable to Create Goal Tracker Categorys", new ReturnErrorItem("", "Goal Tracker Categorys information is not provided"));
                }

                var lst = new List<GoalTrackerCategoryModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var goalTrackerCategory in goalTrackerCategorys.NewGoalTrackerCategorys)
                    {
                        var cResult = await CreateGoalTrackerCategoryAsync(goalTrackerCategory);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<GoalTrackerCategoryModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<GoalTrackerCategoryModel>($"Unexpected error when creating Goal Tracker Categorys", new { goalTrackerCategorys }, ex);
            }
        }

