        public async Task<ReturnModel<GoalTrackerCategoryModel>> UpdateGoalTrackerCategoryAsync(GoalTrackerCategoryUpdateModel goalTrackerCategory)
        {
            try
            {
                if (goalTrackerCategory == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>($"Unable to update Goal Tracker Category", new ReturnErrorItem("", "Goal Tracker Category information is not valid"));
                }

                var existingGoalTrackerCategoryModel = await GetGoalTrackerCategoryByIdForWriteAsync(goalTrackerCategory.GoalTrackerCategoryId);
                if (!existingGoalTrackerCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>(existingGoalTrackerCategoryModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(goalTrackerCategory.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>(errorStr);
                }

                if (canAssign)
                {
                    goalTrackerCategory.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                goalTrackerCategory.CreatedByUserId = existingGoalTrackerCategoryModel.Model.CreatedByUserId;
                goalTrackerCategory.CreatedDate = existingGoalTrackerCategoryModel.Model.CreatedDate;
                goalTrackerCategory.IsDeleted = existingGoalTrackerCategoryModel.Model.IsDeleted;
                goalTrackerCategory.UserId = existingGoalTrackerCategoryModel.Model.UserId;
                //goalTrackerCategory.MovieId = existingGoalTrackerCategoryModel.Model.MovieId;
                //goalTrackerCategory.ProfileImageActualFileName = existingGoalTrackerCategoryModel.Model.ProfileImageActualFileName;
                //goalTrackerCategory.ProfileImageLocation = existingGoalTrackerCategoryModel.Model.ProfileImageLocation;



                var errorList = await IsGoalTrackerCategoryModelValidForUpdateAsync(goalTrackerCategory);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>($"Unable to update Goal Tracker Category", errorList);
                }

                var item = objectMapperService.GoalTrackerCategoryUpdateModelToGoalTrackerCategory(goalTrackerCategory);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateGoalTrackerCategoryAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Goal Tracker Category");
                    }

                    //await CreateOrUpdateGoalTrackerCategoryDependentsAsync(goalTrackerCategory)

                    await trx.CompleteAsync();
                }

                await auditService.GoalTrackerCategoryUpdatedAsync(goalTrackerCategory.GoalTrackerCategoryId);

                var view = await manifestRepository.GetGoalTrackerCategoryViewByIdAsync(goalTrackerCategory.GoalTrackerCategoryId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>($"Unable to find the Goal Tracker Category", new { goalTrackerCategory.GoalTrackerCategoryId });
                }

                return this.ConvertToItem(view, objectMapperService.GoalTrackerCategoryViewToGoalTrackerCategoryModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<GoalTrackerCategoryModel>($"Unexpected error when updating Goal Tracker Category", new { goalTrackerCategory?.GoalTrackerCategoryId }, ex);
            }
        }

