        public Task<List<ReturnErrorItem>> IsGoalTrackerCategoryModelValidForUpdateAsync(GoalTrackerCategoryUpdateModel goalTrackerCategoryModel)
        {
            return IsGoalTrackerCategoryModelValidForAllAsync(false, goalTrackerCategoryModel);
        }

        public async Task<List<ReturnErrorItem>> IsGoalTrackerCategoryModelValidForAllAsync(bool isCreate, GoalTrackerCategoryUpdateModel goalTrackerCategoryModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (goalTrackerCategoryModel.GoalTrackerCategoryId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Category Identifier is not valid"));
                }
            }
            else
            {
                if (goalTrackerCategoryModel.GoalTrackerCategoryId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Category Unique Identifier is not valid"));
                }
            }

            var categoryItem = await manifestRepository.GetCategoryViewByIdAsync(goalTrackerCategoryModel.CategoryId);
            if (categoryItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the Category Information"));
                return result;
            }

            if (categoryItem.UserId != goalTrackerCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this Category Information"));
                return result;
            }


            var goalTrackerItem = await manifestRepository.GetGoalTrackerViewByIdAsync(goalTrackerCategoryModel.GoalTrackerId);
            if (goalTrackerItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the GoalTracker Information"));
                return result;
            }

            if (goalTrackerItem.UserId != goalTrackerCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this GoalTracker Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(goalTrackerCategoryModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != goalTrackerCategoryModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!ValidationUtils.IsLongValid(goalTrackerCategoryModel.CategoryId))
            {
                result.Add(new ReturnErrorItem("CategoryId", "Category cannot be empty"));
            }
            else
            {
                var itemForCategory = await manifestRepository.GetCategoryByIdAsync(goalTrackerCategoryModel.CategoryId);
                if (itemForCategory == null)
                {
                    result.Add(new ReturnErrorItem("CategoryId", "Category is not available"));
                }
                else
                {
                    if (itemForCategory.UserId != goalTrackerCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("CategoryId", "Category does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(goalTrackerCategoryModel.GoalTrackerId))
            {
                result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker cannot be empty"));
            }
            else
            {
                var itemForGoalTracker = await manifestRepository.GetGoalTrackerByIdAsync(goalTrackerCategoryModel.GoalTrackerId);
                if (itemForGoalTracker == null)
                {
                    result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker is not available"));
                }
                else
                {
                    if (itemForGoalTracker.UserId != goalTrackerCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(goalTrackerCategoryModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(goalTrackerCategoryModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != goalTrackerCategoryModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



