        public async Task<ReturnModel<bool>> UploadGoalTrackerCategoryFileAsync(long goalTrackerCategoryId, FileStreamModel streamModel)
        {
            try
            {
                var goalTrackerCategory = await GetGoalTrackerCategoryByIdForWriteAsync(goalTrackerCategoryId);
                if (!goalTrackerCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(goalTrackerCategory);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(goalTrackerCategory.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(goalTrackerCategory.Model.UserId, goalTrackerCategory.Model.GoalTrackerCategoryId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(goalTrackerCategory.Model.UserId, goalTrackerCategory.Model.GoalTrackerCategoryId, streamModel.FileName);
                        await productRepository.UpdateGoalTrackerCategoryFilePathAsync(goalTrackerCategory.Model.GoalTrackerCategoryId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(goalTrackerCategory.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Goal Tracker Category File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearGoalTrackerCategoryFileAsync(long goalTrackerCategoryId)
        {
            try
            {
                var goalTrackerCategory = await GetGoalTrackerCategoryByIdForWriteAsync(goalTrackerCategoryId);
                if (!goalTrackerCategory.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(goalTrackerCategory);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearGoalTrackerCategoryFilePathAsync(goalTrackerCategory.Model.GoalTrackerCategoryId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(goalTrackerCategory.Model.UserId, goalTrackerCategory.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Goal Tracker Category File", ex);
            }
        }

        public async Task CreateOrUpdateGoalTrackerCategoryDependentsAsync(GoalTrackerCategoryUpdateModel model)
        {
            if (model.NewGoalTrackerCategoryXYZZYXModels == null)
                model.NewGoalTrackerCategoryXYZZYXModels = new List<GoalTrackerCategoryXYZZYXCreateModel>();

            if (model.ExistingGoalTrackerCategoryXYZZYXModels == null)
                model.ExistingGoalTrackerCategoryXYZZYXModels = new List<GoalTrackerCategoryXYZZYXUpdateModel>();

            var dbExistingGoalTrackerCategorys = await manifestRepository.GetGoalTrackerCategoryXYZZYXsByGoalTrackerCategoryIdAsync(model.GoalTrackerCategoryId);
            if (!dbExistingGoalTrackerCategorys.IsNullOrEmpty())
            {
                var dbExistingGoalTrackerCategoryIds = dbExistingGoalTrackerCategorys.SelectToList(x => x.GoalTrackerCategoryXYZZYXId);
                var modelExistingGoalTrackerCategoryIds = model.ExistingGoalTrackerCategoryXYZZYXModels.SelectToList(x => x.GoalTrackerCategoryXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingGoalTrackerCategorys.Where(x => !modelExistingGoalTrackerCategoryIds.Contains(x.GoalTrackerCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkGoalTrackerCategoryXYZZYXAsDeletedByIdAsync(x.GoalTrackerCategoryXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingGoalTrackerCategoryXYZZYXModels.Where(x => dbExistingGoalTrackerCategoryIds.Contains(x.GoalTrackerCategoryXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.GoalTrackerCategoryId = model.GoalTrackerCategoryId;
                    var result = await UpdateGoalTrackerCategoryXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewGoalTrackerCategoryXYZZYXModels)
            {
                x.GoalTrackerCategoryId = model.GoalTrackerCategoryId;
                var result = await CreateGoalTrackerCategoryXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableGoalTrackerCategoryByIdAsync(long goalTrackerCategoryId)
        {
            try
            {
                var existingGoalTrackerCategoryModel = await GetGoalTrackerCategoryByIdForWriteAsync(goalTrackerCategoryId);
                if (!existingGoalTrackerCategoryModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<GoalTrackerCategoryModel>(existingGoalTrackerCategoryModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingGoalTrackerCategoryModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableGoalTrackerCategoryByIdAsync(existingGoalTrackerCategoryModel.Model.GoalTrackerCategoryId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.GoalTrackerCategoryEnabledAsync(goalTrackerCategoryId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Goal Tracker Category", new { goalTrackerCategoryId }, ex);
            }
        }

