        public async Task<ReturnModel<bool>> AssociateXYZZYXWithGoalTrackerCategoryAsync(GoalTrackerCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerCategoryWithGoalTrackerCategoryAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker Category association is invalid", errorLst);
                }

                if (await manifestRepository.DoesGoalTrackerCategoryWithXYZZYXAssociationExistsAsync(model.GoalTrackerCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker Category is already associated with the Goal Tracker Category", new { model.GoalTrackerCategoryId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateGoalTrackerCategoryWithXYZZYXAsync(model.GoalTrackerCategoryId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Goal Tracker Category with XYZZYX", new { model.GoalTrackerCategoryId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Goal Tracker Category with XYZZYX", new { model.GoalTrackerCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithGoalTrackerCategoryAsync(GoalTrackerCategoryXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerCategoryWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker Category association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesGoalTrackerCategoryWithXYZZYXAssociationExistsAsync(model.GoalTrackerCategoryId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker Category is not associated with the Goal Tracker Category", new { model.GoalTrackerCategoryId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateGoalTrackerCategoryWithGoalTrackerCategoryAsync(model.GoalTrackerCategoryId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Goal Tracker Category with the Goal Tracker Category", new { model.GoalTrackerCategoryId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Goal Tracker Category with the Goal Tracker Category", new { model.GoalTrackerCategoryId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsGoalTrackerCategoryWithXYZZYXAssociationValidAsync(GoalTrackerCategoryXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.GoalTrackerCategoryId == 0)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Category is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Goal Tracker Category  is not valid"));
                return result;
            }

            var entity = await GetGoalTrackerCategoryForWriteByIdAsync(model.GoalTrackerCategoryId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Category information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Categorys does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

