        public async Task<ReturnListModel<GoalTrackerMileStoneModel>> CreateMultipleGoalTrackerMileStoneAsync(MultipleGoalTrackerMileStoneCreateModel goalTrackerMileStones)
        {
            try
            {
                if (goalTrackerMileStones == null)
                {
                    return log.ErrorAndReturnListModel<GoalTrackerMileStoneModel>($"Unable to Create Goal Tracker Mile Stones", new ReturnErrorItem("", "Goal Tracker Mile Stones information is not valid"));
                }

                if (goalTrackerMileStones.NewGoalTrackerMileStones.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<GoalTrackerMileStoneModel>($"Unable to Create Goal Tracker Mile Stones", new ReturnErrorItem("", "Goal Tracker Mile Stones information is not provided"));
                }

                var lst = new List<GoalTrackerMileStoneModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var goalTrackerMileStone in goalTrackerMileStones.NewGoalTrackerMileStones)
                    {
                        var cResult = await CreateGoalTrackerMileStoneAsync(goalTrackerMileStone);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<GoalTrackerMileStoneModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<GoalTrackerMileStoneModel>($"Unexpected error when creating Goal Tracker Mile Stones", new { goalTrackerMileStones }, ex);
            }
        }

