        public async Task<ReturnModel<GoalTrackerMileStoneModel>> UpdateGoalTrackerMileStoneAsync(GoalTrackerMileStoneUpdateModel goalTrackerMileStone)
        {
            try
            {
                if (goalTrackerMileStone == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>($"Unable to update Goal Tracker Mile Stone", new ReturnErrorItem("", "Goal Tracker Mile Stone information is not valid"));
                }

                var existingGoalTrackerMileStoneModel = await GetGoalTrackerMileStoneByIdForWriteAsync(goalTrackerMileStone.GoalTrackerMileStoneId);
                if (!existingGoalTrackerMileStoneModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>(existingGoalTrackerMileStoneModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(goalTrackerMileStone.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>(errorStr);
                }

                if (canAssign)
                {
                    goalTrackerMileStone.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                goalTrackerMileStone.CreatedByUserId = existingGoalTrackerMileStoneModel.Model.CreatedByUserId;
                goalTrackerMileStone.CreatedDate = existingGoalTrackerMileStoneModel.Model.CreatedDate;
                goalTrackerMileStone.IsDeleted = existingGoalTrackerMileStoneModel.Model.IsDeleted;
                goalTrackerMileStone.UserId = existingGoalTrackerMileStoneModel.Model.UserId;
                //goalTrackerMileStone.MovieId = existingGoalTrackerMileStoneModel.Model.MovieId;
                //goalTrackerMileStone.ProfileImageActualFileName = existingGoalTrackerMileStoneModel.Model.ProfileImageActualFileName;
                //goalTrackerMileStone.ProfileImageLocation = existingGoalTrackerMileStoneModel.Model.ProfileImageLocation;



                var errorList = await IsGoalTrackerMileStoneModelValidForUpdateAsync(goalTrackerMileStone);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>($"Unable to update Goal Tracker Mile Stone", errorList);
                }

                var item = objectMapperService.GoalTrackerMileStoneUpdateModelToGoalTrackerMileStone(goalTrackerMileStone);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateGoalTrackerMileStoneAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Goal Tracker Mile Stone");
                    }

                    //await CreateOrUpdateGoalTrackerMileStoneDependentsAsync(goalTrackerMileStone)

                    await trx.CompleteAsync();
                }

                await auditService.GoalTrackerMileStoneUpdatedAsync(goalTrackerMileStone.GoalTrackerMileStoneId);

                var view = await manifestRepository.GetGoalTrackerMileStoneViewByIdAsync(goalTrackerMileStone.GoalTrackerMileStoneId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>($"Unable to find the Goal Tracker Mile Stone", new { goalTrackerMileStone.GoalTrackerMileStoneId });
                }

                return this.ConvertToItem(view, objectMapperService.GoalTrackerMileStoneViewToGoalTrackerMileStoneModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>($"Unexpected error when updating Goal Tracker Mile Stone", new { goalTrackerMileStone?.GoalTrackerMileStoneId }, ex);
            }
        }

