        public Task<List<ReturnErrorItem>> IsGoalTrackerMileStoneModelValidForUpdateAsync(GoalTrackerMileStoneUpdateModel goalTrackerMileStoneModel)
        {
            return IsGoalTrackerMileStoneModelValidForAllAsync(false, goalTrackerMileStoneModel);
        }

        public async Task<List<ReturnErrorItem>> IsGoalTrackerMileStoneModelValidForAllAsync(bool isCreate, GoalTrackerMileStoneUpdateModel goalTrackerMileStoneModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsGoalTrackerMileStoneNameAlreadyExistsForOtherGoalTrackerMileStoneAsync(goalTrackerMileStoneModel.GoalTrackerMileStoneName, goalTrackerMileStoneModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Goal Tracker Mile Stone already exists"));
                }

                if (goalTrackerMileStoneModel.GoalTrackerMileStoneId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Mile Stone Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsGoalTrackerMileStoneNameAlreadyExistsForOtherGoalTrackerMileStoneAsync(goalTrackerMileStoneModel.GoalTrackerMileStoneId, goalTrackerMileStoneModel.GoalTrackerMileStoneName, goalTrackerMileStoneModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Goal Tracker Mile Stone already exists"));
                }

                if (goalTrackerMileStoneModel.GoalTrackerMileStoneId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Goal Tracker Mile Stone Unique Identifier is not valid"));
                }
            }

            var goalTrackerItem = await manifestRepository.GetGoalTrackerViewByIdAsync(goalTrackerMileStoneModel.GoalTrackerId);
            if (goalTrackerItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the GoalTracker Information"));
                return result;
            }

            if (goalTrackerItem.UserId != goalTrackerMileStoneModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this GoalTracker Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(goalTrackerMileStoneModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != goalTrackerMileStoneModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!ValidationUtils.IsLongValid(goalTrackerMileStoneModel.GoalTrackerId))
            {
                result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker cannot be empty"));
            }
            else
            {
                var itemForGoalTracker = await manifestRepository.GetGoalTrackerByIdAsync(goalTrackerMileStoneModel.GoalTrackerId);
                if (itemForGoalTracker == null)
                {
                    result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker is not available"));
                }
                else
                {
                    if (itemForGoalTracker.UserId != goalTrackerMileStoneModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("GoalTrackerId", "GoalTracker does not belong to you."));
                    }
                }
            }
            if (goalTrackerMileStoneModel.GoalTrackerMileStoneName != null && goalTrackerMileStoneModel.GoalTrackerMileStoneName.Length > GoalTrackerMileStoneModel.COLUMN_SIZE_GoalTrackerMileStoneName)
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneName", $"MileStone Name size should not exceed {GoalTrackerMileStoneModel.COLUMN_SIZE_GoalTrackerMileStoneName}"));
            }
            if (goalTrackerMileStoneModel.GoalTrackerMileStoneName == null)
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneName", "MileStone Text is required "));
            }
            if (goalTrackerMileStoneModel.GoalTrackerMileStoneStartDate != null && !DateUtils.IsValidDate(goalTrackerMileStoneModel.GoalTrackerMileStoneStartDate))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneStartDate", $"Mile Stone Start Date is not a valid date"));
            }
            if (goalTrackerMileStoneModel.GoalTrackerMileStoneEndDate != null && !DateUtils.IsValidDate(goalTrackerMileStoneModel.GoalTrackerMileStoneEndDate))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneEndDate", $"Mile Stone End Date is not a valid date"));
            }
            if (goalTrackerMileStoneModel.PredefinedGoalStatusTypeId == 0 || ValidationUtils.IsEnumValid<PredefinedGoalStatusTypes,long>(goalTrackerMileStoneModel.PredefinedGoalStatusTypeId))
            {
                result.Add(new ReturnErrorItem("PredefinedGoalStatusTypeId", "Goal Status Type cannot be empty"));
            }
            if (goalTrackerMileStoneModel.GoalTrackerMileStoneCompletedDate != null && !DateUtils.IsValidDate(goalTrackerMileStoneModel.GoalTrackerMileStoneCompletedDate))
            {
                result.Add(new ReturnErrorItem("GoalTrackerMileStoneCompletedDate", $"Mile Stone Completed Date is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(goalTrackerMileStoneModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(goalTrackerMileStoneModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != goalTrackerMileStoneModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }

