        public async Task<ReturnModel<bool>> UploadGoalTrackerMileStoneFileAsync(long goalTrackerMileStoneId, FileStreamModel streamModel)
        {
            try
            {
                var goalTrackerMileStone = await GetGoalTrackerMileStoneByIdForWriteAsync(goalTrackerMileStoneId);
                if (!goalTrackerMileStone.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(goalTrackerMileStone);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(goalTrackerMileStone.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(goalTrackerMileStone.Model.UserId, goalTrackerMileStone.Model.GoalTrackerMileStoneId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(goalTrackerMileStone.Model.UserId, goalTrackerMileStone.Model.GoalTrackerMileStoneId, streamModel.FileName);
                        await productRepository.UpdateGoalTrackerMileStoneFilePathAsync(goalTrackerMileStone.Model.GoalTrackerMileStoneId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(goalTrackerMileStone.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Goal Tracker Mile Stone File", ex);
            }
        }

        public async Task<ReturnModel<bool>> ClearGoalTrackerMileStoneFileAsync(long goalTrackerMileStoneId)
        {
            try
            {
                var goalTrackerMileStone = await GetGoalTrackerMileStoneByIdForWriteAsync(goalTrackerMileStoneId);
                if (!goalTrackerMileStone.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(goalTrackerMileStone);
                }

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    await productRepository.ClearGoalTrackerMileStoneFilePathAsync(goalTrackerMileStone.Model.GoalTrackerMileStoneId, await currentSessionService.GetCurrentUserIdAsync());
                    await profileFileFileStorage.DeleteAsync(goalTrackerMileStone.Model.UserId, goalTrackerMileStone.Model.ProfileImageLocation);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when clearing Goal Tracker Mile Stone File", ex);
            }
        }

        public async Task CreateOrUpdateGoalTrackerMileStoneDependentsAsync(GoalTrackerMileStoneUpdateModel model)
        {
            if (model.NewGoalTrackerMileStoneXYZZYXModels == null)
                model.NewGoalTrackerMileStoneXYZZYXModels = new List<GoalTrackerMileStoneXYZZYXCreateModel>();

            if (model.ExistingGoalTrackerMileStoneXYZZYXModels == null)
                model.ExistingGoalTrackerMileStoneXYZZYXModels = new List<GoalTrackerMileStoneXYZZYXUpdateModel>();

            var dbExistingGoalTrackerMileStones = await manifestRepository.GetGoalTrackerMileStoneXYZZYXsByGoalTrackerMileStoneIdAsync(model.GoalTrackerMileStoneId);
            if (!dbExistingGoalTrackerMileStones.IsNullOrEmpty())
            {
                var dbExistingGoalTrackerMileStoneIds = dbExistingGoalTrackerMileStones.SelectToList(x => x.GoalTrackerMileStoneXYZZYXId);
                var modelExistingGoalTrackerMileStoneIds = model.ExistingGoalTrackerMileStoneXYZZYXModels.SelectToList(x => x.GoalTrackerMileStoneXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingGoalTrackerMileStones.Where(x => !modelExistingGoalTrackerMileStoneIds.Contains(x.GoalTrackerMileStoneXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkGoalTrackerMileStoneXYZZYXAsDeletedByIdAsync(x.GoalTrackerMileStoneXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingGoalTrackerMileStoneXYZZYXModels.Where(x => dbExistingGoalTrackerMileStoneIds.Contains(x.GoalTrackerMileStoneXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.GoalTrackerMileStoneId = model.GoalTrackerMileStoneId;
                    var result = await UpdateGoalTrackerMileStoneXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewGoalTrackerMileStoneXYZZYXModels)
            {
                x.GoalTrackerMileStoneId = model.GoalTrackerMileStoneId;
                var result = await CreateGoalTrackerMileStoneXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableGoalTrackerMileStoneByIdAsync(long goalTrackerMileStoneId)
        {
            try
            {
                var existingGoalTrackerMileStoneModel = await GetGoalTrackerMileStoneByIdForWriteAsync(goalTrackerMileStoneId);
                if (!existingGoalTrackerMileStoneModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<GoalTrackerMileStoneModel>(existingGoalTrackerMileStoneModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingGoalTrackerMileStoneModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableGoalTrackerMileStoneByIdAsync(existingGoalTrackerMileStoneModel.Model.GoalTrackerMileStoneId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.GoalTrackerMileStoneEnabledAsync(goalTrackerMileStoneId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Goal Tracker Mile Stone", new { goalTrackerMileStoneId }, ex);
            }
        }

