        public async Task<ReturnModel<bool>> AssociateXYZZYXWithGoalTrackerMileStoneAsync(GoalTrackerMileStoneXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerMileStoneWithGoalTrackerMileStoneAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker Mile Stone association is invalid", errorLst);
                }

                if (await manifestRepository.DoesGoalTrackerMileStoneWithXYZZYXAssociationExistsAsync(model.GoalTrackerMileStoneId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker Mile Stone is already associated with the Goal Tracker Mile Stone", new { model.GoalTrackerMileStoneId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateGoalTrackerMileStoneWithXYZZYXAsync(model.GoalTrackerMileStoneId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Goal Tracker Mile Stone with XYZZYX", new { model.GoalTrackerMileStoneId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Goal Tracker Mile Stone with XYZZYX", new { model.GoalTrackerMileStoneId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithGoalTrackerMileStoneAsync(GoalTrackerMileStoneXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsGoalTrackerMileStoneWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Goal Tracker Mile Stone association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesGoalTrackerMileStoneWithXYZZYXAssociationExistsAsync(model.GoalTrackerMileStoneId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Goal Tracker Mile Stone is not associated with the Goal Tracker Mile Stone", new { model.GoalTrackerMileStoneId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateGoalTrackerMileStoneWithGoalTrackerMileStoneAsync(model.GoalTrackerMileStoneId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Goal Tracker Mile Stone with the Goal Tracker Mile Stone", new { model.GoalTrackerMileStoneId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Goal Tracker Mile Stone with the Goal Tracker Mile Stone", new { model.GoalTrackerMileStoneId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsGoalTrackerMileStoneWithXYZZYXAssociationValidAsync(GoalTrackerMileStoneXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.GoalTrackerMileStoneId == 0)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Mile Stone is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Goal Tracker Mile Stone  is not valid"));
                return result;
            }

            var entity = await GetGoalTrackerMileStoneForWriteByIdAsync(model.GoalTrackerMileStoneId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Mile Stone information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Goal Tracker Mile Stones does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

