        public async Task<ReturnListModel<MeditationFileModel>> CreateMultipleMeditationFileAsync(MultipleMeditationFileCreateModel meditationFiles)
        {
            try
            {
                if (meditationFiles == null)
                {
                    return log.ErrorAndReturnListModel<MeditationFileModel>($"Unable to Create Meditation Files", new ReturnErrorItem("", "Meditation Files information is not valid"));
                }

                if (meditationFiles.NewMeditationFiles.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<MeditationFileModel>($"Unable to Create Meditation Files", new ReturnErrorItem("", "Meditation Files information is not provided"));
                }

                var lst = new List<MeditationFileModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var meditationFile in meditationFiles.NewMeditationFiles)
                    {
                        var cResult = await CreateMeditationFileAsync(meditationFile);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<MeditationFileModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<MeditationFileModel>($"Unexpected error when creating Meditation Files", new { meditationFiles }, ex);
            }
        }

