        public async Task<ReturnModel<MeditationFileModel>> UpdateMeditationFileAsync(MeditationFileUpdateModel meditationFile)
        {
            try
            {
                if (meditationFile == null)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>($"Unable to update Meditation File", new ReturnErrorItem("", "Meditation File information is not valid"));
                }

                var existingMeditationFileModel = await GetMeditationFileByIdForWriteAsync(meditationFile.MeditationFileId);
                if (!existingMeditationFileModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>(existingMeditationFileModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(meditationFile.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>(errorStr);
                }

                if (canAssign)
                {
                    meditationFile.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                meditationFile.CreatedByUserId = existingMeditationFileModel.Model.CreatedByUserId;
                meditationFile.CreatedDate = existingMeditationFileModel.Model.CreatedDate;
                meditationFile.IsDeleted = existingMeditationFileModel.Model.IsDeleted;
                meditationFile.UserId = existingMeditationFileModel.Model.UserId;
                //meditationFile.MovieId = existingMeditationFileModel.Model.MovieId;
                //meditationFile.ProfileImageActualFileName = existingMeditationFileModel.Model.ProfileImageActualFileName;
                //meditationFile.ProfileImageLocation = existingMeditationFileModel.Model.ProfileImageLocation;



                var errorList = await IsMeditationFileModelValidForUpdateAsync(meditationFile);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>($"Unable to update Meditation File", errorList);
                }

                var item = objectMapperService.MeditationFileUpdateModelToMeditationFile(meditationFile);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateMeditationFileAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Meditation File");
                    }

                    //await CreateOrUpdateMeditationFileDependentsAsync(meditationFile)

                    await trx.CompleteAsync();
                }

                await auditService.MeditationFileUpdatedAsync(meditationFile.MeditationFileId);

                var view = await manifestRepository.GetMeditationFileViewByIdAsync(meditationFile.MeditationFileId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>($"Unable to find the Meditation File", new { meditationFile.MeditationFileId });
                }

                return this.ConvertToItem(view, objectMapperService.MeditationFileViewToMeditationFileModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<MeditationFileModel>($"Unexpected error when updating Meditation File", new { meditationFile?.MeditationFileId }, ex);
            }
        }

