        public async Task<List<ReturnErrorItem>> IsMeditationFileModelValidForAllAsync(bool isCreate, MeditationFileUpdateModel meditationFileModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (await manifestRepository.IsMeditationFileNameAlreadyExistsForOtherMeditationFileAsync(meditationFileModel.MeditationFileName, meditationFileModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Meditation File already exists"));
                }

                if (meditationFileModel.MeditationFileId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Meditation File Identifier is not valid"));
                }
            }
            else
            {
                if (await manifestRepository.IsMeditationFileNameAlreadyExistsForOtherMeditationFileAsync(meditationFileModel.MeditationFileId, meditationFileModel.MeditationFileName, meditationFileModel.UserId))
                {
                    result.Add(new ReturnErrorItem("", "Another Meditation File already exists"));
                }

                if (meditationFileModel.MeditationFileId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Meditation File Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(meditationFileModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != meditationFileModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (meditationFileModel.PredefinedMeditationTypeId == 0)
            {
                result.Add(new ReturnErrorItem("PredefinedMeditationTypeId", "PredefinedMeditationTypeId cannot be empty"));
            }
            if (meditationFileModel.MeditationFileName != null && meditationFileModel.MeditationFileName.Length > MeditationFileModel.COLUMN_SIZE_MeditationFileName)
            {
                result.Add(new ReturnErrorItem("MeditationFileName", $"MeditationFileName size should not exceed {MeditationFileModel.COLUMN_SIZE_MeditationFileName}"));
            }
            if (meditationFileModel.MeditationFileName == null)
            {
                result.Add(new ReturnErrorItem("MeditationFileName", "MeditationFileName is required "));
            }
            if (meditationFileModel.Location != null && meditationFileModel.Location.Length > MeditationFileModel.COLUMN_SIZE_Location)
            {
                result.Add(new ReturnErrorItem("Location", $"Location size should not exceed {MeditationFileModel.COLUMN_SIZE_Location}"));
            }
            if (meditationFileModel.FileName != null && meditationFileModel.FileName.Length > MeditationFileModel.COLUMN_SIZE_FileName)
            {
                result.Add(new ReturnErrorItem("FileName", $"FileName size should not exceed {MeditationFileModel.COLUMN_SIZE_FileName}"));
            }
            if (meditationFileModel.FileName == null)
            {
                result.Add(new ReturnErrorItem("FileName", "FileName is required "));
            }
            if (!ValidationUtils.IsLongValid(meditationFileModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(meditationFileModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != meditationFileModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }


            return result.Count > 0 ? result : null;
        }



