        public async Task<ReturnModel<bool>> UploadMeditationFileFileAsync(long meditationFileId, FileStreamModel streamModel)
        {
            try
            {
                var meditationFile = await GetMeditationFileByIdForWriteAsync(meditationFileId);
                if (!meditationFile.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(meditationFile);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(meditationFile.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(meditationFile.Model.UserId, meditationFile.Model.MeditationFileId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(meditationFile.Model.UserId, meditationFile.Model.MeditationFileId, streamModel.FileName);
                        await productRepository.UpdateMeditationFileFilePathAsync(meditationFile.Model.MeditationFileId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(meditationFile.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Meditation File File", ex);
            }
        }

