            }
        }

        public async Task CreateOrUpdateMeditationFileDependentsAsync(MeditationFileUpdateModel model)
        {
            if (model.NewMeditationFileXYZZYXModels == null)
                model.NewMeditationFileXYZZYXModels = new List<MeditationFileXYZZYXCreateModel>();

            if (model.ExistingMeditationFileXYZZYXModels == null)
                model.ExistingMeditationFileXYZZYXModels = new List<MeditationFileXYZZYXUpdateModel>();

            var dbExistingMeditationFiles = await manifestRepository.GetMeditationFileXYZZYXsByMeditationFileIdAsync(model.MeditationFileId);
            if (!dbExistingMeditationFiles.IsNullOrEmpty())
            {
                var dbExistingMeditationFileIds = dbExistingMeditationFiles.SelectToList(x => x.MeditationFileXYZZYXId);
                var modelExistingMeditationFileIds = model.ExistingMeditationFileXYZZYXModels.SelectToList(x => x.MeditationFileXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingMeditationFiles.Where(x => !modelExistingMeditationFileIds.Contains(x.MeditationFileXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkMeditationFileXYZZYXAsDeletedByIdAsync(x.MeditationFileXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingMeditationFileXYZZYXModels.Where(x => dbExistingMeditationFileIds.Contains(x.MeditationFileXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.MeditationFileId = model.MeditationFileId;
                    var result = await UpdateMeditationFileXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewMeditationFileXYZZYXModels)
            {
                x.MeditationFileId = model.MeditationFileId;
                var result = await CreateMeditationFileXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableMeditationFileByIdAsync(long meditationFileId)
        {
            try
            {
                var existingMeditationFileModel = await GetMeditationFileByIdForWriteAsync(meditationFileId);
                if (!existingMeditationFileModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MeditationFileModel>(existingMeditationFileModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(existingMeditationFileModel.Model.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.EnableMeditationFileByIdAsync(existingMeditationFileModel.Model.MeditationFileId, await currentSessionService.GetCurrentUserIdAsync());
                    await trx.CompleteAsync();
                }

                await auditService.MeditationFileEnabledAsync(meditationFileId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Meditation File", new { meditationFileId }, ex);
            }
        }

