        public async Task<ReturnModel<bool>> AssociateXYZZYXWithMeditationFileAsync(MeditationFileXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMeditationFileWithMeditationFileAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Meditation File association is invalid", errorLst);
                }

                if (await manifestRepository.DoesMeditationFileWithXYZZYXAssociationExistsAsync(model.MeditationFileId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Meditation File is already associated with the Meditation File", new { model.MeditationFileId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateMeditationFileWithXYZZYXAsync(model.MeditationFileId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Meditation File with XYZZYX", new { model.MeditationFileId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Meditation File with XYZZYX", new { model.MeditationFileId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithMeditationFileAsync(MeditationFileXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMeditationFileWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Meditation File association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesMeditationFileWithXYZZYXAssociationExistsAsync(model.MeditationFileId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Meditation File is not associated with the Meditation File", new { model.MeditationFileId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateMeditationFileWithMeditationFileAsync(model.MeditationFileId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Meditation File with the Meditation File", new { model.MeditationFileId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Meditation File with the Meditation File", new { model.MeditationFileId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsMeditationFileWithXYZZYXAssociationValidAsync(MeditationFileXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.MeditationFileId == 0)
            {
                result.Add(new ReturnErrorItem("", "Meditation File is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Meditation File  is not valid"));
                return result;
            }

            var entity = await GetMeditationFileForWriteByIdAsync(model.MeditationFileId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Meditation File information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Meditation Files does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

