        public async Task<ReturnListModel<MeditationSessionModel>> CreateMultipleMeditationSessionAsync(MultipleMeditationSessionCreateModel meditationSessions)
        {
            try
            {
                if (meditationSessions == null)
                {
                    return log.ErrorAndReturnListModel<MeditationSessionModel>($"Unable to Create Meditation Sessions", new ReturnErrorItem("", "Meditation Sessions information is not valid"));
                }

                if (meditationSessions.NewMeditationSessions.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<MeditationSessionModel>($"Unable to Create Meditation Sessions", new ReturnErrorItem("", "Meditation Sessions information is not provided"));
                }

                var lst = new List<MeditationSessionModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var meditationSession in meditationSessions.NewMeditationSessions)
                    {
                        var cResult = await CreateMeditationSessionAsync(meditationSession);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<MeditationSessionModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<MeditationSessionModel>($"Unexpected error when creating Meditation Sessions", new { meditationSessions }, ex);
            }
        }

