        public async Task<ReturnModel<MeditationSessionModel>> UpdateMeditationSessionAsync(MeditationSessionUpdateModel meditationSession)
        {
            try
            {
                if (meditationSession == null)
                {
                    return log.ErrorAndReturnModel<MeditationSessionModel>($"Unable to update Meditation Session", new ReturnErrorItem("", "Meditation Session information is not valid"));
                }

                var existingMeditationSessionModel = await GetMeditationSessionByIdForWriteAsync(meditationSession.MeditationSessionId);
                if (!existingMeditationSessionModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<MeditationSessionModel>(existingMeditationSessionModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(meditationSession.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<MeditationSessionModel>(errorStr);
                }

                if (canAssign)
                {
                    meditationSession.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                meditationSession.CreatedByUserId = existingMeditationSessionModel.Model.CreatedByUserId;
                meditationSession.CreatedDate = existingMeditationSessionModel.Model.CreatedDate;
                meditationSession.IsDeleted = existingMeditationSessionModel.Model.IsDeleted;
                meditationSession.UserId = existingMeditationSessionModel.Model.UserId;
                //meditationSession.MovieId = existingMeditationSessionModel.Model.MovieId;
                //meditationSession.ProfileImageActualFileName = existingMeditationSessionModel.Model.ProfileImageActualFileName;
                //meditationSession.ProfileImageLocation = existingMeditationSessionModel.Model.ProfileImageLocation;



                var errorList = await IsMeditationSessionModelValidForUpdateAsync(meditationSession);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<MeditationSessionModel>($"Unable to update Meditation Session", errorList);
                }

                var item = objectMapperService.MeditationSessionUpdateModelToMeditationSession(meditationSession);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateMeditationSessionAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Meditation Session");
                    }

                    //await CreateOrUpdateMeditationSessionDependentsAsync(meditationSession)

                    await trx.CompleteAsync();
                }

                await auditService.MeditationSessionUpdatedAsync(meditationSession.MeditationSessionId);

                var view = await manifestRepository.GetMeditationSessionViewByIdAsync(meditationSession.MeditationSessionId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<MeditationSessionModel>($"Unable to find the Meditation Session", new { meditationSession.MeditationSessionId });
                }

                return this.ConvertToItem(view, objectMapperService.MeditationSessionViewToMeditationSessionModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<MeditationSessionModel>($"Unexpected error when updating Meditation Session", new { meditationSession?.MeditationSessionId }, ex);
            }
        }

