        public Task<List<ReturnErrorItem>> IsMeditationSessionModelValidForCreateAsync(MeditationSessionUpdateModel meditationSessionModel)
        {
            return IsMeditationSessionModelValidForAllAsync(true, meditationSessionModel);
        }

        public Task<List<ReturnErrorItem>> IsMeditationSessionModelValidForUpdateAsync(MeditationSessionUpdateModel meditationSessionModel)
        {
            return IsMeditationSessionModelValidForAllAsync(false, meditationSessionModel);
        }

        public async Task<List<ReturnErrorItem>> IsMeditationSessionModelValidForAllAsync(bool isCreate, MeditationSessionUpdateModel meditationSessionModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (meditationSessionModel.MeditationSessionId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Meditation Session Identifier is not valid"));
                }
            }
            else
            {
                if (meditationSessionModel.MeditationSessionId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Meditation Session Unique Identifier is not valid"));
                }
            }

            var meditationFileItem = await manifestRepository.GetMeditationFileViewByIdAsync(meditationSessionModel.MeditationFileId);
            if (meditationFileItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the MeditationFile Information"));
                return result;
            }

            if (meditationFileItem.UserId != meditationSessionModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this MeditationFile Information"));
                return result;
            }


            var userItem = await companyRepository.GetUserViewByIdAsync(meditationSessionModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != meditationSessionModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!DateUtils.IsValidDate(meditationSessionModel.MeditationSessionDate))
            {
                result.Add(new ReturnErrorItem("MeditationSessionDate", $"MeditationSessionDate is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(meditationSessionModel.MeditationFileId))
            {
                result.Add(new ReturnErrorItem("MeditationFileId", "MeditationFile cannot be empty"));
            }
            else
            {
                var itemForMeditationFile = await manifestRepository.GetMeditationFileByIdAsync(meditationSessionModel.MeditationFileId);
                if (itemForMeditationFile == null)
                {
                    result.Add(new ReturnErrorItem("MeditationFileId", "MeditationFile is not available"));
                }
                else
                {
                    if (itemForMeditationFile.UserId != meditationSessionModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("MeditationFileId", "MeditationFile does not belong to you."));
                    }
                }
            }
            if (!ValidationUtils.IsLongValid(meditationSessionModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(meditationSessionModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != meditationSessionModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }
            if (meditationSessionModel.AddedToFeedDate != null && !DateUtils.IsValidDate(meditationSessionModel.AddedToFeedDate.Value))
            {
                result.Add(new ReturnErrorItem("AddedToFeedDate", $"AddedToFeedDate is not a valid date"));
            }


            return result.Count > 0 ? result : null;
        }



