        public async Task<ReturnModel<bool>> UploadMeditationSessionFileAsync(long meditationSessionId, FileStreamModel streamModel)
        {
            try
            {
                var meditationSession = await GetMeditationSessionByIdForWriteAsync(meditationSessionId);
                if (!meditationSession.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(meditationSession);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(meditationSession.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(meditationSession.Model.UserId, meditationSession.Model.MeditationSessionId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(meditationSession.Model.UserId, meditationSession.Model.MeditationSessionId, streamModel.FileName);
                        await productRepository.UpdateMeditationSessionFilePathAsync(meditationSession.Model.MeditationSessionId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(meditationSession.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Meditation Session File", ex);
            }
        }

