            }
        }

        public async Task CreateOrUpdateMeditationSessionDependentsAsync(MeditationSessionUpdateModel model)
        {
            if (model.NewMeditationSessionXYZZYXModels == null)
                model.NewMeditationSessionXYZZYXModels = new List<MeditationSessionXYZZYXCreateModel>();

            if (model.ExistingMeditationSessionXYZZYXModels == null)
                model.ExistingMeditationSessionXYZZYXModels = new List<MeditationSessionXYZZYXUpdateModel>();

            var dbExistingMeditationSessions = await manifestRepository.GetMeditationSessionXYZZYXsByMeditationSessionIdAsync(model.MeditationSessionId);
            if (!dbExistingMeditationSessions.IsNullOrEmpty())
            {
                var dbExistingMeditationSessionIds = dbExistingMeditationSessions.SelectToList(x => x.MeditationSessionXYZZYXId);
                var modelExistingMeditationSessionIds = model.ExistingMeditationSessionXYZZYXModels.SelectToList(x => x.MeditationSessionXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingMeditationSessions.Where(x => !modelExistingMeditationSessionIds.Contains(x.MeditationSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkMeditationSessionXYZZYXAsDeletedByIdAsync(x.MeditationSessionXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingMeditationSessionXYZZYXModels.Where(x => dbExistingMeditationSessionIds.Contains(x.MeditationSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.MeditationSessionId = model.MeditationSessionId;
                    var result = await UpdateMeditationSessionXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewMeditationSessionXYZZYXModels)
            {
                x.MeditationSessionId = model.MeditationSessionId;
                var result = await CreateMeditationSessionXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

        public async Task<ReturnModel<bool>> EnableMeditationSessionByIdAsync(long meditationSessionId)
