                await auditService.MeditationSessionEnabledAsync(meditationSessionId);

                return new ReturnModel<bool>(result);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when enabling Meditation Session", new { meditationSessionId }, ex);
            }
        }

