        public async Task<ReturnModel<bool>> AssociateXYZZYXWithMeditationSessionAsync(MeditationSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMeditationSessionWithMeditationSessionAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Meditation Session association is invalid", errorLst);
                }

                if (await manifestRepository.DoesMeditationSessionWithXYZZYXAssociationExistsAsync(model.MeditationSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Meditation Session is already associated with the Meditation Session", new { model.MeditationSessionId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateMeditationSessionWithXYZZYXAsync(model.MeditationSessionId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Meditation Session with XYZZYX", new { model.MeditationSessionId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Meditation Session with XYZZYX", new { model.MeditationSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithMeditationSessionAsync(MeditationSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsMeditationSessionWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Meditation Session association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesMeditationSessionWithXYZZYXAssociationExistsAsync(model.MeditationSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Meditation Session is not associated with the Meditation Session", new { model.MeditationSessionId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateMeditationSessionWithMeditationSessionAsync(model.MeditationSessionId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Meditation Session with the Meditation Session", new { model.MeditationSessionId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Meditation Session with the Meditation Session", new { model.MeditationSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsMeditationSessionWithXYZZYXAssociationValidAsync(MeditationSessionXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.MeditationSessionId == 0)
            {
                result.Add(new ReturnErrorItem("", "Meditation Session is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Meditation Session  is not valid"));
                return result;
            }

            var entity = await GetMeditationSessionForWriteByIdAsync(model.MeditationSessionId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Meditation Session information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Meditation Sessions does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

