        public async Task<ReturnModel<VisionBoardPictureModel>> UpdateVisionBoardPictureAsync(VisionBoardPictureUpdateModel visionBoardPicture, FileStreamModel fsModel)
        {
            try
            {
                if (visionBoardPicture == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardPictureModel>($"Unable to update Vision Board Picture", new ReturnErrorItem("", "Vision Board Picture information is not valid"));
                }

                var existingVisionBoardPictureModel = await GetVisionBoardPictureByIdForWriteAsync(visionBoardPicture.VisionBoardPictureId);
                if (!existingVisionBoardPictureModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<VisionBoardPictureModel>(existingVisionBoardPictureModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(visionBoardPicture.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<VisionBoardPictureModel>(errorStr);
                }

                Stream fileStream = null;

                if (fsModel != null)
                {

                    if (fsModel != null && fsModel.FileData != null && fsModel.FileData.Length > 0)
                    {
                        if (fsModel.FileName.IsTrimmedStringNullOrEmpty())
                        {
                            return ReturnModel<VisionBoardPictureModel>.Error($"Uploaded file name is not available. Please provide a valid file document.");
                        }

                        fileStream = fsModel.FileData;
                    }

                    if (fileStream == null)
                    {
                        return ReturnModel<VisionBoardPictureModel>.Error($"Template File should not be empty. Please upload valid Template file.");
                    }
                }

                if (canAssign)
                {
                    visionBoardPicture.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                visionBoardPicture.CreatedByUserId = existingVisionBoardPictureModel.Model.CreatedByUserId;
                visionBoardPicture.CreatedDate = existingVisionBoardPictureModel.Model.CreatedDate;
                visionBoardPicture.IsDeleted = existingVisionBoardPictureModel.Model.IsDeleted;
                visionBoardPicture.UserId = existingVisionBoardPictureModel.Model.UserId;
                visionBoardPicture.FileName = existingVisionBoardPictureModel.Model.FileName;
                visionBoardPicture.FileSize = (fsModel == null || fsModel.FileData == null) ? existingVisionBoardPictureModel.Model.FileSize : fsModel.FileData.Length;
                visionBoardPicture.Location = existingVisionBoardPictureModel.Model.Location;


                var errorList = await IsVisionBoardPictureModelValidForUpdateAsync(visionBoardPicture);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<VisionBoardPictureModel>($"Unable to update Vision Board Picture", errorList);
                }

                var item = objectMapperService.VisionBoardPictureUpdateModelToVisionBoardPicture(visionBoardPicture);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateVisionBoardPictureAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Vision Board Picture");
                    }

                    //await CreateOrUpdateVisionBoardPictureDependentsAsync(visionBoardPicture)

                    if (fileStream != null)
                    {
                        fileStream.Position = 0;
                        await fileAttachmentFileStorage.WriteAsync(item.UserId, item.Location, fileStream);
                    }

                    await trx.CompleteAsync();
                }

                await auditService.VisionBoardPictureUpdatedAsync(visionBoardPicture.VisionBoardPictureId);

                var view = await manifestRepository.GetVisionBoardPictureViewByIdAsync(visionBoardPicture.VisionBoardPictureId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardPictureModel>($"Unable to find the Vision Board Picture", new { visionBoardPicture.VisionBoardPictureId });
                }

                return this.ConvertToItem(view, objectMapperService.VisionBoardPictureViewToVisionBoardPictureModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<VisionBoardPictureModel>($"Unexpected error when updating Vision Board Picture", new { visionBoardPicture?.VisionBoardPictureId }, ex);
            }
        }

