        public Task<List<ReturnErrorItem>> IsVisionBoardPictureModelValidForCreateAsync(VisionBoardPictureUpdateModel visionBoardPictureModel)
        {
            return IsVisionBoardPictureModelValidForAllAsync(true, visionBoardPictureModel);
        }

        public Task<List<ReturnErrorItem>> IsVisionBoardPictureModelValidForUpdateAsync(VisionBoardPictureUpdateModel visionBoardPictureModel)
        {
            return IsVisionBoardPictureModelValidForAllAsync(false, visionBoardPictureModel);
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardPictureModelValidForAllAsync(bool isCreate, VisionBoardPictureUpdateModel visionBoardPictureModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (visionBoardPictureModel.VisionBoardPictureId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Picture Identifier is not valid"));
                }
            }
            else
            {
                if (visionBoardPictureModel.VisionBoardPictureId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Picture Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(visionBoardPictureModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != visionBoardPictureModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }

            if (visionBoardPictureModel.Location != null && visionBoardPictureModel.Location.Length > VisionBoardPictureModel.COLUMN_SIZE_Location)
            {
                result.Add(new ReturnErrorItem("Location", $"Location size should not exceed {VisionBoardPictureModel.COLUMN_SIZE_Location}"));
            }
            if (visionBoardPictureModel.FileName != null && visionBoardPictureModel.FileName.Length > VisionBoardPictureModel.COLUMN_SIZE_FileName)
            {
                result.Add(new ReturnErrorItem("FileName", $"FileName size should not exceed {VisionBoardPictureModel.COLUMN_SIZE_FileName}"));
            }
            if (visionBoardPictureModel.FileName == null)
            {
                result.Add(new ReturnErrorItem("FileName", "FileName is required "));
            }
            if (!ValidationUtils.IsLongValid(visionBoardPictureModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(visionBoardPictureModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != visionBoardPictureModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }

            return result.Count > 0 ? result : null;
        }

