        public async Task CreateOrUpdateVisionBoardPictureDependentsAsync(VisionBoardPictureUpdateModel model)
        {
            if (model.NewVisionBoardPictureXYZZYXModels == null)
                model.NewVisionBoardPictureXYZZYXModels = new List<VisionBoardPictureXYZZYXCreateModel>();

            if (model.ExistingVisionBoardPictureXYZZYXModels == null)
                model.ExistingVisionBoardPictureXYZZYXModels = new List<VisionBoardPictureXYZZYXUpdateModel>();

            var dbExistingVisionBoardPictures = await manifestRepository.GetVisionBoardPictureXYZZYXsByVisionBoardPictureIdAsync(model.VisionBoardPictureId);
            if (!dbExistingVisionBoardPictures.IsNullOrEmpty())
            {
                var dbExistingVisionBoardPictureIds = dbExistingVisionBoardPictures.SelectToList(x => x.VisionBoardPictureXYZZYXId);
                var modelExistingVisionBoardPictureIds = model.ExistingVisionBoardPictureXYZZYXModels.SelectToList(x => x.VisionBoardPictureXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingVisionBoardPictures.Where(x => !modelExistingVisionBoardPictureIds.Contains(x.VisionBoardPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkVisionBoardPictureXYZZYXAsDeletedByIdAsync(x.VisionBoardPictureXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingVisionBoardPictureXYZZYXModels.Where(x => dbExistingVisionBoardPictureIds.Contains(x.VisionBoardPictureXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.VisionBoardPictureId = model.VisionBoardPictureId;
                    var result = await UpdateVisionBoardPictureXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewVisionBoardPictureXYZZYXModels)
            {
                x.VisionBoardPictureId = model.VisionBoardPictureId;
                var result = await CreateVisionBoardPictureXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

