        public async Task<ReturnModel<bool>> AssociateXYZZYXWithVisionBoardPictureAsync(VisionBoardPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardPictureWithVisionBoardPictureAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Picture association is invalid", errorLst);
                }

                if (await manifestRepository.DoesVisionBoardPictureWithXYZZYXAssociationExistsAsync(model.VisionBoardPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Picture is already associated with the Vision Board Picture", new { model.VisionBoardPictureId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateVisionBoardPictureWithXYZZYXAsync(model.VisionBoardPictureId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Vision Board Picture with XYZZYX", new { model.VisionBoardPictureId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Vision Board Picture with XYZZYX", new { model.VisionBoardPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithVisionBoardPictureAsync(VisionBoardPictureXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardPictureWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Picture association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesVisionBoardPictureWithXYZZYXAssociationExistsAsync(model.VisionBoardPictureId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Picture is not associated with the Vision Board Picture", new { model.VisionBoardPictureId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateVisionBoardPictureWithVisionBoardPictureAsync(model.VisionBoardPictureId, model.XYZZYXId);
