                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Vision Board Picture with the Vision Board Picture", new { model.VisionBoardPictureId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Vision Board Picture with the Vision Board Picture", new { model.VisionBoardPictureId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardPictureWithXYZZYXAssociationValidAsync(VisionBoardPictureXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.VisionBoardPictureId == 0)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Picture is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Vision Board Picture  is not valid"));
                return result;
            }

            var entity = await GetVisionBoardPictureForWriteByIdAsync(model.VisionBoardPictureId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Picture information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Pictures does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

