        public async Task<ReturnListModel<VisionBoardSessionModel>> CreateMultipleVisionBoardSessionAsync(MultipleVisionBoardSessionCreateModel visionBoardSessions)
        {
            try
            {
                if (visionBoardSessions == null)
                {
                    return log.ErrorAndReturnListModel<VisionBoardSessionModel>($"Unable to Create Vision Board Sessions", new ReturnErrorItem("", "Vision Board Sessions information is not valid"));
                }

                if (visionBoardSessions.NewVisionBoardSessions.IsNullOrEmpty())
                {
                    return log.ErrorAndReturnListModel<VisionBoardSessionModel>($"Unable to Create Vision Board Sessions", new ReturnErrorItem("", "Vision Board Sessions information is not provided"));
                }

                var lst = new List<VisionBoardSessionModel>();

                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    foreach (var visionBoardSession in visionBoardSessions.NewVisionBoardSessions)
                    {
                        var cResult = await CreateVisionBoardSessionAsync(visionBoardSession);
                        if (!cResult.IsSuccess)
                            throw new RollbackException(cResult);

                        lst.Add(cResult.Model);
                    }

                    await trx.CompleteAsync();
                }

                return ReturnListModel<VisionBoardSessionModel>.Success(lst);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnListModelWithRollbackExceptionHandler<VisionBoardSessionModel>($"Unexpected error when creating Vision Board Sessions", new { visionBoardSessions }, ex);
            }
