        public async Task<ReturnModel<VisionBoardSessionModel>> UpdateVisionBoardSessionAsync(VisionBoardSessionUpdateModel visionBoardSession)
        {
            try
            {
                if (visionBoardSession == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionModel>($"Unable to update Vision Board Session", new ReturnErrorItem("", "Vision Board Session information is not valid"));
                }

                var existingVisionBoardSessionModel = await GetVisionBoardSessionByIdForWriteAsync(visionBoardSession.VisionBoardSessionId);
                if (!existingVisionBoardSessionModel.IsSuccess)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionModel>(existingVisionBoardSessionModel);
                }

                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(visionBoardSession.UserId);

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionModel>(errorStr);
                }

                if (canAssign)
                {
                    visionBoardSession.UserId = await currentSessionService.GetCurrentUserIdAsync() ?? 0;
                }

                visionBoardSession.CreatedByUserId = existingVisionBoardSessionModel.Model.CreatedByUserId;
                visionBoardSession.CreatedDate = existingVisionBoardSessionModel.Model.CreatedDate;
                visionBoardSession.IsDeleted = existingVisionBoardSessionModel.Model.IsDeleted;
                visionBoardSession.UserId = existingVisionBoardSessionModel.Model.UserId;
                //visionBoardSession.MovieId = existingVisionBoardSessionModel.Model.MovieId;
                //visionBoardSession.ProfileImageActualFileName = existingVisionBoardSessionModel.Model.ProfileImageActualFileName;
                //visionBoardSession.ProfileImageLocation = existingVisionBoardSessionModel.Model.ProfileImageLocation;



                var errorList = await IsVisionBoardSessionModelValidForUpdateAsync(visionBoardSession);
                if (errorList != null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionModel>($"Unable to update Vision Board Session", errorList);
                }

                var item = objectMapperService.VisionBoardSessionUpdateModelToVisionBoardSession(visionBoardSession);

                bool result;
                using (var trx = await transactionManager.BeginTransactionAsync())
                {
                    result = await manifestRepository.UpdateVisionBoardSessionAsync(item, await currentSessionService.GetCurrentUserIdAsync());
                    if (result == false)
                    {
                        throw new RollbackException($"Unable to update Vision Board Session");
                    }

                    //await CreateOrUpdateVisionBoardSessionDependentsAsync(visionBoardSession)

                    await trx.CompleteAsync();
                }

                await auditService.VisionBoardSessionUpdatedAsync(visionBoardSession.VisionBoardSessionId);

                var view = await manifestRepository.GetVisionBoardSessionViewByIdAsync(visionBoardSession.VisionBoardSessionId);

                if (view == null)
                {
                    return log.ErrorAndReturnModel<VisionBoardSessionModel>($"Unable to find the Vision Board Session", new { visionBoardSession.VisionBoardSessionId });
                }

                return this.ConvertToItem(view, objectMapperService.VisionBoardSessionViewToVisionBoardSessionModel);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<VisionBoardSessionModel>($"Unexpected error when updating Vision Board Session", new { visionBoardSession?.VisionBoardSessionId }, ex);
            }
        }

