        {
            return IsVisionBoardSessionModelValidForAllAsync(true, visionBoardSessionModel);
        }

        public Task<List<ReturnErrorItem>> IsVisionBoardSessionModelValidForUpdateAsync(VisionBoardSessionUpdateModel visionBoardSessionModel)
        {
            return IsVisionBoardSessionModelValidForAllAsync(false, visionBoardSessionModel);
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardSessionModelValidForAllAsync(bool isCreate, VisionBoardSessionUpdateModel visionBoardSessionModel)
        {
            var result = new List<ReturnErrorItem>();

            if (isCreate)
            {
                if (visionBoardSessionModel.VisionBoardSessionId > 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Session Identifier is not valid"));
                }
            }
            else
            {
                if (visionBoardSessionModel.VisionBoardSessionId <= 0)
                {
                    result.Add(new ReturnErrorItem("", "Vision Board Session Unique Identifier is not valid"));
                }
            }

            var userItem = await companyRepository.GetUserViewByIdAsync(visionBoardSessionModel.UserId);
            if (userItem == null)
            {
                result.Add(new ReturnErrorItem("", $"Unable to Get the User Information"));
                return result;
            }

            if (userItem.UserId != visionBoardSessionModel.UserId)
            {
                result.Add(new ReturnErrorItem("", $"You dont have access to this User Information"));
                return result;
            }




            if (!DateUtils.IsValidDate(visionBoardSessionModel.VisionBoardSessionDate))
            {
                result.Add(new ReturnErrorItem("VisionBoardSessionDate", $"VisionBoardSessionDate is not a valid date"));
            }
            if (!ValidationUtils.IsLongValid(visionBoardSessionModel.UserId))
            {
                result.Add(new ReturnErrorItem("UserId", "User cannot be empty"));
            }
            else
            {
                var itemForUser = await companyRepository.GetUserByIdAsync(visionBoardSessionModel.UserId);
                if (itemForUser == null)
                {
                    result.Add(new ReturnErrorItem("UserId", "User is not available"));
                }
                else
                {
                    if (itemForUser.UserId != visionBoardSessionModel.UserId)
                    {
                        result.Add(new ReturnErrorItem("UserId", "User does not belong to you."));
                    }
                }
            }
            if (visionBoardSessionModel.AddedToFeedDate != null && !DateUtils.IsValidDate(visionBoardSessionModel.AddedToFeedDate.Value))
            {
                result.Add(new ReturnErrorItem("AddedToFeedDate", $"AddedToFeedDate is not a valid date"));
            }


            return result.Count > 0 ? result : null;
        }



