        public async Task<ReturnModel<bool>> UploadVisionBoardSessionFileAsync(long visionBoardSessionId, FileStreamModel streamModel)
        {
            try
            {
                var visionBoardSession = await GetVisionBoardSessionByIdForWriteAsync(visionBoardSessionId);
                if (!visionBoardSession.IsSuccess)
                {
                    return log.ErrorAndReturnModel<bool>(visionBoardSession);
                }

                if (streamModel == null)
                {
                    return log.ErrorAndReturnModel<bool>("File Content is not provided");
                }

                var company = await companyRepository.GetCompanyByIdAsync(visionBoardSession.Model.UserId);
                if (company == null)
                {
                    return log.ErrorAndReturnModel<bool>("Unable to find the Company Information");
                }

                try
                {
                    using (var trx = await transactionManager.BeginTransactionAsync())
                    {
                        var path = profileFileFileStorage.ProfileFilePathForHostBrand(visionBoardSession.Model.UserId, visionBoardSession.Model.VisionBoardSessionId, streamModel.FileName);
                        if (company.PredefinedCompanyTypeId == (int)PredefinedCompanyTypes.MarketPlace)
                            path = profileFileFileStorage.ProfileFilePathForMarketplaceBrand(visionBoardSession.Model.UserId, visionBoardSession.Model.VisionBoardSessionId, streamModel.FileName);
                        await productRepository.UpdateVisionBoardSessionFilePathAsync(visionBoardSession.Model.VisionBoardSessionId, path, streamModel.FileName, await currentSessionService.GetCurrentUserIdAsync());
                        await profileFileFileStorage.WriteAsync(visionBoardSession.Model.UserId, path, streamModel.FileData);
                        await trx.CompleteAsync();
                    }
                }
                finally
                {
                    FileUtils.CloseSafely(streamModel.FileData);
                }

                return ReturnModel<bool>.Success(true);
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when Uploading Vision Board Session File", ex);
            }
        }

