        public async Task CreateOrUpdateVisionBoardSessionDependentsAsync(VisionBoardSessionUpdateModel model)
        {
            if (model.NewVisionBoardSessionXYZZYXModels == null)
                model.NewVisionBoardSessionXYZZYXModels = new List<VisionBoardSessionXYZZYXCreateModel>();

            if (model.ExistingVisionBoardSessionXYZZYXModels == null)
                model.ExistingVisionBoardSessionXYZZYXModels = new List<VisionBoardSessionXYZZYXUpdateModel>();

            var dbExistingVisionBoardSessions = await manifestRepository.GetVisionBoardSessionXYZZYXsByVisionBoardSessionIdAsync(model.VisionBoardSessionId);
            if (!dbExistingVisionBoardSessions.IsNullOrEmpty())
            {
                var dbExistingVisionBoardSessionIds = dbExistingVisionBoardSessions.SelectToList(x => x.VisionBoardSessionXYZZYXId);
                var modelExistingVisionBoardSessionIds = model.ExistingVisionBoardSessionXYZZYXModels.SelectToList(x => x.VisionBoardSessionXYZZYXId);

                var xYZZYXItemsToDelete = dbExistingVisionBoardSessions.Where(x => !modelExistingVisionBoardSessionIds.Contains(x.VisionBoardSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToDelete)
                {
                    var result = await MarkVisionBoardSessionXYZZYXAsDeletedByIdAsync(x.VisionBoardSessionXYZZYXId);
                    if (!result.IsSuccess)
                    {
                        throw new RollbackException(result);
                    }
                }

                var xYZZYXItemsToUpdate = model.ExistingVisionBoardSessionXYZZYXModels.Where(x => dbExistingVisionBoardSessionIds.Contains(x.VisionBoardSessionXYZZYXId));
                foreach (var x in xYZZYXItemsToUpdate)
                {
                    x.VisionBoardSessionId = model.VisionBoardSessionId;
                    var result = await UpdateVisionBoardSessionXYZZYXAsync(x);
                    if (!result.IsSuccess)
                    {   
                        throw new RollbackException(result);
                    }
                }
            }

            foreach (var x in model.NewVisionBoardSessionXYZZYXModels)
            {
                x.VisionBoardSessionId = model.VisionBoardSessionId;
                var result = await CreateVisionBoardSessionXYZZYXAsync(x);
                if (!result.IsSuccess)
                {
                    throw new RollbackException(result);
                }
            }
        }

