        public async Task<ReturnModel<bool>> AssociateXYZZYXWithVisionBoardSessionAsync(VisionBoardSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardSessionWithVisionBoardSessionAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Session association is invalid", errorLst);
                }

                if (await manifestRepository.DoesVisionBoardSessionWithXYZZYXAssociationExistsAsync(model.VisionBoardSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Session is already associated with the Vision Board Session", new { model.VisionBoardSessionId, model.XYZZYXId});
                }

                var rValue = await manifestRepository.AssociateVisionBoardSessionWithXYZZYXAsync(model.VisionBoardSessionId, model.XYZZYXId, await currentSessionService.GetCurrentUserIdAsync());
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }
                return log.ErrorAndReturnModel<bool>("Unable to associate Vision Board Session with XYZZYX", new { model.VisionBoardSessionId, model.XYZZYXId});
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when associating Vision Board Session with XYZZYX", new { model.VisionBoardSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<ReturnModel<bool>> UnAssociateXYZZYXWithVisionBoardSessionAsync(VisionBoardSessionXYZZYXAssociationModel model)
        {
            try
            {
                var (resultValue, canAssign, errorStr) = await permissionService.CanModifyResource(await currentSessionService.GetCurrentCompanyIdAsync());

                if (resultValue == false)
                {
                    return log.ErrorAndReturnModel<bool>(errorStr);
                }

                var errorLst = await IsVisionBoardSessionWithXYZZYXAssociationValidAsync(model);
                if (errorLst != null)
                {
                    return ReturnModel<bool>.Error("Vision Board Session association is not valid", errorLst);
                }

                if (!await manifestRepository.DoesVisionBoardSessionWithXYZZYXAssociationExistsAsync(model.VisionBoardSessionId, model.XYZZYXId))
                {
                    return log.ErrorAndReturnModel<bool>("Related Vision Board Session is not associated with the Vision Board Session", new { model.VisionBoardSessionId, model.XYZZYXId });
                }

                var rValue = await manifestRepository.UnAssociateVisionBoardSessionWithVisionBoardSessionAsync(model.VisionBoardSessionId, model.XYZZYXId);
                if (rValue)
                {
                    return ReturnModel<bool>.Success(rValue);
                }

                return log.ErrorAndReturnModel<bool>("Unable to unassociate Related Vision Board Session with the Vision Board Session", new { model.VisionBoardSessionId, model.XYZZYXId });
            }
            catch (Exception ex)
            {
                return log.ErrorAndReturnModel<bool>($"Unexpected error when unassociating Related Vision Board Session with the Vision Board Session", new { model.VisionBoardSessionId, model.XYZZYXId }, ex);
            }
        }

        public async Task<List<ReturnErrorItem>> IsVisionBoardSessionWithXYZZYXAssociationValidAsync(VisionBoardSessionXYZZYXAssociationModel model)
        {
            var result = new List<ReturnErrorItem>();
            if (model == null)
            {
                result.Add(new ReturnErrorItem("", "Association is not valid"));
                return result;
            }

            if (model.VisionBoardSessionId == 0)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Session is not valid"));
                return result;
            }

            if (model.XYZZYXId == 0)
            {
                result.Add(new ReturnErrorItem("", "Related Vision Board Session  is not valid"));
                return result;
            }

            var entity = await GetVisionBoardSessionForWriteByIdAsync(model.VisionBoardSessionId);
            if(!entity.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Session information is not available"));
                return result;
            }

            var xYZZYX = await GetXYZZYXForWriteByIdAsync(model.XYZZYXId);
            if (!xYZZYX.IsSuccess)
            {
                result.Add(new ReturnErrorItem("", "Related XYZZYX information is not available"));
                return result;
            }

            if (entity.UserId != xYZZYX.UserId)
            {
                result.Add(new ReturnErrorItem("", "Vision Board Sessions does not belong to the same company"));
            }

            if (result.Count > 0)
            {
                return result;
            }

            return null;
        }

